export const INDICATOR_REGISTRY: Record<string, IndicatorMeta> = {
  "ECOS-01": {"id":"ECOS-01","category":"ECOS","name":"Runtime/Language EOL","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":["G3"],"definition":"The language runtime or interpreter the system runs on (e.g., Python 3.6, Node 14, Ruby 2.7, .NET Framework, PHP 7.x) is at or past its official end-of-life date.","why":"An EOL runtime receives no security patches. Any vulnerability found after EOL is permanent, and the security team has no fix to apply. It also blocks hiring (engineers won't fight an old toolchain), blocks library upgrades (new libraries drop EOL runtimes), and violates almost every compliance framework's \"supported software\" control.","manifests":"CI container images (`FROM python:3.6`), `.nvmrc`/`.ruby-version`/`.tool-versions` files, `Dockerfile` base images, runtime configs in `package.json engines`, `pyproject.toml requires-python`, deployment manifests, EOL tickers (`endoflife.date`, `python.org/dev/peps/pep-0537`).","detection":"Version matrix audit — read runtime pins and cross-check against `endoflife.date`; `pip list` / `npm ls` / `gem list` vs. current releases; container image scanners report the base OS/runtime; `docker run --rm <image> <runtime> --version`. Cross-check the system's own support window against the vendor's.","yellow":"Active version within 6 months of EOL, or on EOL but with a funded, resourced upgrade path already started.","red":"Past official EOL with extended/vendor-only support (or none), and no upgrade in progress.","yellow_rationale":"6 months is barely enough to plan+execute a runtime upgrade through QA; it's a warning, not a fire.","red_rationale":"unpatched vulnerabilities are permanent; this is a gate — see G3.","criteria":{"0":"EOL runtime in core logic (triggers G3).","1":"EOL runtime in an isolated path","2":"EOL approaching / one runtime in extended support but upgrade planned","3":"all runtimes current"},"scope":"Runtime EOL dates only; framework lifecycle/status is ECOS-08.","applicability":"`na_when: never` — every system runs on a runtime. If no pins are found, the row is `unknown`, not N/A.","statusing":"measured_when:  runtimes.len >= 1 and unmapped_pins.len == 0   # every pin resolved from the snapshot\nestimated_when: runtimes.len >= 1 and unmapped_pins.len > 0    # clamp [1,2], confidence low\nunknown_when:   zero pins found, or every pin unmappable in the snapshot (unmapped list disclosed)\nscope_limited:  partial lookup failure -> estimated + scope-limited note listing unmapped products\nclamp:          [1,2]                       # applies only in estimated branch\nconfidence:     medium (exhaustive pin surface); low if conflict unresolved","score_mapping":"Threshold values live in §3 and `model/config.md`. Predicate shapes:\n\n- `3`: `all(r.days_until_eol > YELLOW_MARGIN)` for all scored runtimes\n- `2`: `any(days_until_eol <= YELLOW_MARGIN)` or extended-support-only runtime with upgrade evidence (recent upgrade commits touching pins)\n- `1`: `any(is_past_eol)` ∧ affected runtime's pins resolve outside core paths\n- `0`: `any(is_past_eol)` ∧ runtime pin resolves in core deploy path (Dockerfile/prod CI)\nCore membership: files carrying the pin joined against computed core-path set.","fact_schema":"{\"ecos01\": {\n  \"runtimes\": [{\"product\": \"python\", \"version\": \"3.6\", \"cycle\": \"3.6\", \"pin_source\": \".tool-versions\",\n                 \"eol_date\": \"2021-12-23\", \"days_until_eol\": -1337, \"is_past_eol\": true,\n                 \"conflict_sources\": [\".tool-versions\", \"Dockerfile:FROM\"]}],\n  \"conflict\": false,\n  \"unmapped_pins\": [\"some-product@9.1\"],\n  \"lookup_ok\": true}}","budget_class":"fast","evidence":"evidence: \"eol-snapshot: {product} {version} EOL {days_until_eol}d ({pin_source})\"","remediation":{"quick_win":"document the gap, create the upgrade ticket with a date.","structural":"parallel runtime upgrade plan — run new runtime in CI behind a feature gate, migrate one service at a time, dual-run in prod. For truly stuck runtimes, isolate behind a facade and treat like a rewrite candidate.","gold_standard":"Every production runtime within its vendor-supported window; CI builds a canary job on the current runtime; a deprecation calendar exists and is reviewed quarterly.","effort":"⚡ ≤30 min"}},
  "ECOS-02": {"id":"ECOS-02","category":"ECOS","name":"Major Package Drift","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"A large fraction of direct dependencies sit one or more *major* versions behind current, or the core framework (Spring, Laravel, Rails, Angular, React, Django) is pinned to an old major.","why":"Major versions carry breaking changes that require migration work. Drift compounds: the further behind you are, the more migration steps you must chain, and each one gets harder because intermediate versions are forgotten. Drift also forecloses options — security fixes often land only in new majors.","manifests":"`package.json`, `requirements.txt`/`pyproject.toml`, `Gemfile`, `go.mod`, `Cargo.toml`, `pom.xml`/`build.gradle`, lockfiles; tool reports from `npm outdated`, `pip list --outdated`, `dependabot`/`renovate` PR history.","detection":"Dependency tree tools — `npm outdated`, `pip list --outdated`, `bundle outdated`, `go list -u -m all`, `cargo outdated`; or a Dependabot/Renovate dashboard showing how many dependency PRs have been open/ignored. Count direct deps where `major version < latest major` and `latest major - current major >= 1`. Classify by whether the drift is in core (framework, ORM, auth) or peripheral (logging, util).","yellow":"> 30% of direct deps are 1–2 majors behind.","red":"> 50% of direct deps ≥ 2 majors behind, or the core framework is more than one major behind current with no upgrade project.","yellow_rationale":"a third of the surface is drift — still manageable, but the migration debt is real.","red_rationale":"at this depth, individual upgrades stop being safe and the whole dependency graph becomes a migration project.","criteria":{"0":"core framework stuck ≥ 2 majors with no plan.","1":"core framework behind by 2 majors or > 50% drifting","2":"30–50% one major behind","3":"minor drift only"},"scope":"Single-repo major-version drift; per-service skew is ECOS-09, runtime EOL is ECOS-01.","applicability":"`na_when: zero dependency manifests AND zero lockfiles parse in an enumerated tree` (clause-b). Else applicable.","statusing":"measured_when:  direct_deps_total > 0 and resolvable_ratio >= 0.8   # resolvable = parseable major + table metadata present\nestimated_when: 0 < resolvable_ratio < 0.8      # clamp [1,2], confidence low\nunknown_when:   manifests exist but nothing resolvable (fully private ecosystem, or the whole surface is absent from the table)\nna_when:        clause-b fired\nclamp:          [1,2]\nconfidence:     medium (exhaustive manifest surface + pinned metadata table)\nscope_limited:  unresolvable > 20% -> estimated + scope-limited","score_mapping":"Y/R values: see §3.\n\n- `3`: `pct_behind_1plus < Y1` ∧ `max(core_framework_gaps.majors_behind) <= 1`\n- `2`: Yellow-band composition (`Y1 <= pct_behind_1plus < R1`)\n- `1`: `max(core_framework_gaps.majors_behind) == 2` ∨ Red-band composition without core-framework stuck state\n- `0`: `max(core_framework_gaps.majors_behind) >= 3`","fact_schema":"{\"ecos02\": {\n  \"direct_deps_total\": 87, \"unresolvable\": 3,\n  \"unresolvable_names\": [\"internal-billing-client\"],\n  \"resolvable_ratio\": 0.97,\n  \"pct_behind_1plus_major\": 34.5, \"pct_behind_2plus_major\": 12.6,\n  \"core_framework_gaps\": [{\"name\": \"django\", \"current\": \"3.2\", \"latest_major\": 5, \"majors_behind\": 2}]}}","budget_class":"fast","evidence":"evidence: \"lockfile-parse: {pct}% of {n} direct deps >=1 major behind; core gaps: {gap_list}\"\nbasis:    \"lockfile-parse: only {k}/{n} resolvable ({ratio}); drift percentages low-confidence\"","remediation":{"quick_win":"enable Dependabot/Renovate with major-update grouping and a monthly budget.","structural":"\"upgrade train\" — pick one major hop per quarter, keep intermediate commits shippable, use the dependency graph from tools to sequence hops (don't skip majors). Establish a \"never more than 1 major behind\" policy for core deps.","gold_standard":"Core framework within 1 major of current; < 30% of direct deps behind by a major; automatic update PRs flowing weekly; majors scheduled explicitly on the roadmap.","effort":"⚡ ≤30 min"}},
  "ECOS-03": {"id":"ECOS-03","category":"ECOS","name":"Abandoned / Unmaintained Libraries","tier":"B","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"Direct or deep transitive dependencies that are archived, revoked, or effectively unmaintained (no commits, no releases, no maintainer response) — yet still load-bearing.","why":"An unmaintained library is a permanent, unfixable risk: bugs and CVEs accumulate with no upstream to fix them. It also signals the codebase froze at a point in time — the ecosystem moved on, and this system didn't.","manifests":"`package.json` deps with dead GitHub repos; deprecated npm packages (`npm deprecate` flags); PyPI packages with no releases in years; archived GitHub repos (`archived: true`); Socket.dev/OpenSSF reports; libraries whose GitHub page shows \"this repository has been archived by the owner.\"","detection":"Supply-chain scanners — `socket.dev` project scan, `ossf/scorecard` (`scorecard --repo <repo>`), `osv-scanner`, `npm audit`, `pip-audit`; manual: check last release date vs. 24 months on each load-bearing dep. Distinguish *mature-stable* (maintained slowly, fine) from *abandoned* (no activity, no response to issues).","yellow":"Unmaintained for 12–24 months, or single-maintainer bus-factor-1 libraries, in peripheral modules.","red":"Unmaintained > 24 months, or repo archived, or package revoked/unpublished, in *core* logic or on the auth/data path.","yellow_rationale":"still a warning window — fork or replace before it compounds.","red_rationale":"this is now permanent unpatched risk in the most sensitive code.","criteria":{"0":"abandoned lib in core/auth/data path.","1":"abandoned lib in a non-critical service or recent","2":"abandoned libs in peripheral code with replacement planned","3":"all maintained"},"scope":"Abandoned-lib maintenance risk only; malware/provenance risk is ECOS-10, license posture is ECOS-05.","applicability":"same as ECOS-02 (no manifests/lockfile → N/A clause-b).","statusing":"measured_when:  load_bearing_total > 0, resolvable_ratio >= 0.7, and the import scan is not truncated\nestimated_when: 0 < resolvable_ratio < 0.7, OR the source-import scan was truncated   # clamp [1,2], confidence low\nunknown_when:   no lockfile (floating install -> abandonment unknowable per-version); no load-bearing dependency; or every load-bearing dep unresolvable against the table\nna_when:        ECOS-02 applicability fired\nclamp:          [1,2]\nconfidence:     medium (exhaustive lockfile surface); low on partial resolvability / truncation\nscope_limited:  partial resolvability or truncated import scan -> estimated + scope-limited","score_mapping":"- `3`: `abandoned.len == 0`\n- `2`: only peripheral abandoned with `12 <= months <= Y_MONTHS` or bus-factor-1 flags (Y/R values: see §3)\n- `1`: abandoned in isolated/non-critical service path, or recent abandonment (<12mo)\n- `0`: `any(abandoned where in_core_path ∧ (archived ∨ months > R_MONTHS))`","fact_schema":"{\"ecos03\": {\n  \"load_bearing_total\": 142,\n  \"abandoned\": [{\"name\": \"pdfkit\", \"version\": \"1.2.3\", \"months_since_release\": 30, \"archived\": false, \"in_core_path\": false}],\n  \"bus_factor_1_count\": 0,\n  \"unresolvable\": 2,\n  \"unresolvable_names\": [\"internal-sdk\"],\n  \"resolvable_ratio\": 0.986}}","budget_class":"fast","evidence":"evidence: \"lockfile-parse+snapshot: {k}/{n} load-bearing deps unmaintained; worst: {name} last release {months}mo\"\nbasis:    \"lockfile-parse: only {k}/{n} deps resolvable against the metadata table (low confidence)\"","remediation":{"quick_win":"audit the dependency surface for abandoned libs and create a removal/swap ticket with a date.","structural":"replace load-bearing abandoned libs with maintained alternatives or fork-and-own with a maintenance budget; pin to the exact version and wrap it behind your own interface so it's swappable.","gold_standard":"Every load-bearing dependency either actively maintained or deliberately forked-and-owned; a quarterly \"library health\" review is on the calendar; no archived repos in the dependency surface.","effort":"⚡ ≤30 min"}},
  "ECOS-04": {"id":"ECOS-04","category":"ECOS","name":"Deprecated API Usage","tier":"B","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The codebase calls APIs the upstream ecosystem has formally deprecated, removed, or replaced — compiler deprecation warnings, deprecated framework methods, removed stdlib functions, or documented \"do not use\" surfaces.","why":"Deprecation warnings are the ecosystem telling you exactly where your code will break next. Ignoring them means every dependency upgrade becomes a surprise; the code accumulates friction and loses compatibility, and it's a leading indicator that the code has been \"touched less than the world moved.\"","manifests":"Compiler/linter output (`DeprecationWarning`, `@deprecated`, `#[deprecated]`, ESLint `no-deprecated-api`), language build logs, framework upgrade guides (e.g., Django removal timelines, Rails `deprecated_columns`, Angular deprecation list), IDE warnings, docs.","detection":"Static analysis — compile with warnings-as-errors or `-Werror` in a canary build; AST/deprecation linters (`flake8-deprecated`, `eslint-plugin-deprecation`, `@deprecated` grep); framework's own deprecation checks (e.g., `django.checks`); grep for known-removed APIs from upgrade guides. Count warnings; classify by module.","yellow":"Deprecated APIs used in non-critical modules, with warnings suppressed or ignored.","red":"Core business logic depends on deprecated or already-removed APIs, or calls APIs removed in the *next* LTS version of the framework.","yellow_rationale":"warning-level risk — it will bite on the next upgrade but is not an emergency.","red_rationale":"the next upgrade is blocked, and removed APIs often have security implications.","criteria":{"0":"removed APIs already in use in core logic.","1":"warnings in core, or in modules that will break next LTS","2":"warnings in peripheral code","3":"no warnings"},"scope":"Deprecated API calls in code; version drift is ECOS-02, framework support status is ECOS-08.","applicability":"`na_when: no source files of any gated language detected in an enumerated tree`. Else applicable.","statusing":"measured_when:  never auto-measured            # signal quality is ecosystem-dependent -> always labeled inference\nestimated_when: lint_ran == true               # clamp [1,2], confidence medium if type-aware run, else low\nunknown_when:   lint could not run (language unsupported or parse failure)\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when type-aware analysis completed; low for grep-class runs\nscope_limited:  output cap hit -> estimated + scope-limited","score_mapping":"Threshold values: see §3. Estimated ⇒ score ∈ {1,2} only:\n\n- `2`: `warning_total > 0` ∧ `warnings_in_core == 0`\n- `1`: `warnings_in_core > 0` ∨ `removed_api_hits.len > 0` (next-LTS breakage risk)\n- `3`/`0` unreachable by construction (certainty claims not allowed on estimated rows)","fact_schema":"{\"ecos04\": {\n  \"warning_total\": 213,\n  \"warnings_in_core\": 41,\n  \"removed_api_hits\": [{\"symbol\": \"django.utils.functional.allow_tags\", \"file\": \"app/views.py\"}],\n  \"lint_ran\": true, \"tool_version\": \"eslint 8.57\"}}","budget_class":"slow-dissolvable","evidence":"basis: \"eslint-deprecation: {n} warnings ({k} in core); {m} next-LTS removal hits\"","remediation":{"quick_win":"turn deprecation warnings into a CI-visible report (not silent); fix the 20 highest-value warnings.","structural":"treat deprecation debt like feature debt — a quarterly \"modernize the deprecated surface\" slice; keep the target version's removal list as a tracked checklist.","gold_standard":"Zero deprecation warnings in the core module build; a CI gate that fails (or reports) on new deprecation warnings; removal timelines tracked.","effort":"⚡ ≤30 min"}},
  "ECOS-05": {"id":"ECOS-05","category":"ECOS","name":"License Compliance Risk","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":["G8"],"definition":"Dependency licenses are unknown, ambiguous, or incompatible with how the codebase is distributed — with special danger from copyleft licenses (GPL/AGPL) in proprietary closed-source software.","why":"Licensing problems are a *quiet* form of debt that surfaces only at acquisition, audit, or legal review — the worst possible time. An obsolete codebase often has an undisciplined dependency history, which is exactly how unknown-license and copyleft packages sneak in.","manifests":"`package.json`/lockfiles with no `license` field, libraries with custom/unclear licenses (WTFPL, CC-BY-NC, \"BSD without notice\"), GPL/AGPL-licensed packages in a closed-source product, vendored code with licenses stripped, missing `NOTICE`/`THIRD_PARTY_LICENSES` files.","detection":"SBOM generation (`syft`, `bom`, `cyclonedx-cli`) + license scanning (`fossa`, `snyk`, `license-checker`, `pip-licenses`), `github/licensee`, `npx license-checker-rseidelsohn`. Generate an SBOM, classify each license, flag unknown/missing/copyleft.","yellow":"Unknown or ambiguous licenses present in transitive dependencies; no SBOM generated.","red":"Copyleft licenses (GPL/AGPL) detected in a proprietary, closed-source distribution, or vendored copyleft code without notice.","yellow_rationale":"mostly discoverable and fixable, but the discovery tooling is missing — that's the warning.","red_rationale":"this can force source release or trigger legal exposure — an exit-blocking defect.","criteria":{"0":"copyleft/unknown in distributed closed-source product.","1":"unknown licenses or a copyleft dep in peripheral code","2":"no SBOM but licenses look clean","3":"SBOM + compliant"},"scope":"License classification and SBOM content; provenance/attestation is ECOS-10.","applicability":"`na_when: ECOS-02 clause-b fired` (no manifests → nothing to license). Else applicable.","statusing":"measured_when:  an SBOM-class scan completes over the enumerated tree and packages_total > 0   # not reachable in the offline release (direct-dep table only)\nestimated_when: direct-dep license table with >=1 license classified                            # clamp [1,2], confidence low; the release's default\nunknown_when:   zero packages discovered in a tree that has source files, or none of the direct deps covered by the table\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     low (direct-dep surface only; transitive licenses need the unshipped SBOM path)\nscope_limited:  license_unknown_count > 0 -> estimated + scope-limited","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: `license_unknown_count == 0` ∧ `copyleft_strong.len == 0` ∧ `sbom_present_in_repo`\n- `2`: clean licenses ∧ `sbom_present_in_repo == false`\n- `1`: `license_unknown_count > 0` ∨ copyleft only in dev/peripheral scope\n- `0`: `any(copyleft_strong ∧ closed_source_distribution_likely)` → also drives G8","fact_schema":"{\"ecos05\": {\n  \"packages_total\": 412, \"license_unknown_count\": 9,\n  \"license_unknown_names\": [\"internal-billing-client\"],\n  \"copyleft_strong\": [{\"name\": \"libfoo\", \"version\": \"1.2\", \"license\": \"GPL-3.0\", \"direct\": true}],\n  \"copyleft_weak_count\": 2,\n  \"sbom_present_in_repo\": false, \"ci_license_gate_present\": false,\n  \"closed_source_distribution_likely\": true}}","budget_class":"slow-dissolvable","evidence":"evidence: \"lockfile-parse: {n} direct deps; {u} unknown licenses; strong copyleft in {names} ({paths})\"","remediation":{"quick_win":"generate an SBOM (`syft . > sbom.json`), wire it into CI, publish attribution files.","structural":"add a license gate to CI (fail on GPL in closed-source), replace copyleft deps, retire unknown-license packages, review vendored code for stripped notices.","gold_standard":"SBOM generated and attested on every release; license policy enforced in CI; zero unknown licenses; copyleft list reviewed quarterly and signed off.","effort":"🔶 ~2–4 h"}},
  "ECOS-06": {"id":"ECOS-06","category":"ECOS","name":"Dependency Bloat","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The dependency graph is inflated — hundreds/thousands of transitive packages, dozens of unused direct dependencies, multiple packages doing the same job, or full libraries pulled in for one function.","why":"Dependency count is a proxy for attack surface, build time, and cognitive load. Modern practice trends toward smaller, composable, tree-shaken dependency surfaces. A bloated graph is also a smell that the codebase accreted rather than was designed — a hallmark of legacy.","manifests":"Lockfiles with huge transitive counts (`npm ls --all`), `package.json` unused deps, `go mod why`, duplicates (`npm dedupe` output, `pipdeptree` showing the same lib 3 versions), bundle analysis (webpack/rollup reports), monorepo node_modules sprawl.","detection":"Tree inspection — `npm ls --prod`, `pipdeptree`, `bundle list`, `go mod graph | wc -l`, `cargo tree`; dead-dep detectors (`depcheck`, `knip` for unused); duplicate detection (`npm dedupe --dry-run`, `pipdeptree -d` showing dupes); bundle analyzers (`webpack-bundle-analyzer`). Count: total transitive deps, unused direct deps, duplicated packages.","yellow":"100–300 transitive deps, or > 20% unused direct deps, in a mostly-clean graph.","red":"> 300 transitive deps, or orphaned deps that can't be removed (feature flagged forever), or duplicated versions of security-critical libs.","yellow_rationale":"still shippable, but the attack surface and maintenance drag are above modern norms.","red_rationale":"at this size the graph is un-auditable and upgrades break something every time.","criteria":{"0":"un-auditable graph with orphaned security-critical duplicates.","1":"> 300 or heavy duplication","2":"100–300 transitive with some unused","3":"lean, within budget"},"scope":"Dependency graph size/dupes; unused code in modules is ARCH-04, supply-chain exposure is ECOS-10.","applicability":"ECOS-02 clause-b. Else applicable.","statusing":"measured_when:  >=1 lockfile parsed            # transitive totals + duplicate version sets are exhaustive parsed facts\nestimated_when: never in this build            # the unshipped unused-direct sub-signal is reported null, not estimated\nunknown_when:   no lockfile (transitive counts unknowable)\nna_when:        applicability fired\nclamp:          [1,2]                          # n/a — measured-only row in this build\nconfidence:     medium (exhaustive lockfile surface)\nscope_limited:  no trigger in this build (the lockfile surface has no read bound)","score_mapping":"Thresholds Y/R: see §3.\n\n- `3`: `transitive_total < Y_TRANS` ∧ `duplicates.len == 0`\n- `2`: Yellow band (`Y_TRANS <= transitive <= R_TRANS`); the unused-direct fraction cannot contribute in this build (sub-signal absent, `null`)\n- `1`: `transitive > R_TRANS` ∨ heavy duplication without security-critical overlap\n- `0`: `duplicate_security_critical == true`","fact_schema":"{\"ecos06\": {\n  \"transitive_total\": 1403,\n  \"direct_unused\": [],\n  \"pct_direct_unused\": null,\n  \"duplicates\": [{\"name\": \"lodash\", \"versions\": [\"4.17.15\", \"4.17.21\"]}],\n  \"duplicate_security_critical\": true,\n  \"lockfiles_parsed\": 2}}","budget_class":"fast","evidence":"evidence: \"lockfile-parse: {t} transitives across {k} lockfiles; {d} duplicate package versions\"","remediation":{"quick_win":"run `knip`/`depcheck`, remove unused direct deps, enable `npm dedupe`/lockfile optimization in CI.","structural":"set a budget (e.g., \"no net-new transitive deps without review\"), replace kitchen-sink libs with narrow ones, dedupe semver ranges, and periodically prune.","gold_standard":"Transitive count within a declared budget; zero unused direct deps; single version of every critical lib; dependency review is part of code review.","effort":"⚡ ≤30 min"}},
  "ECOS-07": {"id":"ECOS-07","category":"ECOS","name":"Build Reproducibility & Lockfile Integrity","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The build is not reproducible or not pinned: no lockfile, floating/mutable version ranges, builds that differ between machines/times, or a lockfile that is ignored or unmaintained.","why":"Reproducibility is the foundation of trust — for security (you don't know what you shipped), for debugging (prod ≠ local), and for reliability (the build that worked Friday may fail Monday). Its absence is a hallmark of an era before supply-chain discipline, and it blocks almost every modernization step (safe upgrades, CI caching, SBOMs, canary rollouts).","manifests":"No `package-lock.json`/`yarn.lock`/`poetry.lock`/`Gemfile.lock`/`go.sum`/`Cargo.lock` committed; `requirements.txt` without pins; version ranges (`>=1.0,<2`) in manifests; CI that does fresh installs into mutable registries; Docker builds without `--immutable`/`--frozen-lockfile`; builds that pull latest (`@latest`, `latest` tags).","detection":"File audit — check for committed lockfiles in git (`git ls-files | grep lock`), `npm ci`/`pip install -r` vs. `npm install`, CI logs for \"added X packages\" churn; reproducibility test: build twice in clean containers and diff output hashes; `npm shrinkwrap` diff; registry-pin checks (`--registry`, integrity hashes in lockfile v2/v3).","yellow":"Lockfile present but stale/partial, or immutable-install not enforced in CI.","red":"No lockfile at all, floating ranges in prod-critical deps, or CI installs mutably from a live registry with no integrity pins.","yellow_rationale":"a stale lockfile is worse than none — false confidence with drift.","red_rationale":"you cannot know what you shipped — a supply-chain and reliability blind spot.","criteria":{"0":"no lockfile, floating ranges, mutable installs in core path.","1":"lockfile absent in some services","2":"lockfile but stale or not enforced","3":"lockfile + immutable CI + reproducible"},"scope":"Lockfile presence and build reproducibility; registry/provenance hardening is ECOS-10.","applicability":"`na_when: zero manifests of any kind` → unknown, never N/A (a build exists even unpinned). Actually: clause-b N/A when tree contains zero build/config files at all (docs-only repo).","statusing":"measured_when:  >=1 manifest detected            # presence/absence of lockfile is itself the fact\nestimated_when: never                             # this row is fully decidable statically\nunknown_when:   zero build/config files AND zero manifests (clause-b -> na instead) or tree un-enumerable\nna_when:        docs-only/no-build tree (clause-b, reason recorded)\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium; low when git history is unavailable (staleness dropped)","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: all ecosystems locked ∧ stale=false ∧ `ci_immutable_install.enforced`\n- `2`: locked ∧ (`stale` ∨ ¬enforced)\n- `1`: some services/dirs locked, others not (multi-manifest partial coverage)\n- `0`: no lockfile for a prod manifest ∨ `pin_ratio < R_PIN%` ∨ mutable CI installs on prod path\n\nMechanism-absent ecosystems (`lockfile_mechanism_absent`: Maven, classic NuGet) are exempt from the missing-lockfile limb of `0` — absence is structural; their pin ratio carries the reproducibility judgment.","fact_schema":"{\"ecos07\": {\n  \"lockfiles\": [{\"path\": \"packages.lock.json\", \"ecosystem\": \"csharp\", \"stale\": false, \"integrity_hashes\": true, \"packages\": 42}],\n  \"lockfile_mechanism_absent\": [\"csharp:packages.config\"],\n  \"pin_ratio\": 96.2,\n  \"ci_immutable_install\": {\"enforced\": true, \"evidence\": \".github/workflows/ci.yml:31 npm ci\"},\n  \"mutable_install_sites\": []}}","budget_class":"fast","evidence":"evidence: \"lockfile-parse: lockfile={present|absent} ({paths}); pin_ratio={p}%; ci={'npm ci' @ ci.yml:31}\"\nbasis:    \"lockfile-parse: no lockfile mechanism for {ecosystems} — absence is structural\"","remediation":{"quick_win":"commit the lockfile, switch CI to `npm ci`/`pip install --require-hashes`/`--frozen-lockfile`, add a \"lockfile up-to-date\" CI check.","structural":"adopt content-hash pinning, build from clean containers, produce provenance attestations (SLSA level 1→2), verify registry integrity.","gold_standard":"Lockfile committed and current; CI immutable install; two clean builds produce byte-identical artifacts; SLSA provenance generated per release.","effort":"⚡ ≤30 min"}},
  "ECOS-08": {"id":"ECOS-08","category":"ECOS","name":"Framework Lock-in & Monoculture Risk","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The system is deeply locked to a framework/ecosystem whose maintenance status is declining, whose roadmap is hostile or migrating away, or where the org's options are foreclosed (e.g., a bespoke fork, a dead vendor, or a proprietary dependency you can't exit).","why":"Lock-in itself isn't debt — *dying* lock-in is. When the framework you bet on stops evolving (or its community migrates), the codebase becomes progressively harder to staff, secure, and extend. This indicator separates \"old but fine\" from \"obsolete.\"","manifests":"Framework status pages (AngularJS EOL, jQuery, Spring Framework lifecycle, Laravel, Django support policy), vendor announcements (SaaS/PAAS framework retirements), community exodus signals (Stack Overflow trends, job postings, contributor decline), custom forks of OSS that must be maintained in-house, license changes that foreclose use.","detection":"Lifecycle audits — framework official support matrix; `endoflife.date`; contributor/release cadence (GitHub `commits since`); internal \"how stuck are we\" test: `how hard is a 1-line change to the framework?`; check org skill availability (jobs, interviews); vendor dependency review (single-vendor lock for core).","yellow":"Framework in maintenance mode, or community clearly migrating, while the org still has a migration path.","red":"Framework is EOL, vendor-retired, or license-change-foreclosed, with core logic coupled to it and no viable migration path.","yellow_rationale":"this is the time to plan the exit, while the path is cheap.","red_rationale":"the platform is sinking under the codebase; this is a rewrite driver.","criteria":{"0":"EOL/retired framework in core logic with no path (overlaps G3).","1":"EOL-ish framework in isolated module","2":"maintenance mode, exit plan exists","3":"framework current/supported"},"scope":"Framework lifecycle and lock-in; runtime EOL is ECOS-01, code-style generation gap is ARCH-06.","applicability":"`na_when: no framework-class dependency detected` (clause-b over parsed manifests — a pure stdlib/CLI repo). Else applicable.","statusing":"measured_when:  frameworks.len > 0 and support lookup succeeded\nestimated_when: coupling_share computed on partial import graph   # clamp [1,2], confidence low\nunknown_when:   framework present but no support data (niche/vendor framework)\nna_when:        applicability fired (no framework deps)\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  none typical","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: all frameworks `active`\n- `2`: any `maintenance` ∧ `facade_layer_detected ∨ migration_evidence` (upgrade commits/branches)\n- `1`: any `eol` framework confined to non-core module set\n- `0`: `any(support_status == eol)` ∧ `coupling_share > R_COUPLING` ∧ ¬facade → co-fires G3 evaluation","fact_schema":"{\"ecos08\": {\n  \"frameworks\": [{\"name\": \"angularjs\", \"version\": \"1.8.3\", \"support_status\": \"eol\", \"eol_date\": \"2021-12-31\"}],\n  \"coupling_share\": 0.62,\n  \"facade_layer_detected\": false,\n  \"fork_pinned\": false}}","budget_class":"fast","evidence":"evidence: \"endoflife.date+import-graph: angularjs 1.8.3 eol since 2021-12-31; coupling {p}% ({k} files), no facade\"","remediation":{"quick_win":"quantify the coupling (which modules touch framework-specific APIs directly) and freeze scope on framework-dependent features.","structural":"extract the framework behind a facade at the boundaries (ports & adapters), migrate incrementally module-by-module on the critical path, keep the system runnable through the whole migration.","gold_standard":"Framework either current-and-supported, or the core logic is framework-independent behind an interface with an active migration plan.","effort":"⚡ ≤30 min"}},
  "ECOS-09": {"id":"ECOS-09","category":"ECOS","name":"Version Skew Across Services","tier":"A","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"PART","rollup":"deep-dive","gates":[],"definition":"In a multi-service system, the same dependency/framework exists at many different major versions across services (e.g., service A on Python 3.9, service B on 3.12; shared libraries at 3 different majors), with no coordinated upgrade strategy.","why":"Skew means the \"system\" has no coherent platform — every service is a snowflake with its own dependency museum. It multiplies upgrade effort (one fix, N upgrades), blocks shared tooling, and signals that the org has no platform discipline. It's the system-level echo of ECOS-02.","manifests":"Cross-repo version manifests, dependency dashboards, `renovate`/`dependabot` aggregated reports, internal platform teams' inventory, container registry image tags showing runtime variety.","detection":"Aggregate manifests across repos (script it: grep `FROM | python-version | framework version` across repos), use a central platform inventory, run a single dependency scan across the org's repos and diff versions by service; count distinct majors per load-bearing dependency.","yellow":"2–3 majors of a core dependency in flight, with a shared upgrade backlog.","red":"Core dependency at 3+ distinct majors, or runtimes so varied that shared tooling/CI can't support them.","yellow_rationale":"tolerable drift, but it already costs you in shared fixes.","red_rationale":"you're maintaining N platforms, not one — every security fix is multiplied.","criteria":{"0":"divergent snowflakes with no platform baseline.","1":"three majors with no coordination","2":"two majors in flight with a plan","3":"uniform"},"scope":"Per-service version skew only; single-repo major drift is ECOS-02.","applicability":"`na_when: single-service layout detected (one root manifest set, no sibling service dirs)` → N/A clause-b. `unknown_when: multi-service but manifests live in other repos` (org plane unreachable from URL).","statusing":"measured_when:  >=2 service roots and >=80% roots yielded parseable pins\nestimated_when: partial root coverage                                    # clamp [1,2], confidence low\nunknown_when:   multi-service suspected but manifests outside repo scope\nna_when:        single-service layout (clause-b)\nclamp:          [1,2]\nconfidence:     medium within monorepo","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: `all(max_distinct_majors.count == 1)`\n- `2`: `max(count) == 2` ∧ coordinated-upgrade evidence (shared bump commit across roots)\n- `1`: `max(count) == 3`\n- `0`: `max(count) > 3` ∨ no reference-version convergence","fact_schema":"{\"ecos09\": {\n  \"service_roots\": [\"services/api\", \"services/worker\"],\n  \"skew\": [{\"dep\": \"python\", \"majors\": [\"3.9\", \"3.12\"], \"services_on_reference\": 0.5}],\n  \"max_distinct_majors\": {\"dep\": \"django\", \"count\": 3}}}","budget_class":"slow-dissolvable","evidence":"basis: \"monorepo-scan: django at 3 majors across {n} services; {p}% on reference\"","remediation":{"quick_win":"inventory the skew, pick a \"platform baseline\" version, and make new work use it.","structural":"establish a platform/boilerplate team with a version cadence; migrate oldest-first on the critical path; add cross-service tests for the shared contract; sunset divergent majors with deadlines.","gold_standard":"One supported major of every core dependency per system; upgrade cadence managed centrally; a new service starts on the platform baseline.","effort":"🔷 ~1–2 days"}},
  "ECOS-10": {"id":"ECOS-10","category":"ECOS","name":"Supply-Chain: Typosquatting, Malware, & Registry Risk","tier":"B","default_status":"measured","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"Deep exposure to malicious packages (typosquatting, dependency-confusion, hijacked/malware packages), or the org has no defense in depth (no signature verification, no registry pinning, no provenance checks, no OpenSSF hygiene) across the dependency graph.","why":"This is the *newest* axis of debt. An obsolete codebase predates supply-chain tooling entirely, so it usually has none. If you can't attest where your code comes from, you're running a modern system with 2016-era supply-chain hygiene.","manifests":"Lockfiles with suspiciously-named packages, private-registry name collisions, packages with `mvnrepository`-style confusion, GitHub Actions pinned to tags not SHAs, no `OpenSSF Scorecard` run, no `Socket.dev`/`OSV` scan in CI, unverified registry endpoints, ad-hoc `curl | bash` installs.","detection":"Deep SCA — `socket.dev` (malware/typosquatting/provenance), `openssf/scorecard`, `osv-scanner`, `npm audit --parseable` cross-referenced, `pip-audit`, `trivy --scanners vuln,secret`; manual: check suspicious package names (one-char diffs), release provenance, maintainer accounts; audit GitHub Actions for tag-pinned third-party actions.","yellow":"Scorecard 5–7, no malware found, but no provenance verification and actions pinned to tags.","red":"Known malware/hijacked package in the lockfile, or scorecard < 5 with zero supply-chain scanning anywhere.","yellow_rationale":"no active infection but no defense either.","red_rationale":"active or credible infection risk with no visibility — treat as incident-level.","criteria":{"0":"malware/hijack suspected or confirmed.","1":"no scanning, tag-pinned actions","2":"scanning present, pins loose","3":"scorecard ≥ 8 + provenance"},"scope":"Malware/provenance/CI-action risk; abandoned-lib risk is ECOS-03, license posture is ECOS-05.","applicability":"ECOS-02 clause-b. Else applicable.","statusing":"measured_when:  >=2 of {scorecard, osv, actions-audit} succeeded\nestimated_when: only 1 signal available                                  # clamp [1,2], confidence low\nunknown_when:   all remote signals failed (rate-limit/private)\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  private registries unauditable -> estimated + scope-limited","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: `scorecard_score >= R_SC` ∧ `actions_unpinned == 0` ∧ provenance present\n- `2`: scan present ∧ no malware ∧ pins loose\n- `1`: no scanning anywhere ∧ tag-pinned actions ∧ no malware found\n- `0`: `malware_advisories.len > 0` ∨ `typosquat_suspects in prod deps`","fact_schema":"{\"ecos10\": {\n  \"scorecard_score\": 6.4,\n  \"malware_advisories\": [],\n  \"typosquat_suspects\": [{\"name\": \"requestss\", \"near\": \"requests\", \"distance\": 1}],\n  \"actions_unpinned\": 7, \"actions_total\": 12,\n  \"provenance_config_present\": false}}","budget_class":"slow-dissolvable","evidence":"evidence: \"scorecard {s}/10; osv malware=0; actions SHA-pinned {k}/{n}; typosquat suspects {list}\"","remediation":{"quick_win":"run socket.dev/scorecard immediately, pin all CI actions to SHAs, enable `--lockfile` integrity and verified-publisher checks, scan for squat-named packages.","structural":"registry pinning, SBOM + provenance attestation (SLSA), private registry mirror with scanning, incident runbook for a compromised package, least-privilege CI tokens.","gold_standard":"Scorecard ≥ 8, all actions SHA-pinned, provenance verified per release, malware scan wired into CI as a gate, squatted-name watchlist.","effort":"🔷 ~1–2 days"}},
  "ARCH-01": {"id":"ARCH-01","category":"ARCH","name":"Cognitive Complexity & God Classes","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Methods, classes, and modules exceed sane complexity budgets — deeply nested branches, methods doing many things, \"God Classes\" absorbing unrelated responsibilities, files that are thousands of lines long.","why":"Complexity is the root tax on every other activity: tests are harder to write, bugs harder to reason about, refactors riskier, onboarding slower. High complexity correlates strongly with defect density and is the classic signature of code that accreted without design pressure.","manifests":"Large files, methods with many `if`/`else`/`for`/`while`/`catch` levels, classes with many fields/methods (God Classes), `God object` smells, deeply nested conditionals, methods with 10+ branches.","detection":"Static analysis — SonarQube/SonarCloud cognitive complexity, CodeClimate maintainability, `radon` (Python `cc`), `eslint complexity`/`cognitive-complexity`, `lizard`, `jscpd`; IDE metrics; grep for file LOC. Compute max/mean method complexity per module; flag modules in the top decile.","yellow":"Method complexity 15–30, classes 500–2,000 LOC, complexity concentrated in a few known files.","red":"Method complexity > 30, classes > 2,000 LOC, or God Classes in core domain logic.","yellow_rationale":"above SonarQube's default acceptable line but still refactorable in place.","red_rationale":"these units are no longer safely modifiable — tests are effectively impossible; defect rate is structurally high.","criteria":{"0":"core domain logic is unmodifiable God Classes.","1":"God Class in an isolated core path","2":"offenders in non-core modules","3":"within budgets"},"scope":"Pure size/complexity of units; duplication that inflates size is scored under ARCH-08 — only shape counted here.","applicability":"`na_when: zero source files in any supported language` (clause-b, enumerated tree). Else applicable.","statusing":"measured_when:  methods_analyzed >= MIN_SAMPLE (50) and analyzer exit clean\nestimated_when: sampled subset only (budget dissolve)          # clamp [1,2], confidence low\nunknown_when:   no supported-language source parsed\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium (full deterministic static pass)\nscope_limited:  >MAX_FILES truncated -> estimated + scope-limited","score_mapping":"Y/R values (complexity 15/30, class LOC 500/2000): see §3.\n\n- `3`: `pct_over_Y <= Y_PCT` ∧ no god classes\n- `2`: offenders present, all outside core paths\n- `1`: god-class or >R-complexity method touching an isolated core path\n- `0`: core domain logic dominated by R-band units (`core_offenders_ratio > R_RATIO`)","fact_schema":"{\"arch01\": {\n  \"methods_analyzed\": 4820,\n  \"pct_over_Y\": 4.2,\n  \"top_offenders\": [{\"file\": \"app/orders.py\", \"fn\": \"process\", \"ccn\": 38, \"loc\": 912}],\n  \"god_classes\": [{\"file\": \"OrderManager.java\", \"loc\": 2340}],\n  \"file_loc_p95\": 480}}","budget_class":"slow-dissolvable","evidence":"evidence: \"lizard {ver}: {k} methods >{Y}; worst {file}:{fn} ccn={c}; {g} god classes\"","remediation":{"quick_win":"carve the top 5 offenders by automated extract-method (IDE-assisted, with tests), add a complexity budget to CI (`eslint max-complexity`, SonarQube gate).","structural":"a structured decomposition of God Classes by responsibility; strangle complexity behind facades; pair the two riskiest files on a refactor sprint.","gold_standard":"Complexity budget enforced in CI; max method complexity < 15; no file > 1,000 LOC; the top-decile complexity list is shrinking and tracked.","effort":"🔶 ~2–4 h"}},
  "ARCH-02": {"id":"ARCH-02","category":"ARCH","name":"Coupling & Cohesion","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Modules are highly interdependent (coupling) and/or each module bundles many unrelated responsibilities (low cohesion). The system behaves like a plate of tangled spaghetti rather than a set of deep, single-purpose modules.","why":"Low cohesion/high coupling is the anti-thesis of maintainability: changes ripple, nothing is replaceable in isolation, and modernization becomes all-or-nothing. It's the architectural fingerprint of a codebase that grew by addition.","manifests":"Modules importing from many unrelated modules, services reaching into other services' internals, a \"utils\" module everyone depends on, god modules, shared DTOs across everything, hidden dependencies via globals.","detection":"Dependency Structure Matrix (DSM) via Lattix/Structure101, dependency analysis via `jdepend`/`arc42`, ArchUnit, `dependency-cruiser` (JS/TS), `python-dependency-inspector`; manual: import/require graph analysis; measure per-module fan-in/fan-out; detect cycles (ARCH-03) as a symptom.","yellow":"Cyclic dependencies present between submodules; a growing central hub; several modules with fan-out > 20.","red":"Circular dependencies across bounded contexts, or services sharing DBs/tables directly, or one omnipresent \"everything\" module everyone imports.","yellow_rationale":"warning-level — you can still reason about it, but ripples are starting.","red_rationale":"no module is independently changeable; this blocks any incremental modernization.","criteria":{"0":"DB-coupled services / omnipresent hub.","1":"cycles across core modules","2":"cycles in peripheral modules","3":"clean, enforced boundaries"},"scope":"Intra-module coupling/cohesion; inter-service & DB coupling belongs to DATA-02 and API-03 — not here.","applicability":"`na_when: <2 modules or no importable structure` (single-file scripts, clause-b).","statusing":"measured_when:  graph built with native tooling\nestimated_when: fallback regex importer used                      # clamp [1,2], confidence low\nunknown_when:   language unsupported and no imports parseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium native / low fallback\nscope_limited:  monorepo >N roots sampled -> estimated + scope-limited","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: `cycles.len == 0` ∧ no omnipresent hub (`max_fan_in < Y_FANIN`)\n- `2`: cycles present, all within single bounded context / peripheral\n- `1`: cycles crossing core module groups\n- `0`: `db_shared_across_services` ∨ hub imported by >R_HUBSHARE of modules","fact_schema":"{\"arch02\": {\n  \"modules\": 64, \"cycles\": [{\"members\": [\"a\", \"b\", \"c\"], \"crosses_bounded_context\": true}],\n  \"hub_modules\": [{\"name\": \"shared-utils\", \"fan_in\": 51}],\n  \"cross_service_imports\": 7,\n  \"db_shared_across_services\": true}}","budget_class":"slow-dissolvable","evidence":"evidence: \"depgraph: {m} modules, {c} cycles ({worst}); hub '{hub}' fan_in={f}; cross-service={x}\"","remediation":{"quick_win":"draw the DSM, pick the 3 highest-fan-in hubs, wrap them behind interfaces and shrink their API.","structural":"define bounded contexts and enforce them with ArchUnit-style rules in CI; extract the shared hub into a stable, narrow contract; invert dependencies toward stable abstractions.","gold_standard":"Acyclic dependency graph at the module boundary; every module has narrow, explicit dependencies; teams can change their module without coordination (tested via a chaos week).","effort":"🔶 ~2–4 h"}},
  "ARCH-03": {"id":"ARCH-03","category":"ARCH","name":"Layer & Boundary Violations","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Architectural layers (presentation → application → domain → infrastructure, or bounded contexts) are routinely crossed in the wrong direction: UI code touching the DB, domain logic in controllers, services importing each other's internals, business rules in views or stored procedures.","why":"Eroded boundaries mean the architecture exists only in theory. Once rules don't live where they should, nothing can be reasoned about, tested in isolation, or swapped — the system reverts to \"everything depends on everything\" and every boundary enforcement is gone.","manifests":"Controllers with business logic, domain objects with persistence concerns, UI layer with SQL, services reaching into other services' DBs, stored procedures containing business rules, `#pragma`/`module` hacks, layered module that doesn't exist on disk.","detection":"Architecture enforcement tools — ArchUnit/NetArchTest/ArchUnitNET (Java/.NET), `dependency-cruiser` with rules (JS/TS), `import-linter` (Python), `yapf`+ custom lints, SonarQube architecture rules; manual: a 30-min tour of one vertical slice tracing UI→logic→persistence to check direction. Run existing rule tests (if none exist, that's itself a finding).","yellow":"Occasional boundary crossings that reviewers miss; no architecture tests enforcing rules.","red":"System-wide boundary erosion — UI/controllers do persistence, business rules live in stored procedures, or no architecture enforcement exists *and* the drift is visible in a quick tour.","yellow_rationale":"violations are currently luck-based — the guard is missing.","red_rationale":"the architecture is nominal only; treat as structural debt.","criteria":{"0":"systemic erosion, architecture nominal.","1":"violations in core slices","2":"occasional violations, no guard yet","3":"boundaries enforced"},"scope":"Direction of layer boundaries only; wire-protocol legaciness lands in API-06 and DATA-02.","applicability":"`na_when: no layered structure inferable (flat scripts, <2 layers)` clause-b.","statusing":"measured_when:  native rule pack ran (project-owned or engine default on parseable tree)\nestimated_when: heuristic-only layering (Go/Java fallback)      # clamp [1,2], confidence low\nunknown_when:   no structure parseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when guard_present or conventions clean\nscope_limited:  sampled dirs -> estimated + scope-limited","score_mapping":"Criteria: see §3.\n\n- `3`: `guard_present` ∧ `violations == 0`\n- `2`: `¬guard_present` ∧ violations few & peripheral (\"luck-based\" state)\n- `1`: `violations_in_core > 0` in isolated slices\n- `0`: systemic erosion: `ui_persistence_hits.len >= R_UI` ∨ business-rules-in-stored-procs detected ∨ core-wide violations","fact_schema":"{\"arch03\": {\n  \"guard_present\": false,\n  \"rule_pack\": \"engine-default\",\n  \"violations\": 23,\n  \"violations_in_core\": 5,\n  \"ui_persistence_hits\": [{\"file\": \"routes/invoice.php\", \"signal\": \"raw SQL\"}]}","budget_class":"fast","evidence":"evidence: \"archrules({pack}): {v} violations ({k} core); ui->persistence hits {list}\"","remediation":{"quick_win":"add an arch test (ArchUnit/import-linter) and fix the top violations; enforce at PR time.","structural":"rebuild the lost layers — extract domain into its own module, move persistence behind repositories, keep UI thin; do it one vertical slice at a time.","gold_standard":"Architecture rules enforced in CI; a 30-minute vertical-slice tour confirms correct directions; business rules live in the domain layer only.","effort":"🔶 ~2–4 h"}},
  "ARCH-04": {"id":"ARCH-04","category":"ARCH","name":"Dead & Orphaned Code","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"Unreferenced functions, classes, endpoints, feature flags that are permanently on (or permanently off), unreachable branches, duplicate implementations where only one is used, and modules that nothing imports.","why":"Dead code is fossilized intent. It costs readers time (is this used?), auditors time, and test-maintenance time, and it accumulates whenever the codebase is touched without pruning — a hallmark of unowned code. It also hides which live paths are actually in production.","manifests":"Unused exports/imports, feature flags stuck true/false with no plan, endpoints with zero traffic, utility functions with no callers, commented-out blocks, dead branches (`if (false)`), shadowed duplicates.","detection":"Dead-code eliminators — `knip` (TS/JS), `unimported`, `depcheck`, `vulture` (Python), `pyflakes` unused, `golangci-lint` unused, IntelliJ/WebStorm unused-code inspection; coverage diffs (run coverage; code never executed in prod-like tests); API traffic logs for zero-traffic endpoints; git archaeology for \"last touched 5 years ago.\"","yellow":"10–20% of functions unreferenced, or a handful of zero-traffic endpoints, or flags on for > 1 year.","red":"> 20% dead code, or unreferenced endpoints live in production exposing attack surface, or the dead-code report has grown two quarters in a row.","yellow_rationale":"warning-level bloat — prune it before it compounds.","red_rationale":"the codebase is decaying faster than it's being maintained — plus live-but-orphaned endpoints are an attack surface.","criteria":{"0":"orphaned endpoints live on core/auth paths.","1":"> 20% or orphaned endpoints in isolated services","2":"10–20% dead code in peripheral areas","3":"scan clean"},"scope":"Unreferenced code and flags only; live-but-zero-traffic exposure cross-references API traffic without duplicating it.","applicability":"never N/A for scored repos (dead code % is defined over whatever exists); `unknown_when: no supported language`.","statusing":"measured_when:  native detector ran clean\nestimated_when: heuristic-only ecosystem (Go/Java)          # clamp [1,2], confidence low\nunknown_when:   no supported language parsed\nna_when:        never (see Inputs)\nclamp:          [1,2]\nconfidence:     medium full / low heuristic\nscope_limited:  monorepo workspace truncation -> estimated + scope-limited","score_mapping":"Y/R values (10–20% / >20%, flag-age 6–12mo): see §3.\n\n- `3`: `unreferenced_pct < Y_PCT` ∧ no stuck flags ∧ no orphans\n- `2`: Yellow band, peripheral only\n- `1`: `> R_PCT` ∨ orphan endpoints in isolated services\n- `0`: orphan endpoints resolving on core/auth paths ∨ two-quarter growth trend (needs scan history; v1 single-scan omits trend)","fact_schema":"{\"arch04\": {\n  \"symbols_total\": 3120, \"unreferenced_pct\": 12.8,\n  \"stuck_flags\": [{\"name\": \"checkoutV2\", \"age_days\": 420, \"value\": true}],\n  \"orphan_endpoints\": [{\"route\": \"/admin/legacy-export\", \"refs_found\": 0}]}}","budget_class":"slow-dissolvable","evidence":"evidence: \"knip {ver}: {p}% of {n} symbols unreferenced; stuck flags {list}; orphans {list}\"","remediation":{"quick_win":"run knip/vulture, delete safely (git history preserves), remove orphaned endpoints and the routes that point to them.","structural":"a \"no dead code\" PR gate (knip in CI, fail on new unreferenced exports), flag retirement policy (flags > 6 months get removed or justified), quarterly pruning ritual.","gold_standard":"Dead-code scan clean in CI; every feature flag has an owner and a retirement date; all prod endpoints are in an API inventory with traffic.","effort":"⚡ ≤30 min"}},
  "ARCH-05": {"id":"ARCH-05","category":"ARCH","name":"Code Churn vs. Defect Hot Spots","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"A small fraction of files absorbs a disproportionate share of commits (churn), and those same files produce a disproportionate share of defects and incident fixes. Change is fractal: the same code is reworked over and over.","why":"High-churn/high-defect \"hot spots\" are where the codebase is actively fighting its own shape. They signal that a module's design is wrong for its workload — and the fix isn't more commits, it's a redesign. DORA and CodeScene research tie this pattern directly to delivery slowdown and engineer churn.","manifests":"Git history (files with the most commits and most bug-fix commits), bug tracker (which modules get the most defect tickets), incident data (which files are implicated in production fixes), files that are touched on every feature.","detection":"Git hot-spot analysis — CodeScene, GitPrime/Pluralsight Flow, `git log --since --oneline -- <path> | wc -l`, `git blame` density, commit graph mining (custom script counting commits/bugfixes per file); correlate with defect tracker (`gh issue --search \"in:title bug\"` grouped by path). Compute churn rank and defect rank; flag files in both top deciles.","yellow":"Top 5% churned files show moderate bug frequency; churn is concentrated but defects not yet correlated.","red":"Top 10% churned files account for > 50% of production incident fixes, or a single file is both #1 churn and #1 defect.","yellow_rationale":"warning — the shape is starting to hurt.","red_rationale":"the module is structurally broken — every change breeds a bug.","criteria":{"0":"hot spot in core logic driving incidents.","1":"hot spot in an isolated path","2":"churn concentrated, defects mild","3":"no overlap"},"scope":"Churn∩defect concentration per file; who owns the code is VEL-06 — not this row.","applicability":"`na_when: git history < 6 months or < 200 commits` → insufficient signal, status `unknown`, never N/A (history exists).","statusing":"measured_when:  commits_analyzed >= MIN_COMMITS and not history_truncated\nestimated_when: truncated/shallow history                        # clamp [1,2], confidence low\nunknown_when:   applicability condition fired (<6mo / <200 commits)\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium full-year window; low otherwise\nscope_limited:  window shrunk by budget -> estimated + scope-limited","score_mapping":"Thresholds/criteria: see §3.\n\n- `3`: churn∩defect intersection empty in top deciles\n- `2`: churn concentrated (`churn_top10_share > Y_SHARE`), defect correlation mild\n- `1`: single hot spot in isolated path\n- `0`: hot spot on core path ∧ `defect_rank <= R_RANK ∧ churn_rank <= R_RANK`","fact_schema":"{\"arch05\": {\n  \"commits_analyzed\": 4210, \"window_days\": 365,\n  \"churn_top10_share\": 0.38,\n  \"hotspots\": [{\"file\": \"auth/session.py\", \"churn_rank\": 1, \"defect_rank\": 2, \"in_core_path\": true}],\n  \"history_truncated\": false}}","budget_class":"api-budgeted","evidence":"evidence: \"git-mining {n} commits/{w}d: top10% files absorb {s}% churn; hotspots {files}\"","remediation":{"quick_win":"put the top hot spot behind a designated owner, add targeted tests, freeze feature scope on it for one sprint.","structural":"redesign the hot spot — decompose by responsibility, rewrite the risky core with tests first, rotate engineers to avoid bus-factor in the fix. Track the metric quarterly to prove improvement.","gold_standard":"Churn evenly distributed relative to responsibility; no file in the top churn∩defect intersection for two quarters; hot-spot list tracked in the refactoring backlog.","effort":"🔶 ~2–4 h"}},
  "ARCH-06": {"id":"ARCH-06","category":"ARCH","name":"Architectural Era / Framework Generation","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The codebase's architectural style is one or more generations behind the ecosystem norm — e.g., a non-modular monolith with no dependency injection where modules are expected, global singleton state where DI is expected, or an architecture style (e.g., action-command giant controllers, RPC-style god endpoints) that modern practice has replaced.","why":"Architectural style is a proxy for how much of the system's mechanics are \"solved\" by structure vs. reinvented by hand. Old eras lack the seams that make change, testing, and tooling cheap. A codebase that predates modularity has to build those seams manually — a huge modernization drag.","manifests":"No DI container (manual wiring in a central bootstrap), no package/module boundaries on disk, static service locators, giant controller/service classes, everything depending on everything, build system that doesn't support modules, tests that need a live stack because nothing is swappable.","detection":"Architecture inventory — a \"generation test\": can you instantiate a core service in a unit test without the DB/network? Can you swap one implementation for another without editing callers? Check for DI, module boundaries, hexagonal/ports-and-adapters seams. Compare against the current norm for the language (e.g., .NET 8 modular monolith vs. WebForms-era, Spring Boot vs. EJB 2).","yellow":"One generation behind — some seams exist but testing requires a live stack for many paths.","red":"Two+ generations behind — no DI, no module seams, tests require the full stack, or the architecture style (e.g., EJB 2-era) has no modern tooling support.","yellow_rationale":"modernization is still incremental — a facade can buy time.","red_rationale":"the seams modernization needs don't exist; you're building them before you can refactor.","criteria":{"0":"whole system two+ generations behind with no seams.","1":"two generations behind in isolated services","2":"one generation behind, seams exist","3":"current generation"},"scope":"Style/seams generation gap; vendor support status is ECOS-08, runtime EOL is ECOS-01.","applicability":"`na_when: no source parsed`. Else applicable.","statusing":"measured_when:  never auto-measured            # era judgment is inherently inferential\nestimated_when: >=2 of {di, boundaries, seam} signals computed   # clamp [1,2], confidence medium if 3-of-3, else low\nunknown_when:   no signals computable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium iff di+boundaries+seam all present","score_mapping":"Criteria/generation definitions: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: `generation_gap <= 1` ∧ some seams (`core_seam_index >= Y_SEAM`)\n- `1`: `generation_gap == 2` confined to isolated services ∨ weak seams elsewhere\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch06\": {\n  \"di_present\": false,\n  \"module_boundaries\": false,\n  \"core_seam_index\": 0.18,\n  \"singleton_count\": 41,\n  \"generation_gap\": 2,\n  \"era_table\": \"java-2026.1\"}}","budget_class":"fast","evidence":"basis: \"era-probes: di={bool} boundaries={bool} seam_index={s}; classified gap={g} generations\"","remediation":{"quick_win":"introduce interface seams around the 3 worst-coupled cores, add a couple of tests to prove the seams work.","structural":"adopt the modern architecture incrementally — introduce a DI container, extract modules with enforced boundaries, wrap legacy access behind ports, migrate vertical slices one at a time.","gold_standard":"Core logic testable without live infrastructure; DI and module boundaries standard; new features land in the modern style while legacy shrinks.","effort":"🔶 ~2–4 h"}},
  "ARCH-07": {"id":"ARCH-07","category":"ARCH","name":"Global Mutable State & Hidden Dependencies","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The system relies on global mutable state — singletons, module-level variables, static mutable fields, ambient configuration, shared caches — and hides dependencies (time, randomness, network, the DB) inside functions rather than injecting them.","why":"Hidden dependencies and globals make correctness a function of execution order and history rather than of inputs. Tests become order-dependent, concurrency becomes a minefield, and the code can't be reasoned about in isolation. Modern practice (pure functions, explicit dependencies, DI) exists precisely to eliminate this class of bug.","manifests":"Singleton service locators, static mutable fields, module-level `config`/`state` objects, functions calling `time.now()`/`Math.random()`/the DB directly (not injected), hidden global caches, order-dependent initialization, \"set state at import time\" patterns.","detection":"Static analysis + manual — grep for singleton/service-locator patterns, `static` mutable fields, direct `DateTime.Now`/`new Date()` in logic (vs. injected clock), direct ORM calls in domain functions; dependency injection presence; a test experiment: run the suite in random order / in parallel and count failures (also feeds TEST-07). Tools: `architecture-tests`, `import-linter`, SonarQube, greps.","yellow":"Globals/singletons present in non-core paths, or a handful of hidden-dependency calls; tests currently pass serially.","red":"Shared mutable state in core business flows, or hidden time/IO in core logic, or parallel/randomized test runs fail.","yellow_rationale":"warning — it hasn't bit yet, but it's the same class as the red flag.","red_rationale":"correctness is now order-dependent — a structural correctness debt, not just a style debt.","criteria":{"0":"core correctness is order/concurrency-dependent.","1":"globals/hidden deps in core, tests serial-only","2":"globals in peripheral code","3":"explicit dependencies everywhere"},"scope":"Shared *state* in product code; the test suite's reaction to it is TEST-07 — this row scores the code.","applicability":"`na_when: no source parsed`. Else applicable.","statusing":"measured_when:  never auto-measured            # pattern greps are labeled inference\nestimated_when: >=1 matcher pack ran           # clamp [1,2], confidence medium if full pack, else low\nunknown_when:   no supported language\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when all language matchers ran clean\nscope_limited:  sampled dirs -> estimated + scope-limited","score_mapping":"Criteria: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: globals/hidden-dep hits present, `hits_in_core == 0`\n- `1`: `hits_in_core > 0` below Red density\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch07\": {\n  \"singleton_count\": 17,\n  \"hidden_dep_hits\": [{\"file\": \"billing/currency.py\", \"signal\": \"datetime.now() in domain\", \"in_core_path\": true}],\n  \"hits_in_core\": 6}}","budget_class":"fast","evidence":"basis: \"state-grep: {s} singletons; {h} hidden time/IO/DB calls ({k} core)\"","remediation":{"quick_win":"inject the clock/random/IO at the seams you can reach; make the top 5 singletons instances with explicit wiring.","structural":"eliminate globals by constructor injection; make state explicit and owned; introduce a proper initialization/DI lifecycle; enforce \"no static mutable\" with a lint.","gold_standard":"All dependencies explicit and injected; time/random/IO behind interfaces; test suite passes under random/parallel execution; zero mutable statics in core.","effort":"🔶 ~2–4 h"}},
  "ARCH-08": {"id":"ARCH-08","category":"ARCH","name":"Duplication Debt","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The same logic, algorithms, or structures are copy-pasted across the codebase and/or across services, with variations drifting over time — \"the same bug in 5 places.\"","why":"Duplication is the most visible sign that code wasn't given a home to live in. Every duplicated instance multiplies fix cost, allows drift (one copy gets the fix, others don't), and inflates the surface area of every change. It's the persistence of \"temporary\" code that became permanent.","manifests":"Similar functions/classes across modules, copy-pasted validation/date/price logic, identical DTOs, duplicated middleware/error handling, near-identical test fixtures, similar blocks in different languages.","detection":"Clone detection — `jscpd` (code clone detection, all languages), PMD-CPD, Simian, SonarQube duplication, `dupl` (Go), `pylint` similar; manual: two files implementing the same concept; cross-service grep for the same constant/logic string.","yellow":"Duplication 10–20%, mostly within a module, mostly peripheral.","red":"> 25% duplication, or the same core business logic duplicated across services (where a bug in one copy costs money), or duplicated security/auth logic.","yellow_rationale":"warning — extract and consolidate before it becomes a web.","red_rationale":"divergent copies of critical logic are a correctness and security hazard.","criteria":{"0":"core rules duplicated across services with drift.","1":"dup in core logic within one service","2":"10–20% peripheral dup","3":"< 10% dup, single source of truth"},"scope":"Clone ratio within/across modules; duplicated data access driving coupling is DATA-02/API-03.","applicability":"`na_when: < 10 source files` (clone ratio meaningless below floor, clause-b).","statusing":"measured_when:  jscpd exit clean and lines_analyzed >= MIN_LINES\nestimated_when: sampled subset (budget dissolve)              # clamp [1,2], confidence low\nunknown_when:   no supported language\nna_when:        applicability fired (< MIN_FILES)\nclamp:          [1,2]\nconfidence:     medium (deterministic token model)\nscope_limited:  file-count cap -> estimated + scope-limited","score_mapping":"Y/R values (10–20% / >25%): see §3.\n\n- `3`: `duplication_pct < Y_PCT`\n- `2`: Yellow band, peripheral clusters only\n- `1`: duplication in core logic within one service\n- `0`: `security_critical_dup` ∨ core business rules duplicated cross-service (`cross_service ∧ in_core_path ∧ tokens > R_TOKENS`)","fact_schema":"{\"arch08\": {\n  \"duplication_pct\": 14.2,\n  \"clusters\": [{\"tokens\": 380, \"files\": [\"a/pay.py\", \"b/pay.py\"], \"cross_service\": true}],\n  \"security_critical_dup\": true,\n  \"lines_analyzed\": 84200}}","budget_class":"slow-dissolvable","evidence":"evidence: \"jscpd {ver}: {p}% across {n} lines; worst cluster {t} tokens ({files}); sec-crit={bool}\"","remediation":{"quick_win":"run jscpd, consolidate the top clusters behind a shared library (start with the business-critical ones).","structural":"establish a shared internal library with a review process; kill duplicates at PR time (clone scan in CI); migrate duplicated logic incrementally with tests preserving behavior.","gold_standard":"Duplication < 10%; core business rules exist exactly once, in one owned library; clone scan in CI fails new duplication.","effort":"🔶 ~2–4 h"}},
  "ARCH-09": {"id":"ARCH-09","category":"ARCH","name":"Agentic Operability (AI/LLM Codebase-Readiness)","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"How well an AI/LLM coding agent (Copilot-class, CLI agents, automated refactoring) can find context, run a targeted test, and make a change safely from a fresh clone. Modernization is increasingly executed by agents; a codebase that resists them resists the accelerant.","why":"Agentic operability is the 2020s modernization axis: navigable, seam-rich, tested, documented code is cheap to change *by machine*; legacy discs are not. It is also the practical test of whether the modernization *itself* can be AI-assisted. A repo without navigation aids, testable seams, and a single-command harness forces every change — human or machine — into archaeology.","manifests":"No repo-map / LLM context / navigation index that matches disk, tests not co-located with the code they cover, core logic not constructible in a unit test without live infra, no single command that builds+tests from a fresh clone, docs that contradict code (borrowed signal from DOCS-02).","detection":"Navigation-aid inventory (repo-map files, code-navigation config, top-level index vs. disk layout); test-to-code proximity heuristic (% of source files with a co-located or directly-referenced test); core-module seam index (already computed for ARCH-02/06 — reuse); fresh-clone harness check (does a documented command complete a green build+test?); sampled docs-vs-code contradictions. Compose the four signals into one score.","yellow":"Partial navigation aids, < 60% test-to-code proximity in core, seams exist but inner loop slow — an agent can act but slowly and with drift risk.","red":"No navigation aids, core logic not constructible in a test without live infrastructure, no single-command harness — an agent cannot complete a scoped task reliably from a fresh clone.","yellow_rationale":"operable with friction — fix the cheap aids before agents multiply the cost.","red_rationale":"the fastest modernization lever is foreclosed; every change stays archaeology.","criteria":{"0":"no navigation, no seams, no harness — machine and human alike cannot operate.","1":"aids absent, core seams missing, harness manual","2":"aids partial, proximity ~60%, harness slow","3":"navigation aids + co-located tests + seam-rich core + single-command success"},"scope":"Compound operability score; inherits seams of ARCH-02/06, proximity of TEST-06, freshness of DOCS-02 — measured once here.","applicability":"never N/A for scored repos.","statusing":"measured_when:  never auto-measured            # compound judgment\nestimated_when: >=3 of 4 signals computed      # clamp [1,2]; confidence medium iff all 4\nunknown_when:   <3 signals computable (emit which)\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium iff nav+proximity+seam+ci_proof all present\nscope_limited:  ci proof unavailable (no Actions) -> estimated low + scope-limited note","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: aids partial ∨ `proximity >= Y_PROX` ∧ seams exist ∧ slow harness signal\n- `1`: aids absent ∨ `proximity < Y_PROX` in core ∨ no CI proof\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch09\": {\n  \"nav_aids\": {\"present\": true, \"files\": [\"CLAUDE.md\"], \"matches_disk\": 0.9},\n  \"test_proximity_core\": 0.42,\n  \"core_seam_index\": 0.55,\n  \"ci_green_proof\": {\"found\": true, \"workflow\": \"ci.yml\", \"last_green_days\": 2},\n  \"docs_contradictions_sampled\": 3}}","budget_class":"fast","evidence":"basis: \"agentic-compose: nav={p}% disk-match; proximity={q}; seam={s}; ci_green={bool}({d}d)\"","remediation":{"quick_win":"ship a repo-map/context file, co-locate tests for the top core modules, define a task runner of record with a fresh-clone CI proof.","structural":"seam extraction on core (ports), docs-as-code freshness (DOCS-09), a recurring \"agent completes task X from fresh clone\" acceptance test as a quality gate.","gold_standard":"From a fresh clone, an agent (or new hire) can locate the module, run its tests, and land a scoped change within one session; navigation aids match disk; core is testable without live infra.","effort":"🔶 ~2–4 h"}},
  "ARCH-10": {"id":"ARCH-10","category":"ARCH","name":"Feature-Flag & Configuration Debt","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"Configuration and feature toggles are hardcoded in source, live in per-env hand-edited files, or exist as long-lived flags with no owner or retirement — so \"safe incremental release\" is achieved, if at all, by editing code.","why":"Progressive delivery — flags, externalized config, rollback-by-toggle — is the mechanism that makes modernization *safe*. A codebase that hardcodes toggles and buries config in code predates 12-factor discipline: every release is a big-bang, every rollback is a code change, and every environment is a fabrication by hand.","manifests":"Hardcoded booleans/strings as toggles (`USE_NEW_FLOW = true` in source), flag values stuck on for months/years with no ticket, prod config values committed to the repo, per-env config files maintained separately by hand, feature branches used as flags (ties to VEL-10), no config management/injection.","detection":"Grep sweep for toggle/flag/env strings; config-declaration inventory (env templates vs. baked values in source); flag age + ownership via git history; prod-value-in-repo check; env config drift comparison. Count flags, classify by core path.","yellow":"Flags/config hardcoded in non-core modules; some long-lived flags without owners; env config partially hand-edited.","red":"Core logic driven by hardcoded toggles/baked config; prod config stored in the repo; flags used as emergency switches with no retirement path.","yellow_rationale":"friction and drift risk, modernizable in place.","red_rationale":"safe incremental modernization — and safe rollback — is impossible without the flag/config levers.","criteria":{"0":"core on hardcoded config/flags with no retirement — safe modernization blocked.","1":"toggles in core with no ownership, config hand-edited","2":"toggles in non-core, some uneowned flags","3":"all toggles externalized + owned, config injected per env"},"scope":"Config/flag mechanics only; secrets are SEC-02, env drift is VEL-07/DATA-10, dead stuck-on flags are ARCH-04.","applicability":"never N/A for scored repos (absence of flags/config hygiene is itself signal).","statusing":"measured_when:  never auto-measured            # toggle-vs-config classification is inferential\nestimated_when: >=1 sweep completed            # clamp [1,2]; confidence medium iff blame ages complete\nunknown_when:   tree unparseable\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium when toggle+config+age probes all ran\nscope_limited:  sampled dirs -> estimated + scope-limited","score_mapping":"Criteria: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: toggles only outside core ∧ some owned/aged flags ∨ partial templating\n- `1`: `toggles_in_core > 0` ∧ no retirement evidence ∨ `prod_config_in_repo`\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch10\": {\n  \"hardcoded_toggles\": [{\"name\": \"checkoutV2\", \"file\": \"src/config.ts\", \"age_days\": 420}],\n  \"toggles_in_core\": 2,\n  \"flag_sdk_present\": false,\n  \"prod_config_in_repo\": true,\n  \"env_templates_present\": false}}","budget_class":"fast","evidence":"basis: \"flag-sweep: {n} hardcoded toggles ({k} core, oldest {d}d); prod-config-in-repo={bool}; sdk={bool}\"","remediation":{"quick_win":"move the top flags to an externalized flag source with owners + retirement dates, externalize prod config into a per-env injected pipeline.","structural":"config-as-code injected per environment, a flag lifecycle policy (owner, TTL, removal ceremony), a rule that prod values never live in the repo.","gold_standard":"Zero hardcoded toggles in core; every flag owned with a retirement date; config injected per env from one source; rollback = flag flip, not code change.","effort":"⚡ ≤30 min"}},
  "ARCH-11": {"id":"ARCH-11","category":"ARCH","name":"Nullable/Untyped Code & Runtime Error Density","tier":"A","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"The codebase is weakly typed or relies on implicit nullability where modern practice expects static typing and explicit null safety — dynamic dispatch, `any`/`Object` as a type, unchecked casts, defensive null checks scattered everywhere, stringly-typed arguments — and runtime errors (NPEs, `undefined` access) are a visible fraction of incidents.","why":"Type safety is a modernization \"tax\" that's often the whole point of upgrading: it converts a class of runtime bugs into compile-time errors. A codebase that predates or rejects it carries a permanently higher runtime-error rate and makes large refactors (renames, signature changes) dangerous and slow.","manifests":"TypeScript `any` everywhere, Python without type hints in hot paths, Java/C# with pervasive null checks and unchecked casts, dynamic languages doing introspection, `Optional.get()` chains, crash logs dominated by null/undefined exceptions.","detection":"Type-lint rules — TypeScript `no-explicit-any`, `strict` mode off, `strictNullChecks` off; `mypy` coverage %; `pyright`; grep for defensive null checks; incident data mining: what share of prod crashes are null/type errors. Count typed-vs-untyped function signatures in core modules.","yellow":"Some typed coverage, strict mode partially on, null-crash share 5–10% of incidents.","red":"Core paths untyped, strict mode off, null/undefined errors a top incident cause (> 15%).","yellow_rationale":"warning — type debt is present but not dominant.","red_rationale":"a whole bug class you could eliminate at compile time is shipping to prod.","criteria":{"0":"null errors a top incident class.","1":"core untyped, strict off","2":"partially typed","3":"strict + typed"},"scope":"Server-side type safety; client-side untyped state is FE-05, repeated null-defence boilerplate is ARCH-12.","applicability":"`na_when: language set has no typing surface worth scoring` — only when repo is docs/config-only. Zero-typed-signatures is score signal, not N/A.","statusing":"measured_when:  never auto-measured            # red-flag criterion needs runtime error share\nestimated_when: >=1 typing probe completed     # clamp [1,2]; confidence medium if config+AST both\nunknown_when:   no supported language parsed\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium iff tsconfig/pyright config read + AST density both ran","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: partial typing (`typed_pct >= Y_TYPED` ∨ strict on with exceptions)\n- `1`: core modules untyped ∧ strict off\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch11\": {\n  \"strict_mode\": {\"ts\": false, \"strictNullChecks\": false},\n  \"any_per_kloc\": 18.4,\n  \"typed_signature_pct\": 31.0,\n  \"config_files\": [\"tsconfig.json\"]}}","budget_class":"fast","evidence":"basis: \"type-probe: strict={bool}; {a}/KLOC any; {t}% signatures typed ({lang})\"","remediation":{"quick_win":"enable `strict`/`strictNullChecks` on the smallest core module, fix the fallout, expand module by module; add `mypy --strict` to CI incrementally with a ban-list.","structural":"adopt explicit null-safety (Option/Result types), eliminate `any` with real types at boundaries, add type coverage gate (e.g., `typescript coverage > X%`).","gold_standard":"Strict mode on across the system; typed coverage > 90%; null/type errors < 2% of incidents; boundary types (API, DB, events) fully defined.","effort":"🔷 ~1–2 days"}},
  "ARCH-12": {"id":"ARCH-12","category":"ARCH","name":"Duplicated Cross-Cutting Concerns (auth, logging, error handling, transactions)","tier":"A","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"Cross-cutting concerns — authentication, authorization, logging, error mapping, transaction boundaries, validation — are implemented ad hoc in every call site instead of as shared, testable infrastructure (middleware/interceptors/decorators).","why":"Cross-cutting concerns are where security and compliance bugs live, and ad-hoc implementation means: inconsistent coverage (one route forgets auth), duplicated and drifted logic, and no single place to add a security control or a trace. Modern frameworks provide interceptors/middleware precisely to centralize these.","manifests":"Auth checked manually at the top of N controllers (and missed in a few), logging calls sprinkled with inconsistent context, try/catch duplication, transaction management inside every service method, validation hand-rolled per endpoint.","detection":"Grep/pattern analysis — count manual auth checks vs. middleware; error-handling duplication (catch blocks with the same mapping); transaction boilerplate per method; trace/log-context consistency (from PERF-01/API-07). Tools: SonarQube rules, custom greps, security review sampling.","yellow":"Some duplication of cross-cutting code; manual auth in a few non-critical routes.","red":"Manual security checks in core routes (with known coverage gaps), or no centralized error/logging infrastructure at all.","yellow_rationale":"warning — the drift is seeded.","red_rationale":"this is where a missed check becomes a breach.","criteria":{"0":"missed coverage in security-sensitive paths.","1":"manual checks in core","2":"mostly centralized, gaps","3":"centralized + enforced"},"scope":"Shared-infrastructure duplication; auth-*coverage* gaps are SEC-04, error-*semantics* are API-07.","applicability":"`na_when: no HTTP/route surface detected` (pure CLI/batch repo, clause-b).","statusing":"measured_when:  never auto-measured            # coverage-gap judgment is inferential\nestimated_when: >=2 of {middleware-coverage, auth-sites, error-mapper} probes ran   # clamp [1,2]\nunknown_when:   routes unparseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when all three probes ran on a supported framework\nscope_limited:  sampled endpoint set -> estimated + scope-limited","score_mapping":"Criteria: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: mostly centralized (`coverage_pct >= Y_COV`), few manual sites outside core\n- `1`: manual security checks in core-route set ∨ `coverage_pct < Y_COV`\n- `3`/`0` unreachable by construction","fact_schema":"{\"arch12\": {\n  \"endpoints\": 84,\n  \"middleware_coverage_pct\": 61.9,\n  \"manual_auth_sites\": [{\"file\": \"controllers/admin.js\", \"endpoint\": \"/admin/x\"}],\n  \"dup_error_mappers\": 7,\n  \"tx_boilerplate_methods\": 22}}","budget_class":"fast","evidence":"basis: \"crosscut-probe: middleware covers {p}% of {n} endpoints; manual auth sites {k}; dup mappers {m}\"","remediation":{"quick_win":"audit for missing shared middleware and missed auth sites; move the top repeated concern (auth) to framework middleware.","structural":"centralize each concern (authN/authZ, logging, error mapping, validation, transactions) into one owned infrastructure layer with tests; wire via framework interceptors; add security tests that assert every endpoint enforces auth.","gold_standard":"Every cross-cutting concern implemented once, in infrastructure, enforced by framework; a security test walks all routes asserting auth coverage; zero manual auth in controllers.","effort":"🔷 ~1–2 days"}},
  "TEST-01": {"id":"TEST-01","category":"TEST","name":"Code Coverage Degradation","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"PART","rollup":"standard","gates":[],"definition":"Coverage of the highest-criticality logic has fallen below a working threshold — either never measured, measured only on trivial code, or measurably dropping over time.","why":"Coverage isn't a goal in itself, but it's the cheapest proxy for \"can we refactor this safely?\" Below ~50% branch coverage, refactoring the core is close to gambling. A coverage trend that's *falling* is a leading indicator that the suite is being abandoned while production grows.","manifests":"CI coverage reports (Istanbul/JaCoCo/coverage.py reports), coverage dashboards, modules with notoriously no tests, \"we skip tests to ship\" patterns, coverage gate absent or set to 0.","detection":"Coverage runners — `c8`/`istanbul` (JS), `JaCoCo` (Java), `coverage.py`/`pytest-cov` (Python), `dotnet test --collect`, `go test -cover`; view by module, weight by criticality (core domain vs. peripheral). Track the trend over last 4 quarters.","yellow":"50–70% branch coverage, or coverage falling > 5 points/quarter in core modules, or gate absent.","red":"< 50% branch coverage on core services, or zero coverage on a newly shipped critical path, or the coverage gate is absent *and* the trend is down.","yellow_rationale":"below this line refactors get risky; falling coverage means it's getting worse.","red_rationale":"the immune system can't catch the damage refactors will cause.","criteria":{"0":"core untested or gate absent with falling trend.","1":"< 50% on isolated paths","2":"50–70% with gate","3":"> 80% core coverage, gate on"},"scope":"Coverage level/trend; which core paths lack tests is TEST-06 — not this row.","applicability":"`na_when: zero test files AND zero test config` → unknown, not N/A. Else applicable.","statusing":"measured_when:  never in v1                      # lineage of any observed number is unverified\nestimated_when: any pct signal observed          # clamp [1,2]; confidence low always (04 §5 caveat mandatory)\nunknown_when:   no artifact/config/log signal\nna_when:        never\nclamp:          [1,2]\nconfidence:     low by rule; report copy carries \"seen in CI artifacts; lineage unverified\"\nscope_limited:  logs unavailable -> unknown \"rate-limited\" if API exhausted","score_mapping":"Thresholds/criteria: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: `Y_COV <= observed_pct < R_COV`\n- `1`: `observed_pct < R_COV` ∨ coverage configured but no observable number anywhere\n- `3`/`0` unreachable by construction","fact_schema":"{\"test01\": {\n  \"committed_report\": {\"found\": false},\n  \"ci_runner_configured\": true,\n  \"log_observed_pct\": {\"branch\": null, \"line\": 63.5, \"source\": \"run#1234 log\", \"observed_at\": \"2026-08-01\"},\n  \"trend_available\": false}}","budget_class":"api-budgeted","evidence":"basis: \"actions-log run#{id}: line {p}% (artifact lineage unverified)\"","remediation":{"quick_win":"add a real coverage gate (fail below threshold) on core modules only, and instrument the trend.","structural":"invest in testing the highest-churn/highest-risk modules first (correlate with ARCH-05), write tests as part of every bug fix (see coverage climb), make coverage a tracked product metric.","gold_standard":"Branch coverage > 80% on core modules; coverage gate enforced in CI; coverage trend visible on a dashboard and rising or stable.","effort":"⚡ ≤30 min"}},
  "TEST-02": {"id":"TEST-02","category":"TEST","name":"Flaky Test Rate","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"A measurable fraction of the test suite fails intermittently without any code change — tests that pass locally, fail in CI, pass on rerun, or fail only in certain orders/environments.","why":"Flaky tests are a *behavioral* tax: they train the team to distrust the suite (the \"rerun it\" reflex), hide real regressions, burn CI time, and erode the will to refactor. A high flake rate is a symptom of test-design debt and of a codebase too coupled to run cleanly.","manifests":"CI rerun logs, GitHub Actions \"rerun failed jobs\" click-rate, `.first`/`.random` ordering issues, sleeps/timers in tests, tests that need a shared DB, non-determinism from real time/network/parallelism.","detection":"Flake tracking — CI analytics (GitHub Actions, Datadog CI Visibility), rerun frequency, `--flaky` flags (pytest, Jest `--retry`), running the suite multiple times (`for i in {1..10}; do npm test`), randomized order runs (`--shuffle`, `--random-order`), parallel execution. Track flake rate as `flaky_failures / total_failures`.","yellow":"5–10% flaky, or a few notorious flaky tests causing weekly reruns.","red":"> 10% flaky, or flaky tests routinely disabled/deleted to keep CI green, or the team's reflex is \"rerun it\" for > 50% of failures.","yellow_rationale":"warning — the suite is starting to lie.","red_rationale":"the suite no longer verifies anything — the immune system is compromised.","criteria":{"0":"suite widely distrusted, real regressions escaping.","1":"> 10% or skipped-to-green","2":"5–10% flaky","3":"< 2%"},"scope":"Flake rate of the suite; order-dependence causes land in TEST-07 when v2 executes both.","applicability":"n/a until v2.","statusing":"measured_when:  never in v1\nestimated_when: never                            # flake guesses are exactly what the taxonomy forbids\nunknown_when:   always in v1                     # emission text: rerun protocol above\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1 (unscored row).","fact_schema":"{\"test02\": {\"status\": \"unknown\", \"reason\": \"requires test execution (v2 deep scan)\"}}","budget_class":null,"evidence":"emission: \"unknown — flakiness provable only by rerunning the suite; see 'what it takes' appendix\"","remediation":{"quick_win":"quarantine flaky tests (run separately, don't block but do report), fix the top 5 by root cause (sleeps → waits, shared DB → test DBs, order-dependence → isolation).","structural":"make tests hermetic (see TEST-07), add flake detection to CI (auto-quarantine + report), hold the line: no new flaky tests.","gold_standard":"Flake rate < 2%; zero \"rerun to pass\" culture; flaky tests auto-quarantined and tracked to fix within a sprint.","effort":"🔶 ~2–4 h"}},
  "TEST-03": {"id":"TEST-03","category":"TEST","name":"Test Pyramid Inversion","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The distribution of tests is inverted — few unit tests, a top-heavy layer of slow end-to-end tests, or UI-tests-as-integration-tests — instead of a pyramid (many fast unit tests, fewer integration, few E2E).","why":"An inverted pyramid is expensive and slow (E2E tests are the slowest, flakiest, most brittle), gives poor failure localization (an E2E failure says nothing about where), and means most logic is tested through the UI — the least stable interface. It's the signature of a suite that grew as \"just make it green\" rather than by design.","manifests":"Test suite where E2E/UI tests dominate runtime, unit tests near-zero, coverage achieved only via slow full-stack tests, `cypress`/`playwright`/`selenium` suites that take an hour, \"tests that spin up the whole app.\"","detection":"Categorize tests by type (unit/integration/E2E) via config, runtime, or annotations; measure count and *runtime share* per tier; run a pyramid ratio: `unit_count / e2e_count`, and runtime share of E2E. Inspect what the \"unit\" tests actually do (do they hit the DB? the UI?).","yellow":"E2E-heavy (E2E count ≥ unit count, or E2E runtime > 50% of suite time) in places.","red":"Test pyramid fully inverted — no meaningful unit layer, all behavior tested through UI/full-stack, E2E suite hours long and frequently failing.","yellow_rationale":"warning — slow and brittle, but the coverage is at least there.","red_rationale":"feedback is so slow and coarse that the suite provides almost no regression protection.","criteria":{"0":"no unit layer, behavior tested only through UI.","1":"E2E-dominant in a service","2":"overweight E2E in places","3":"pyramid shape"},"scope":"Shape of the suite by tier; run-time cost of that shape is TEST-04, skip hygiene is TEST-05.","applicability":"`na_when: zero test files of any kind` → score-0 territory belongs to TEST rows generally; here N/A (no pyramid to invert) with reason recorded. Decision: **N/A allowed** — a repo with zero tests has no pyramid shape; TEST-05/08 carry the zero-test signal instead.","statusing":"measured_when:  never auto-measured            # per-file tier assignment is heuristic\nestimated_when: >=60% of test files classified # clamp [1,2]; confidence medium iff high-ratio >= 0.8\nunknown_when:   <60% classifiable\nna_when:        zero test files (reason: no shape)\nclamp:          [1,2]\nconfidence:     medium when high-confidence classification dominates\nscope_limited:  test-file read bound hit (file count / per-file bytes) -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: overweight E2E but unit layer exists (`e2e_share > Y_SHARE ∧ unit > 0`)\n- `1`: near-inverted (`unit:e2e < Y_RATIO`) or UI-tests-as-integration pattern dominant\n- `3`/`0` unreachable by construction","fact_schema":"{\"test03\": {\n  \"unit\": 210, \"integration\": 45, \"e2e\": 88, \"unclassified\": 12,\n  \"e2e_share_est\": 0.41,\n  \"classification_confidence\": {\"high\": 0.86, \"low\": 0.14}}}","budget_class":"fast","evidence":"basis: \"pyramid-classify {n} test files: u/i/e = {a}/{b}/{c}; e2e share ~{s}% ({conf} confidence)\"","remediation":{"quick_win":"move the top 20 E2E tests' logic down to integration/unit level (test the service, not the click).","structural":"rebuild the pyramid over time — write unit tests for all domain logic, integration for boundaries, keep E2E for < 10 user journeys; budget E2E runtime.","gold_standard":"Classic pyramid (e.g., 70/20/10); E2E < 10% runtime; failures localize within seconds; E2E covers only true user journeys.","effort":"🔶 ~2–4 h"}},
  "TEST-04": {"id":"TEST-04","category":"TEST","name":"Test Run Time","tier":"B","default_status":"measured","effort":"⚡ ≤30 min","v1":"PART","rollup":"standard","gates":[],"definition":"The full test suite takes so long that it throttles delivery — minutes of feedback on every commit, or so long that tests are skipped, split, or gamed.","why":"Feedback latency is the core of engineering speed. Long suites push people to skip tests locally, to not run the suite before merge, and to treat CI as the \"slow lane.\" It's both a symptom of test bloat (from the pyramid inversion, dead code, over-heavy E2E) and a cause of quality decay.","manifests":"CI pipeline metrics (suite duration trend), `pytest --durations`, Jest timings, \"tests take too long\" complaints, people committing without running tests, \"we split CI and hope\" configurations.","detection":"CI analytics — pipeline duration per stage, test-stage duration trend over quarters; per-test timing reports (`--durations=20`, Jest `--verbose`); measure P95 feedback loop (commit → test result).","yellow":"10–30 min suite, tests usually run before merge, slow tail known.","red":"> 30 min suite, or tests routinely not run locally, or CI times out and tests are dropped to keep deploy green.","yellow_rationale":"warning — still survivable, but the tax is real.","red_rationale":"at this speed the suite stops being run — it's ceremonial, not protective.","criteria":{"0":"tests not part of the merge loop.","1":"> 30 min or split-and-hope","2":"10–30 min","3":"< 10 min"},"scope":"Suite duration trend; build/install duration is VEL-01 — stage attribution separates them.","applicability":"`na_when: no test jobs in CI AND zero test files` → N/A (no suite to time). Zero-CI repos → unknown.","statusing":"measured_when:  never in v1                      # elapsed CI time ≠ instrumented suite timing\nestimated_when: >=5 runs sampled                 # clamp [1,2]; confidence low (04 §5 caveat mandatory)\nunknown_when:   <5 runs or no CI\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     low by rule (\"not full CI history\" caveat)","score_mapping":"Y/R values (10–30 / >30 min): see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: `Y_MIN <= p95 < R_MIN`\n- `1`: `p95 >= R_MIN` ∨ tests serially blocking every deploy (job-graph check)\n- `3`/`0` unreachable by construction","fact_schema":"{\"test04\": {\n  \"workflow\": \"ci.yml\", \"runs_sampled\": 20,\n  \"median_min\": 14.2, \"p95_min\": 27.8,\n  \"source\": \"actions-durations\"}}","budget_class":"api-budgeted","evidence":"basis: \"actions-durations n={k}: median {m}m, p95 {p}m (elapsed-time signal)\"","remediation":{"quick_win":"parallelize across shards/workers, move slow E2E out of the merge gate (nightly), fix the slowest 10 tests.","structural":"attack root causes — pyramid rebalance (TEST-03), hermetic fast tests, caching, and a runtime budget with a gate.","gold_standard":"Suite < 10 min P95; every engineer runs the suite before merge; a runtime budget enforced in CI.","effort":"⚡ ≤30 min"}},
  "TEST-05": {"id":"TEST-05","category":"TEST","name":"Skipped / Disabled Tests","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"A growing graveyard of `@skip`/`@Ignore`/`xit`/`pytest.skip`/commented-out tests — disabled with \"fix later\" intent that never comes.","why":"Skipped tests are *written-down coverage* — they document that a path was important enough to test and then abandoned. Each skip is a forgotten debt. A suite with many skips has systematically withdrawn its protection, and the trend usually tracks overall maintenance abandonment.","manifests":"`@Ignore`/`@Disabled` (JUnit), `@skip` (pytest/Jest `xit`), `describe.skip`, commented-out test blocks, \"temporarily disabled for release\" commits, tests excluded in CI config.","detection":"Grep for skip markers with `rg \"@skip|@Ignore|xit\\(|test.skip|pytest.mark.skip\"`, count by module and date of skip; git log for skip-adding commits (check dates); CI config exclusions.","yellow":"5–10% skipped, or skips concentrated in a few modules, some recent.","red":"> 10% skipped, or skips aged > 6 months with no ticket, or skips added to force a release through.","yellow_rationale":"warning — a fix-it-within-a-sprint item.","red_rationale":"the team is actively deleting its safety net to ship.","criteria":{"0":"skips used to force releases or coverage silently gone.","1":"> 10% or aged","2":"5–10%","3":"< 2%"},"scope":"Skip/disable hygiene; why suites flake is TEST-02, isolation causes TEST-07.","applicability":"`na_when: zero test files` (nothing to skip — reason recorded).","statusing":"measured_when:  >=1 test file parsed\nestimated_when: never                             # markers are facts\nunknown_when:   tree unparseable\nna_when:        zero test files\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium; low if blame unavailable (drop age subscore)\nscope_limited:  test-file read bound hit (file count / per-file bytes) -> measured + scope-limited","score_mapping":"Y/R values (5–10% / >10%; months-aged): see §3.\n\n- `3`: `skip_ratio < Y_RATIO`\n- `2`: Yellow band or recent skips only\n- `1`: `skip_ratio > Y_RATIO` with aged skips present\n- `0`: `skip_ratio > R_RATIO` ∨ mass aged disables (>6mo) on core-module tests","fact_schema":"{\"test05\": {\n  \"total_tests_est\": 344, \"skipped_total\": 31,\n  \"skip_ratio\": 0.09,\n  \"aged_skips\": [{\"file\": \"e2e/checkout.spec.ts\", \"age_days\": 233}],\n  \"ci_exclusions\": [\"--ignore=tests/flaky\"]}}","budget_class":"fast","evidence":"evidence: \"skip-scan: {k}/{n} tests skipped ({p}%); {a} older than {d}d ({files})\"","remediation":{"quick_win":"re-enable or delete each skip deliberately (delete-with-justification or fix-with-test); no skips without a linked ticket and owner.","structural":"CI gate that fails on new skips without a ticket; a monthly \"skip inventory\" review; fix the top skipped module's root cause.","gold_standard":"< 2% skipped, all with tickets + owners, none older than a sprint; new skips auto-blocked.","effort":"⚡ ≤30 min"}},
  "TEST-06": {"id":"TEST-06","category":"TEST","name":"Core Domain Untested","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":["G5"],"definition":"The highest-criticality flows — the code that makes or loses money, touches PII, or is the product's reason to exist — have no (or negligible) test coverage.","why":"Untested core logic is a *gate* (G5). It means the system's most important behavior is verified by production incidents, not by engineering. Modernizing or even touching that code becomes a bet. This indicator is the \"but the tests cover the wrong things\" trap — coverage can be high elsewhere while the crown jewels are naked.","manifests":"The billing/payments/quotes/compliance module with no tests, coverage report filtered by module shows the core at ~0%, \"we never wrote tests for that,\" incident history clustering on the same untested path.","detection":"Cross-reference the highest-criticality modules (from business mapping) against coverage reports per module; grep the core module for test files; check incident data for the untested path (defects = unverified behavior). Use a \"core-path map\" — pick 10 business-critical user journeys and check each has a test.","yellow":"Core paths partially tested (some journeys covered, gaps in edge cases), or tests exist but are E2E-only.","red":"Zero tests on the highest-criticality service or core journey (triggers G5).","yellow_rationale":"warning — the skeleton is there but the guard is thin.","red_rationale":"the most important behavior in the company is unverified — you cannot refactor it safely, and you cannot claim it works.","criteria":{"0":"core untested (triggers G5).","1":"core tested only via E2E or edge cases missing","2":"core partially tested (gaps)","3":"core fully tested"},"scope":"Whether core paths are tested; overall suite shape is TEST-03, coverage level TEST-01.","applicability":"`na_when: no source parsed`. Zero tests anywhere is score signal here, not N/A.","statusing":"measured_when:  never in v1                      # proximity ≠ coverage\nestimated_when: core set non-empty               # clamp [1,2]; confidence low always\nunknown_when:   core-path computation failed\nna_when:        never\nclamp:          [1,2]\nconfidence:     low by rule (\"business map missing\" caveat mandatory per the catalog conventions)","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: partial (`proximity >= Y_PROX`)\n- `1`: `proximity < Y_PROX`\n- `3`/`0` unreachable by construction","fact_schema":"{\"test06\": {\n  \"core_modules\": 22,\n  \"with_any_test\": 9,\n  \"proximity_pct\": 0.41,\n  \"untested_core_sample\": [\"billing/refund.py\", \"auth/session.py\"]}}","budget_class":"fast","evidence":"basis: \"core-proximity: {k}/{n} core modules have adjacent/referenced tests ({p}%); untested e.g. {files}\"","remediation":{"quick_win":"characterisation-test the core (capture current behavior, lock it), then fix the top 3 divergent behaviors.","structural":"treat the core as the highest test priority — require tests on every core change, build a test-heavy \"crown jewels\" suite, tie core coverage to the gate.","gold_standard":"All 10 core journeys have tests; core module coverage > 80%; a core change without tests cannot merge; incidents on core paths are rare and never \"first discovery.\"","effort":"🔶 ~2–4 h"}},
  "TEST-07": {"id":"TEST-07","category":"TEST","name":"Test Isolation & Hermeticity","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"Tests are not isolated — they depend on shared state: a live/shared database, shared fixtures mutated by earlier tests, execution order, wall-clock time, the network, or each other. They pass only in a particular environment or sequence.","why":"Non-hermetic tests are the root cause of flakiness, order-dependence, and the \"works on my machine\" suite. They also make parallelization impossible, slow everything down, and let prod-vs-test drift hide bugs. Modern test practice demands deterministic, isolated, fast tests.","manifests":"Tests using the shared dev DB, tests that mutate a global fixture, `sleep()` calls, tests assuming order (alphabetical luck), `--runInBand` required to pass, \"must run the DB locally,\" tests that need external services live.","detection":"Run suite in random order (`--shuffle`/`--random-order`/`pytest-randomly`) and in parallel — count failures; grep for `sleep`, shared DB connection strings in tests, `beforeAll` mutation of shared state; CI on fresh containers vs. warm caches.","yellow":"Some shared fixtures/order-dependence in peripheral suites; parallel run mostly passes.","red":"Suite requires single-threaded serial execution or shared live DBs to pass, or random-order runs fail broadly.","yellow_rationale":"warning — the rot is localized for now.","red_rationale":"the suite is environment-dependent — its results don't generalize to prod, and it cannot scale.","criteria":{"0":"environment-dependent suite, results don't transfer.","1":"serial-only or shared DB in a service","2":"some shared state, mostly passes","3":"hermetic + parallel"},"scope":"Suite reaction to shared state; the state itself is ARCH-07's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # grep hits cannot establish hermeticity either way\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"test07\": {\"status\": \"unknown\", \"reason\": \"isolation provable only by executing suite\",\n             \"static_hints\": {\"sleep_calls_in_tests\": 14, \"shared_db_url_in_tests\": true}}}","budget_class":null,"evidence":"emission: \"unknown — requires randomized/parallel suite execution (v2); static hints: {hint_summary}\"","remediation":{"quick_win":"run randomized + parallel CI to surface the worst offenders, fix shared-fixture tests, replace sleeps with waits.","structural":"hermetic test infrastructure — per-test DBs (Testcontainers), fixtures scoped to each test, deterministic time, no network in unit tests, parallel by default.","gold_standard":"Suite passes under random order and full parallelism on a fresh container; zero sleeps; tests never touch shared live infrastructure.","effort":"🔶 ~2–4 h"}},
  "TEST-08": {"id":"TEST-08","category":"TEST","name":"Quality Gates in CI","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"There are no automated quality gates — no static analysis (SAST/lint), no coverage threshold, no complexity budget, no security scan — blocking or reporting on the merge path. Quality relies entirely on human review.","why":"Gates are the difference between a *process* that maintains quality and a *hope* that it does. A codebase without gates is one where every quality debt is discovered by incident or by argument. It's also a signal the CI was built in an era before quality tooling, or that the team has given up on enforcement.","manifests":"CI that only builds and runs tests (or not even that), no lint step, no SAST (Semgrep/SonarQube/CodeQL), no coverage gate, no `knip`/complexity check, \"reviewers are the gate\" as the whole policy.","detection":"CI config audit — read the pipeline (GitHub Actions/`.gitlab-ci.yml`/Jenkinsfile): list jobs; check for lint/static-analysis/coverage/security stages; check if gates fail the build or just comment; count of merges that bypassed CI (admin merges).","yellow":"Linting only; no coverage or SAST gate; quality relies on review.","red":"No static analysis or quality gates of any kind on the merge path.","yellow_rationale":"warning — some guard exists but it's toothless on the important axes.","red_rationale":"every quality defect is discovered downstream — the process has no immune system either.","criteria":{"0":"no gates at all.","1":"gates exist but bypassable/comment-only","2":"lint-only, review as gate","3":"full gates enforced"},"scope":"Quality-gate presence/blocking; security-job specifics are SEC-10's row (orchestrator shares the parsed configs).","applicability":"never N/A. Zero CI configs (clause-b over enumerated tree) → score-0 measured, not N/A.","statusing":"measured_when:  tree enumerated                  # presence/absence is fully decidable\nestimated_when: CI configs exist but unparseable (rare)   # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: lint ∧ typecheck ∧ coverage ∧ SAST all present ∧ blocking\n- `2`: lint-only or partial gates; coverage gate absent\n- `1`: gates present but advisory-only on main path\n- `0`: no SAST/static analysis stage at all ∨ zero CI configs","fact_schema":"{\"test08\": {\n  \"ci_files\": [\".github/workflows/ci.yml\"],\n  \"gates\": {\"lint\": {\"present\": true, \"blocking\": true},\n             \"typecheck\": {\"present\": false},\n             \"coverage_gate\": {\"present\": true, \"blocking\": true, \"threshold\": 70},\n             \"sast\": {\"present\": false}},\n  \"advisory_only_sites\": 1,\n  \"branch_protection_known\": false}}","budget_class":"fast","evidence":"evidence: \"ci-audit {files}: gates L/T/C/S = {l}/{t}/{c}/{s}; blocking={b}; advisory sites={a}\"","remediation":{"quick_win":"add lint + SAST (Semgrep/CodeQL/SonarQube) as failing stages, add a coverage gate on core, block admin bypass (require justification audit).","structural":"define the quality bar in code (lint rules, complexity budgets, coverage thresholds, security checks) and let CI enforce it; tie all gates to the same config the team reviews.","gold_standard":"CI fails on lint, SAST, coverage, complexity, and security findings; bypasses are impossible or audited; the gates' config is itself reviewed.","effort":"⚡ ≤30 min"}},
  "TEST-09": {"id":"TEST-09","category":"TEST","name":"Mutation Testing Score","tier":"B","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"Mutation testing results — the percentage of injected mutants (faults) the test suite actually kills — indicating whether the suite *verifies* behavior or merely *executes* code. A suite can have high coverage and kill almost no mutants (assertions missing or weak).","why":"Coverage measures \"did we run the code,\" not \"would we catch a bug in it.\" A low mutation score means the suite is theater — green CI with low real protection. For a modernization decision, it's the difference between \"refactor with confidence\" and \"refactor into a brick wall.\"","manifests":"Mutation tool reports — Stryker (JS/TS/Java/C#), MutPy (Python), PIT (Java), go-mutesting; a suite with high line coverage but weak assertions, tests that only call functions without asserting outcomes, snapshot-heavy tests that auto-update.","detection":"Run mutation testing on a representative module (often the core domain) — Stryker/PIT/MutPy default operators; compute killed/overall mutant ratio; time-box to a module (full-repo mutation is slow). Watch for equivalent mutants and timeouts as noise.","yellow":"60–80% mutation score; some survivors in edge cases; assertions weak in peripheral tests.","red":"< 60% mutation score on the core module, or surviving mutants in security/pricing/correctness logic.","yellow_rationale":"decent, but surviving mutants mark blind spots.","red_rationale":"the suite looks green but wouldn't catch a real bug in the code that matters.","criteria":{"0":"suite executes but verifies almost nothing.","1":"< 60% core or key-logic survivors","2":"60–80%","3":"≥ 85% core"},"scope":"Mutant kill strength; ordinary coverage is TEST-01's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # a configured-but-unrun score would be exactly a scored guess\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"test09\": {\"status\": \"unknown\",\n             \"reason\": \"mutation testing executes the suite against mutants (v2)\",\n             \"config_present\": [\"stryker.conf.json\"]}}","budget_class":null,"evidence":"emission: \"unknown — needs a time-boxed mutation run on a core module (v2 deep scan)\"","remediation":{"quick_win":"run mutation on the top-criticality module, fix the highest-value survivors (add assertions, kill branches).","structural":"run mutation on core modules in CI (time-boxed), use surviving-mutant count as a tracked quality metric, strengthen weak assertions.","gold_standard":"Core module mutation score ≥ 85%; mutation runs in CI on the core; survivors are reviewed and justified.","effort":"🔷 ~1–2 days"}},
  "TEST-10": {"id":"TEST-10","category":"TEST","name":"Test Maintenance Burden","tier":"B","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"YES","rollup":"standard","gates":[],"definition":"The ongoing cost of keeping the suite green — how often tests break from *infrastructure* rather than *behavior* changes, how much engineering time goes to fixing/debugging tests vs. writing features, snapshot churn, and the ratio of \"test fix\" commits to feature commits.","why":"A suite that costs more to maintain than it saves is net-negative — and teams quietly stop investing in it, which then shows up as the other TEST indicators (flakes, skips, inverted pyramid). High maintenance burden is the *cause* under the symptoms.","manifests":"Git log (\"fix test\", \"update snapshot\", \"flaky fix\" commits), snapshot churn (CI updating goldens constantly), test-debugging sessions, PRs blocked by unrelated test failures, `--update-snapshots` habitual use, \"tests changed because we changed X\" infra coupling.","detection":"Git archaeology — count commits matching `/fix test|snapshot|flake|test update/i` as a share of all commits; snapshot update frequency; time-tracking (rough survey); correlated-failure analysis (which production change breaks which unrelated tests).","yellow":"10–20% of commits are test maintenance; snapshot churn noticeable; tests coupled to infra details.","red":"> 25% of commits are test maintenance, or tests break on every infra/rename change (coupled to internals not behavior), or the team actively dreads the suite.","yellow_rationale":"warning — the tax is growing.","red_rationale":"the suite has become a tax, and the response will be abandonment.","criteria":{"0":"> 25%, team avoiding the suite.","1":"20–25% or internal-coupled","2":"10–20%","3":"< 10% maintenance"},"scope":"Maintenance drag of the suite itself; suite shape TEST-03, flakiness TEST-02.","applicability":"`na_when: zero test files`. History <6mo → unknown (insufficient window).","statusing":"measured_when:  never auto-measured            # fix-vs-chore classification is heuristic\nestimated_when: >=200 commits in window        # clamp [1,2]; confidence medium if >=1000\nunknown_when:   history <6 months\nna_when:        zero test files\nclamp:          [1,2]\nconfidence:     medium with full-year window\nscope_limited:  shrunk window -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: `test_fix_share < R_SHARE` but snapshot churn elevated\n- `1`: `test_fix_share >= R_SHARE` ∨ chronic monthly snapshot churn\n- `3`/`0` unreachable by construction","fact_schema":"{\"test10\": {\n  \"commits_window\": 4210, \"test_touching\": 380,\n  \"test_fix_share\": 0.34,\n  \"snapshot_updates_per_month\": 11,\n  \"window_days\": 365}}","budget_class":"fast","evidence":"basis: \"git-archaeology {n} commits/{w}d: test-fix share {p}%; snapshots {s}/mo\"","remediation":{"quick_win":"break the coupling — assert behavior not internals (mock at boundaries, not implementation), stabilize flaky snapshots, stop auto-updating snapshots.","structural":"treat the suite as a product (owner, budget, KPIs), refactor tests to test contracts not internals, track test-maintenance share as a metric with a ceiling.","gold_standard":"< 10% of commits are test maintenance; tests break only when behavior changes; the suite is seen as an asset, not a tax.","effort":"🔷 ~1–2 days"}},
  "SEC-01": {"id":"SEC-01","category":"SEC","name":"Unpatched Vulnerabilities","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":["G2"],"definition":"Known, scored vulnerabilities (OSV/CVEs) affecting the runtime, dependencies, or container images are present, and unpatched — with an age beyond acceptable exposure windows.","why":"Every unpatched CVE is a *known* open door. The CVE age is a direct measure of maintenance abandonment: modern teams patch in days; obsolete systems accumulate for months. It's also the most defensible, unarguable \"this codebase is obsolete\" datum you can hand an executive.","manifests":"SCA reports (Snyk/Dependabot/Trivy/OSV), image scans (Trivy/Grype/Clair), patch dashboards, CVEs on the lockfile, \"no scan exists\" in CI.","detection":"Software Composition Analysis — `trivy repo/image`, `snyk test`, `npm audit`, `pip-audit`, `osv-scanner`, `dependabot` alert dashboard, Grype. Produce a themed report: critical/high/open-days/exposure (is the affected path internet-exposed?). Filter noise (dev-only, reachability consideration).","yellow":"1–5 High CVEs open > 30 days, or any Critical open ≤ 14 days but already in the patch queue.","red":"Any Critical CVE > 14 days on an internet-exposed path (triggers **G2**), or High CVEs accumulating with no patch process.","yellow_rationale":"known risk with a live fix-window — warning, not fire, provided the trend is downward.","red_rationale":"an exposed, known-critical vuln older than two weeks is a breach waiting to happen.","criteria":{"0":"exposed critical > 14 days (G2).","1":"critical open in isolated path","2":"high CVEs 30–60 days","3":"zero open criticals, SLAs met"},"scope":"Open vulns in dependencies and their patch state; chain/malware quality of transitive graph is SEC-06.","applicability":"`na_when: zero dependency manifests` (clause-b). Else applicable.","statusing":"measured_when:  >=1 scanner completed over a parsed lockfile\nestimated_when: partial lockfile coverage only            # clamp [1,2], confidence low\nunknown_when:   all scanners failed / no advisories reachable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium (authoritative advisory DBs)\nscope_limited:  private deps unauditable -> estimated + scope-limited","score_mapping":"Y/R values (High>30d etc.): see §3.\n\n- `3`: zero open High/Critical\n- `2`: High findings within Yellow age band\n- `1`: aged Highs or Critical with fix available but unmerged < R_DAYS\n- `0`: `any(severity==CRITICAL ∧ age_days > 14 ∧ (core-closure ∨ exposure unknown))`","fact_schema":"{\"sec01\": {\n  \"findings\": [{\"id\": \"CVE-2025-1234\", \"pkg\": \"urllib3\", \"severity\": \"CRITICAL\",\n                 \"age_days\": 41, \"fix_available\": true, \"in_core_import_closure\": true}],\n  \"critical_open_over_14d\": 1, \"high_open\": 4,\n  \"tools\": [\"trivy 0.55\", \"osv-scanner 1.9\"]}}","budget_class":"fast","evidence":"evidence: \"trivy+osv: {n} open ({c} crit>{d}d, {h} high); worst {cve} on {pkg} age={a}d\"","remediation":{"quick_win":"patch the open Criticals/Highs in the exposure window — today; re-scan.","structural":"a patch SLA policy (Critical ≤ 7 days, High ≤ 30), automated patching (Dependabot/Renovate auto-merge with CI as the gate), and a \"no open Critical in prod\" rule enforced by the security review.","gold_standard":"Zero open Criticals; Highs < 30 days; automated scans in CI; patch SLA documented and met for 4 straight quarters.","effort":"🔶 ~2–4 h"}},
  "SEC-02": {"id":"SEC-02","category":"SEC","name":"Hardcoded Secrets & Credentials","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":["G1"],"definition":"API keys, passwords, tokens, database credentials, private keys, or S3/cloud credentials are hardcoded in source code, committed in history, present in config files in the repo, or exposed in logs/artifacts.","why":"This is the clearest \"belongs to a previous era\" signal — modern practice is secret management (Vault/AWS Secrets Manager/SSM/env-injection) from day one. Hardcoded secrets indicate not just one mistake but an absence of the *tooling* and *discipline* that modern systems have. It's a gate (G1) because active secrets are directly exploitable.","manifests":"`password = \"...\"`, `AWS_SECRET=AKIA...`, `.env` committed to the repo, config files with creds, connection strings with embedded passwords, keys in image layers, secrets in build logs, API docs with tokens.","detection":"Secret scanners — Gitleaks, TruffleHog, `git secret scan`, Semgrep secret rules, GitHub secret scanning, `trufflehog git file://. --only-verified`; scan current tree *and* full git history; check container image layers (`dive`, Trivy secret scan); check logs/artifacts.","yellow":"Secrets in commit history that are already revoked/rotated; a few live tokens in non-prod configs.","red":"Active, valid credentials in source, config, or history — especially in core/prod paths (triggers **G1**).","yellow_rationale":"a real hygiene failure, but not immediately exploitable.","red_rationale":"direct, immediate compromise: the credential works today.","criteria":{"0":"active creds in core/prod (G1).","1":"live secret in a non-critical config","2":"revoked secrets in history only","3":"no secrets, manager in place"},"scope":"Secrets/credentials in source, config, and history; supply-chain malware risk is ECOS-10.","applicability":"never N/A for scored repos.","statusing":"measured_when:  gitleaks completed on tree (+history if available)\nestimated_when: never                            # scanner output is fact; absence-after-scan is not-proven evidence\nunknown_when:   scanner failed to run at all\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium; low if history truncated\nscope_limited:  history budget hit -> measured + scope-limited note (tree result stands)","score_mapping":"Criteria: see §3.\n\n- `3`: zero findings anywhere, clean-run evidence\n- `2`: history-only findings, all plausibly rotated (age > rotation window) — Yellow band per entry\n- `1`: unverified findings in isolated paths, or aged history-only secrets in core paths\n- `0`: any finding in current tree ∧ (in core/config-deploy path ∨ verified-live)","fact_schema":"{\"sec02\": {\n  \"tree_findings\": [{\"rule\": \"aws-access-token\", \"file\": \"config/prod.py\", \"verified\": false}],\n  \"history_only_findings\": 6,\n  \"verified_live\": 0,\n  \"history_scanned_full\": true}}","budget_class":"fast","evidence":"evidence: \"gitleaks: tree={t} findings ({v} verified-live); history-only={h} (full={bool}); worst {rule}@{file}\"","remediation":{"quick_win":"rotate EVERY leaked credential immediately (the exposure window starts at commit time, not discovery time), remove from current tree, switch to env vars.","structural":"adopt a secret manager + injection (Vault, Secrets Manager), ban secrets in code via CI scanners on every commit *and* a history scrub, least-privilege per environment, kill the \"secrets in docs\" habit.","gold_standard":"Zero secrets in the tree or history; secrets injected at runtime from a manager; CI blocks secret commits; rotation drill run annually.","effort":"⚡ ≤30 min"}},
  "SEC-03": {"id":"SEC-03","category":"SEC","name":"Missing Web Security Controls","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":["G4"],"definition":"The application is missing modern transport/presentation security controls — TLS configuration outdated (TLS 1.0/1.1), missing security headers (CSP, HSTS, X-Content-Type-Options, frame options), no input validation/sanitization at entry points, no output encoding — and OWASP Top-10 classes (SQLi, XSS, RCE, SSRF) are reachable in application flows.","why":"Web security controls are the *price of entry* for a modern system — they're free to add and non-negotiable by default in any modern framework. Their absence marks a codebase that predates the security education of the last decade. Reachable OWASP Top-10 classes in core flows is a gate (G4).","manifests":"Response headers (curl `-I`), TLS scan (ssllabs, `testssl.sh`), raw SQL string concatenation, unsanitized user input into queries/renderers, `innerHTML` with user data, unvalidated file uploads, SSRF-able fetch targets, deserialization of untrusted input.","detection":"DAST (OWASP ZAP, Burp, Nuclei) against a staging env, SAST (Semgrep, SonarQube, CodeQL rule packs) for injection patterns, header/TLS scanning (`testssl.sh`, Mozilla Observatory, `securityheaders.com`), manual review of input-handling paths. Map findings to OWASP Top-10 categories and reachability.","yellow":"Missing headers, outdated TLS (1.1 tolerated), input validation incomplete on non-critical paths.","red":"Reachable SQLi/RCE/broken auth/SSRF in core flows, or no input validation at all at any entry point (triggers **G4**).","yellow_rationale":"hardening gaps — real but not immediately exploitable at scale.","red_rationale":"actively exploitable vulnerability classes in the software's purpose — a breach in training.","criteria":{"0":"reachable Top-10 in core (G4).","1":"reachable finding in isolated path","2":"hardening gaps outside core","3":"no findings, A grades"},"scope":"Deployed-app control surface (headers/TLS/OWASP-reachable); auth-flow weaknesses are SEC-04.","applicability":null,"statusing":"measured_when:  never from URL\nestimated_when: never                            # header greps in code prove intent, not enforcement\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"sec03\": {\"status\": \"unknown\",\n            \"reason\": \"web controls observable only on a deployed target\",\n            \"g4_state\": \"needs-verification\"}}","budget_class":null,"evidence":"emission: \"unknown — needs staging target for headers/TLS/DAST (deep scan); G4 pending that check\"","remediation":{"quick_win":"enable modern headers (HSTS/CSP via middleware), upgrade TLS, fix the top reachable injection points with parameterized queries and validation.","structural":"framework defaults (most modern frameworks secure headers by default — upgrade), SAST+DAST in CI, input validation at every entry, an injection-class bug ban (semantic gate).","gold_standard":"A+ header/TLS grades, zero reachable Top-10 findings, SAST+DAST wired into CI, validation at all boundaries.","effort":"🔶 ~2–4 h"}},
  "SEC-04": {"id":"SEC-04","category":"SEC","name":"Authentication & Authorization Weaknesses","tier":"B","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":["G4"],"definition":"Weak or missing authN/authZ: default credentials, no auth on admin/internal endpoints, session flaws (predictable tokens, no expiry/rotation), broken password policy, missing MFA on privileged access, coarse or absent role-based access control, broken authorization checks (IDOR).","why":"Modern systems treat auth as infrastructure (OIDC/SAML SSO, MFA, policy engines). A codebase rolling its own sessions with a hand-rolled token scheme, or protecting admin paths by convention, is an era artifact — and the results are directly exploitable (part of G4).","manifests":"Default creds (`admin/admin`) in setup scripts, session tokens as mutable cookies, no expiry/rotation, `isAdmin` checked on the client, authorization checked on the UI not the server, no MFA anywhere (especially admin), homegrown JWT without verification of `alg`, IDOR (fetching by id without ownership check).","detection":"Security review (pentest-style) of auth flows, SAST rules (broken access control), manual walk of admin/internal endpoints with auth stripped, session inspection (token predictability/expiry), OWASP ZAP \"forced browsing,\" check for client-side-only authorization, IDOR probes on object-id endpoints.","yellow":"Weak session policy (long expiry, no rotation), coarse RBAC (all-or-nothing admin), no MFA on some privileged paths, some IDOR-able endpoints.","red":"Default/known credentials, unauthenticated admin/internal paths, org-level broken authN (session hijackable), or authorization enforced only client-side in core flows.","yellow_rationale":"real weaknesses under the \"still auth'd\" threshold.","red_rationale":"the barrier either doesn't exist or is client-side theater.","criteria":{"0":"default creds / unauthorized admin / client-side-only (G4).","1":"broken control in an isolated service","2":"weakness in non-critical areas","3":"managed identity + enforced authz"},"scope":"AuthN/AuthZ flow weaknesses; duplicated cross-cutting auth infrastructure is ARCH-12, deployed-control surface SEC-03.","applicability":"`na_when: no auth-adjacent code or routes detected` (pure CLI tool, clause-b).","statusing":"measured_when:  never auto-measured            # proxies cannot prove exploitability\nestimated_when: >=2 matcher classes ran        # clamp [1,2]; confidence LOW always (rule)\nunknown_when:   no parseable auth surface\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     low by definition (04 §5: \"label low\")","score_mapping":"Criteria: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: isolated smell sites, none on core/auth paths\n- `1`: any hit class touching core-route set ∨ multiple classes firing\n- `3`/`0` unreachable by construction","fact_schema":"{\"sec04\": {\n  \"routes_total\": 84, \"routes_without_server_middleware\": 9,\n  \"client_side_only_role_guards\": 4,\n  \"session_config_flags\": {\"insecure_cookie\": true},\n  \"default_cred_literals\": [],\n  \"debug_bypass_hits\": [{\"file\": \"app.py\", \"pattern\": \"if DEBUG: skip_auth()\"}]}}","budget_class":"fast","evidence":"basis: \"auth-proxy: {r}/{n} routes lack server middleware; {c} client-only guards; flags {list} [low confidence]\"","remediation":{"quick_win":"kill default creds, add auth + server-side authorization to every endpoint (route registry), enable MFA on privileged roles, fix the top IDORs.","structural":"move to managed identity (SSO/OIDC, platform IAM), policy-based authorization (OPA/AWS IAM/ABAC), automated authz tests (walk every route asserting enforcement), session best practices.","gold_standard":"All endpoints server-side auth'd and authz'd, MFA everywhere privileged, managed SSO + policy engine, authz coverage test in CI.","effort":"🔶 ~2–4 h"}},
  "SEC-05": {"id":"SEC-05","category":"SEC","name":"Audit Logging Deficits","tier":"B","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"The system has no (or inadequate) audit trail: administrative actions, PII access/modification, authentication events, and permission changes are not logged — or logs are unstructured, tamperable, or not retained.","why":"Audit logs are how you learn what happened — required for every serious incident, every compliance framework (SOC2, HIPAA, GDPR' accountability), and every post-mortem. Their absence means the system is un-forensic: if (when) something happens, you will not know the who/when/what. Modern systems log events as a first-class, structured, append-only concern.","manifests":"Admin endpoints with no logging, no auth-event log, PII read/modify paths without access records, logs that get wiped on deploy, unstructured ad-hoc `console.log`, no retention policy, no tamper protection.","detection":"Log/config audit — check log sinks, retention, and content; automation: review the auth module and admin APIs for audit statements; check audit trail survives redeploy (external sink vs. local fs); check log schema (structured JSON with event type, actor, target, timestamp, request ID); run an action and confirm it's traceable end-to-end.","yellow":"Unstructured logs or missing request correlation IDs; partial coverage (some sensitive actions logged, some not).","red":"Zero audit trails for administrative access, PII modification, or authentication events.","yellow_rationale":"warning — reconstruction is hard but possible.","red_rationale":"you cannot investigate — regulatory and forensic dead-end.","criteria":{"0":"no audit trail at all.","1":"major gaps in sensitive paths","2":"partial coverage, unstructured","3":"complete, structured, retained"},"scope":"Audit-trail deficits; observability instrumentation generally is PERF-01.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # presence-of-logging-library proves nothing about audit coverage\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"sec05\": {\"status\": \"unknown\",\n            \"reason\": \"audit-trail content/retention needs runtime + sink audit\"}}","budget_class":null,"evidence":"emission: \"unknown — requires auditing auth/admin/PII event emission against external sinks (deep scan)\"","remediation":{"quick_win":"add audit logging to the top admin/PII/auth paths with a structured schema, ship logs to an external durable sink, set retention.","structural":"treat audit as a compliance requirement — append-only/crypto-chained where needed, centralized log platform, automated test asserting every sensitive action produces an audit event.","gold_standard":"Every admin/PII/auth event logged structured (actor, action, target, time, request ID), durable, retained per policy, and tamper-evident; an automated coverage test exists.","effort":"🔶 ~2–4 h"}},
  "SEC-06": {"id":"SEC-06","category":"SEC","name":"Insecure Transitive Chains","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The vulnerability surface hides deep in the transitive dependency graph — chains of unmaintained or suspicious packages below the surface that could carry malware, or known vulnerable paths reachable only through indirect dependencies.","why":"Deep scanning is the difference between \"we checked the obvious\" and \"we actually know what we ship.\" Legacy codebases usually have legacy graphs (deep, unpruned, invisible) — and a deep, unmonitored graph is where the next SolarWinds/event-stream-class event happens. (Pairs with ECOS-06/ECOS-10.)","manifests":"Lockfiles hundreds/thousands deep, dependency trees where the vulnerable package is 8 levels down, packages that appear to be maintained yet contain modified forks, deep chains into abandoned libs (ECOS-03), scanner reports with buried reachable paths.","detection":"Deep SCA — `osv-scanner --experimental-local-db`, `pip-audit -r`, `npm audit --all`, Socket.dev for provenance chain, Grype lockfile scanning, reachability analysis (Snyk Reachable, GitHub reachability). Trace each open CVE to the top-level packages that can trigger it; check depth and reachability. Also check vendored code for sub-scanning.","yellow":"Vulnerabilities only reachable through deep chains (depth > 5) into unmaintained packages, without likely exploit reachability.","red":"Known malware/hijacked package confirmed in the lockfile, or a reachable critical vuln that only lives in the transitive graph and has no patch (see also ECOS-10).","yellow_rationale":"warning — risk exists but is buried; still must be managed.","red_rationale":"the actual shipping software contains malicious or unpatchable code you didn't choose.","criteria":{"0":"malware/any-unpatchable in the shipping graph (G2-adjacent).","1":"reachable deep vuln below top 2 levels","2":"deep-chain vulns non-reachable","3":"deep-scan clean"},"scope":"Transitive chain quality/reachability; direct-dep vulns are SEC-01, abandonment is ECOS-03.","applicability":"ECOS-02 clause-b.","statusing":"measured_when:  >=1 scanner completed on parsed graph\nestimated_when: graph partially resolvable                # clamp [1,2], confidence low\nunknown_when:   no lockfile\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium (exhaustive lockfile surface)\nscope_limited:  private transitive segment -> estimated + scope-limited","score_mapping":"Criteria: see §3.\n\n- `3`: no vulnerable transitives reachable in prod scope\n- `2`: vulnerable transitives exist, none reachable, shallow chains only\n- `1`: deep unmaintained chain into a peripheral prod path\n- `0`: `any(malware_class_hits)` ∨ vulnerable transitive reachable from core imports","fact_schema":"{\"sec06\": {\n  \"transitive_total\": 1316,\n  \"vulnerable_transitive\": [{\"pkg\": \"minimist\", \"version\": \"1.2.0\", \"depth\": 4,\n                              \"via\": [\"mkdirp\"], \"reachable_from_core\": true}],\n  \"malware_class_hits\": []}}","budget_class":"fast","evidence":"evidence: \"osv-deep: {k} vulnerable transitives of {n} ({r} core-reachable); worst {pkg} depth={d} via {via}\"","remediation":{"quick_win":"use tooling to map reachable chains to top-level packages, plan removals/forks of the top offenders, add deep scanning to CI.","structural":"prune the graph (replace deep-chain producers), vendoring review, dependency budget (ECOS-06), provenance verification, and an incident runbook for \"malicious package found.\"","gold_standard":"Deep scanning in CI with reachability intelligence; zero malware; vulnerable chains mapped and justified; unmaintained chains trending to zero.","effort":"🔶 ~2–4 h"}},
  "SEC-07": {"id":"SEC-07","category":"SEC","name":"Patch Cadence & Update Workflow","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The org has no working patch pipeline — security updates arrive via occasional heroics rather than a continuous, automated, gated flow. Lockfiles sit stale, Dependabot/Renovate is off, patches wait for \"the next release.\"","why":"Patch cadence is the *process* that turns SEC-01's findings into fixes. Absent a cadence, every CVE is a project; present, it's a routine Tuesday. Its absence marks a maintenance model abandoned by modern practice (auto-update + CI-as-gate).","manifests":"No Dependabot/Renovate, or the bot's PRs accumulate > 500 open, old lockfile dates, manual `docker build` on servers, \"we batch patches once a year,\" security patches deferred for feature freezes, no staging for patch validation.","detection":"Automation audit — bot presence + PR age distribution, lockfile last-updated date, release-process gate (do patches require a full release train?), patch ticket SLAs, how long between a CVE report and a fix deploy (look at history).","yellow":"Manual patch process, patches within 30–90 days, automation absent but SLA roughly met.","red":"No automation, patches routinely > 90 days or deferred for releases, or \"we can't patch because the build breaks\" (unpatched = systemic).","yellow_rationale":"warning — it works, barely, and only because people carry it.","red_rationale":"the pipeline is broken, so exposure accumulates structurally.","criteria":{"0":"no pipeline, systemic exposure.","1":"batch/heroic patching","2":"manual but within 30–90 days","3":"automated + SLA met"},"scope":"Update workflow and freshness; the vulnerability content of what's stale is SEC-01.","applicability":"never N/A for repos with manifests; no-manifest trees → clause-b N/A.","statusing":"measured_when:  manifest parsed                            # presence/absence of workflow is decidable either way\nestimated_when: GH API unavailable -> bot+lockfile facts only   # clamp [1,2], confidence low\nunknown_when:   no manifests\nna_when:        clause-b fired (no manifests at all)\nclamp:          [1,2]\nconfidence:     medium with full PR data\nscope_limited:  PR page truncation -> estimated + scope-limited","score_mapping":"Y/R values (>90d stale etc.): see §3.\n\n- `3`: bot present ∧ `lockfile_age_days < Y_DAYS` ∧ p95 PR age low\n- `2`: automation present but backlog growing / lockfile in Yellow band\n- `1`: manual-only patching (no bot) but fresh lockfile\n- `0`: no patching workflow ∧ `lockfile_age_days > R_DAYS`","fact_schema":"{\"sec07\": {\n  \"bot\": {\"present\": true, \"tool\": \"dependabot\", \"ecosystems\": [\"npm\", \"pip\"]},\n  \"lockfile_age_days\": 12,\n  \"open_bot_prs\": {\"total\": 14, \"median_age_days\": 9, \"p95_age_days\": 61, \"oldest_ignored\": 210}}}","budget_class":"api-budgeted","evidence":"evidence: \"patch-cadence: {tool} on {ecos}; lockfile {d}d old; open bot PRs {n} (p95 {p}d)\"","remediation":{"quick_win":"enable Dependabot/Renovate with auto-merge on green for patch/minor updates, act on the security-only PRs first.","structural":"a scheduled patch lane (weekly security window, CI gates), environment-per-ticket to stage patches, measured SLA with an executive dashboard.","gold_standard":"Patches automated, applied within SLA (Crit ≤ 7d, High ≤ 30d), CI validates every patch, zero manual patch heroics.","effort":"⚡ ≤30 min"}},
  "SEC-08": {"id":"SEC-08","category":"SEC","name":"Compliance Drift","tier":"D","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"The system is out of alignment with the compliance frameworks it must meet (SOC 2, ISO 27001, GDPR, HIPAA, PCI-DSS, or internal policy controls) — evidence collection is manual, control mapping is stale or nonexistent, and required safeguards (encryption in transit/at rest, data retention, right-to-erasure, attestation) are missing.","why":"Compliance is a contract with the market — customers, regulators, insurers. Drift means the codebase is no longer *certifiable*, which blocks sales, renewals, and funding, and signals the security program itself is under-resourced (all SEC indicators correlate).","manifests":"Missing encryption at rest, no data-retention/erasure flows (GDPR), controls without evidence (SOC2), audit findings closed as \"accepted risk\" en masse, no data classification, PII stored in unencrypted logs or denormalized blobs, outdated policy docs vs. actual behavior.","detection":"Control-mapping audit — inventory the required control set, verify each against implementation (encryption config, retention jobs, erasure endpoints, log retention, access reviews); check evidence-generation (is it automated or a manual spreadsheet?); review recent audit findings and acceptances. Tools: compliance scanners (e.g., CSPM/Vanta/Drata evidence), manual walkthrough.","yellow":"Partial control mapping, manual evidence collection, a few accepted-risk findings, some unencrypted stores.","red":"No mapping or evidence to required frameworks, no encryption at rest, no retention/erasure capability, or audit findings closed without remediation.","yellow_rationale":"warning — manageable, but auditors will flag it.","red_rationale":"the system cannot be certified or defended — a business blocker.","criteria":{"0":"unmapable to frameworks, no core safeguards.","1":"no evidence automation, accepted risks growing","2":"partial mapping, manual evidence","3":"mapped + auto-evidenced"},"scope":"Control-framework drift; technical controls that feed it (backups, logging) live in DATA-06/SEC-05.","applicability":null,"statusing":"measured_when:  never\nestimated_when: never                            # compliance guesses are reputation-fatal\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"sec08\": {\"status\": \"unknown\", \"reason\": \"control mapping requires human audit against a framework scope\"}}","budget_class":null,"evidence":"emission: \"unknown — needs a scoped control-mapping audit (SOC2/GDPR/HIPAA); see deep-dive checklist\"","remediation":{"quick_win":"map the top 10 required controls to evidence today, automate the biggest evidence gaps (logs, backups, review reports).","structural":"continuous compliance automation (CSPM tools, evidence pipelines), close the accepted-risk list to a bounded, tracked set, encryption at rest everywhere, retention/erasure as engineering backlog items.","gold_standard":"Controls auto-evidenced, near-zero accepted-risk, encryption + retention/erasure automated, audit-ready at any moment.","effort":"🔶 ~2–4 h"}},
  "SEC-09": {"id":"SEC-09","category":"SEC","name":"Input Robustness & Fuzzing","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"YES","rollup":"standard","gates":[],"definition":"The system parses untrusted input (uploads, formats, network payloads, configs) with no fuzzing coverage, no input-validation hardening, and no crash-memory-safety testing — a hand-maintained \"we trust the data\" posture.","why":"Fuzzing is how the modern era finds memory and parser bugs; it's standard practice in any security-mature org. Its absence is a direct vulnerability-miss signal for anything that ingests foreign bytes — and parsers are where remote code execution lives.","manifests":"File-upload endpoints, document viewers, invoice/PDF/XML/JSON/CSV parsing, archive extraction, image processing, serialization boundaries — with no fuzz harnesses (*fuzz* targets), no `-fsanitize` builds, no structured-input validation.","detection":"Fuzz harness inventory (AFL, libFuzzer, Jazzer, `cargo-fuzz`, `go fuzz`, `oss-fuzz` presence); memory-checker builds (ASan/UBSan) existence; run a short fuzz campaign on the top parser (e.g., `libFuzzer` for 30 min) and measure crashes/hangs; inspect input-validation layers for fuzz-blocking (canary that rejects early).","yellow":"Sanitizer builds and some validation exist, but no fuzz harnesses; a couple of untrusted parsers unhardened.","red":"Untrusted-input parsers (especially any memory-unsafe language or complex format) with no fuzzing *and* no validation hardening — or known parser CVEs unaddressed.","yellow_rationale":"warning — the tooling farm is half-seeded.","red_rationale":"an unguarded byte-receiving boundary is a standing RCE/buffer-overflow invitation.","criteria":{"0":"unguarded untrusted-input parsers in core.","1":"unhardened parsers in peripheral","2":"sanitizers, no harnesses","3":"fuzzed + sanitized"},"scope":"Fuzz-readiness posture; actual injection vulnerabilities are SEC-03/04 rows.","applicability":"`na_when: repo has no input-parsing surface class (no parsers/decoders/protocol handlers detected)` → clause-b N/A with the detector's evidence listed.","statusing":"measured_when:  tree enumerated                  # inventory is a fact; scored as presence-only\nestimated_when: parser-surface detection uncertain -> applicability ambiguous   # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        no parsing surface (clause-b, evidence recorded)\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  none typical","score_mapping":"Criteria: see §3.\n\n- `3`: harnesses ∧ sanitizers ∧ continuous fuzzing\n- `2`: harnesses present, sanitizers partial\n- `1`: sanitizers only ∨ single stale harness\n- `0`: parsing surface exists ∧ zero harness/sanitizer evidence anywhere","fact_schema":"{\"sec09\": {\n  \"harnesses\": [{\"path\": \"fuzz/fuzz_parse.c\", \"engine\": \"libFuzzer\"}],\n  \"sanitizers_in_build\": true,\n  \"continuous_fuzzing\": {\"oss_fuzz\": false, \"scheduled_workflow\": false},\n  \"parser_surface_detected\": [\"json\", \"yaml\", \"http\"]}}","budget_class":"fast","evidence":"evidence: \"fuzz-inventory: {k} harnesses ({engines}); sanitizers={bool}; continuous={bool}; surface={classes}\"","remediation":{"quick_win":"stand up fuzz harnesses for the top 3 untrusted parsers, run sanitizer builds, harden validation at those boundaries (limits, types, structure).","structural":"fuzz-in-CI for parser-adjacent code, migrate memory-unsafe parsers, input-validation as a platform concern, adversarial corpus maintenance.","gold_standard":"Every untrusted parser fuzzed in CI with sanitizers, zero standing crashes, validation layers reject early and clearly.","effort":"🔷 ~1–2 days"}},
  "SEC-10": {"id":"SEC-10","category":"SEC","name":"Security Testing in CI","tier":"A","default_status":"measured","effort":"🔷 ~1–2 days","v1":"YES","rollup":"standard","gates":[],"definition":"Security tooling (SAST, secret scanning, dependency scanning, container scanning, and periodic DAST/pentest) is absent from CI or performed ad hoc — meaning security is found downstream, by incidents and audits, rather than caught at merge time.","why":"\"Shift-left\" security (gates in CI) is the modern baseline. A codebase without it is relying on human reviewers for security, which — as every breach analysis shows — is not a strategy. This indicator measures whether the *process* is modern even when today's findings are clean.","manifests":"CI with no SAST job (Semgrep/CodeQL/SonarQube), no secret scan step, no dependency scan (or run only weekly), no container image scan, no `trivy` step, pentests done \"when someone remembers,\" no threat modelling artifacts.","detection":"CI config audit — inventory security jobs; check they fail the build (not comment-only) and scan all diff contexts; check secret scan covers history; check container/image scanning on every build; check DAST/pentest cadence records; verify findings have an owner+tracking (not just printed).","yellow":"One or two scan types in CI (e.g., secrets + deps), SAST missing or comment-only, DAST quarterly at best.","red":"No security tooling in CI at all, or scans exist but can't fail the build (always green), or findings have no owner/tracking.","yellow_rationale":"warning — you catch the cheap stuff, not everything.","red_rationale":"every security defect ships to the field and is discovered by the next user or attacker.","criteria":{"0":"zero security tooling in CI.","1":"minimal coverage, no tracking","2":"partial toolchain, no block","3":"full toolchain gating"},"scope":"Security-job inventory/blocking in CI; the gates' quality-gate siblings are TEST-08; actual findings come from SEC-01/02.","applicability":"never N/A. Zero CI configs → measured score-0 (clause-b evidence).","statusing":"measured_when:  tree enumerated                  # job inventory decidable statically\nestimated_when: configs unparseable              # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: SAST ∧ secret-scan(history) ∧ deps ∧ image classes present ∧ blocking on push/PR\n- `2`: core classes present, partial blocking or partial triggers\n- `1`: single advisory-only class\n- `0`: no security jobs at all","fact_schema":"{\"sec10\": {\n  \"security_jobs\": [{\"name\": \"semgrep\", \"class\": \"sast\", \"trigger\": \"push\", \"blocking\": true}],\n  \"classes_present\": [\"sast\", \"deps\"],\n  \"secret_scan_covers_history\": false,\n  \"image_scan_on_build\": false,\n  \"workflow_permissions_hardened\": true}}","budget_class":"fast","evidence":"evidence: \"ci-security: classes={list}; blocking={k}/{n}; history-secret-scan={bool}; perms-hardened={bool}\"","remediation":{"quick_win":"add Semgrep/CodeQL failing gates, secret scan on history + CI, TRIVY on images — this week.","structural":"a security-as-quality pipeline (SAST, deps, secrets, container, DAST on staging, threat modelling for new features), a findings tracking loop (owner, SLA, retest), and a hard \"no gate-less merge\" rule.","gold_standard":"Five scan categories failing in CI, findings tracked to closure within SLA, DAST regularly scheduled, threat modelling on all new boundaries.","effort":"🔷 ~1–2 days"}},
  "DATA-01": {"id":"DATA-01","category":"DATA","name":"Schema Migration Backlog / \"Migration Hell\"","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Database schema changes have accumulated into an unmanageable backlog — dozens of unapplied migrations, long-running one-off migration jobs, destructive or manual schema changes, or a schema that's been mutated directly with no migration history at all.","why":"Migration discipline is the data layer's version control. When migrations are lost, batched, or manual, the schema drifts from the code's expectations, every deployment becomes a coin-flip, and the team's fear of touching the schema freezes all feature work. It's the single most common reason legacy systems *can't* be modernized in place.","manifests":"Migration folder with 400+ files, `db:schema:load` instead of migrations, manual `ALTER TABLE` statements in runbooks, \"schema drift\" warnings in CI, a migration that \"takes 6 hours to run,\" migrations modifying prod directly from a laptop, no migration from empty schema for a new environment.","detection":"Migration inventory — count migration files vs. applied versions in each env (`prisma migrate status`, `alembic heads`, Rails version table, Flyway report); check for drift between environments (compare `schema.rb`/`schema.sql` vs. actual DB); look for destructive operations in migration history (`DROP`, `RENAME` without backfill); measure time and safety of latest migrations (are they reversible?).","yellow":"10+ pending migrations or one long-running (> 30 min) migration pending; a little env drift.","red":"Schema changed ad hoc/manually in prod, or migrations are destructive/lossy as normal practice, or a fresh environment cannot be built from migrations.","yellow_rationale":"warning — friction is rising, deployments start to be scary.","red_rationale":"the schema is no longer reproducible — the data layer is beyond migration discipline and needs reconstitution.","criteria":{"0":"manual/destructive schema mutation, irreproducible.","1":"long-running or partially manual migrations","2":"backlog/tolerable drift","3":"migrations only, clean builds"},"scope":"Migration mechanics/backlog; schema shape debt is DATA-08, cross-env drift is DATA-10.","applicability":"`na_when: exhaustive enumeration shows no persistence layer at all` — zero migration dirs ∧ zero DB drivers in parsed manifests ∧ zero schema files (clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  framework detected and >=1 migration parsed     # inventory facts only\nestimated_when: raw-SQL-heavy chains where op semantics unparseable   # clamp [1,2], confidence low\nunknown_when:   persistence suspected (DB driver present) but zero migration artifacts -> cannot distinguish \"schemaless\" from \"invisible\"\nna_when:        clause-b fired (no persistence layer)\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  multi-framework monorepo -> per-root aggregation + scope-limited if truncated","score_mapping":"Y/R values: see §3.\n\n- `3`: linear replayable chain ∧ no destructive ops ∧ low raw-SQL share\n- `2`: backlog pressure signals (recent pile-up), chain still clean\n- `1`: destructive/manual ops present outside core tables ∨ partial graph gaps\n- `0`: unreplayable chain (missing parents/cycles) ∧ destructive ops on core tables","fact_schema":"{\"data01\": {\n  \"framework\": \"alembic\", \"migration_count\": 214,\n  \"chain_replayable\": true,\n  \"destructive_ops\": [{\"file\": \"0203_drop_legacy.py\", \"ops\": [\"DROP TABLE\"]}],\n  \"raw_sql_share\": 0.31,\n  \"graph_cycles\": 0}}","budget_class":"fast","evidence":"evidence: \"migrations({fw}): {n} files; replayable={bool}; destructive={k} ({files}); raw-sql {p}%\"","remediation":{"quick_win":"bring migrations under tooling (alembic/flyway/prisma), reconcile the drift between envs with a verified baseline, add a CI \"fresh build from migrations\" check.","structural":"adopt expand-contract migration practice (expanding then contracting changes, reversible when possible), split long migrations into batched incremental jobs, freeze manual-DDL policy, build from migrations as the only path to a new env.","gold_standard":"Migrations are the only way the schema changes; environments provably identical from clean builds; migrations are reversible and fast; zero manual DDL.","effort":"🔶 ~2–4 h"}},
  "DATA-02": {"id":"DATA-02","category":"DATA","name":"Database Coupling & Hidden Dependencies","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"The \"system\" is really one shared database — services write to the same tables, stored procedures contain business logic, foreign keys and joins reach across bounded contexts, and schema changes to one domain break another.","why":"DB coupling is how microservice-shaped codebases secretly remain monoliths. It defeats independent deployment (one team migrates, everyone breaks), ties all teams to one bottleneck, and makes any modernization a single point. It's the data-layer echo of ARCH-02/ARCH-03.","manifests":"Multiple services connecting to one DB, cross-service `SELECT` and `JOIN`s, stored procedures with business rules, shared tables across contexts, no enforced ownership boundaries, migrations affecting other teams' services.","detection":"Query/connection analysis — enumerate DB connections per service from configs; inspect schemas for cross-context tables; grep for `JOIN` across table families; check stored-procedure counts and whether logic lives in them; look at who owns the schema (single DBA? a team?). Tools: DB schema diagrams, `pg_stat_activity` connection mapping, code search for cross-service table names.","yellow":"Several services share a DB but write mostly to separate tables; some cross-context reads.","red":"Services share tables write-path, business logic lives in stored procedures, or any service queries another's tables directly as normal practice.","yellow_rationale":"warning — coupling exists, still manageable with discipline.","red_rationale":"the seas are one body — no independent change is possible.","criteria":{"0":"shared write-path or proc-based logic.","1":"cross-context reads/joins","2":"shared DB, separate tables","3":"owned schemas, API/event boundaries"},"scope":"DB-level coupling between services; intra-repo module import coupling is ARCH-02, integration-point count is API-03.","applicability":"`na_when: DATA-01 clause-b fired` (no persistence layer). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # coupling judgment over partial topology is inferential\nestimated_when: >=1 service root with DB configs enumerated   # clamp [1,2]; confidence medium in monorepo\nunknown_when:   DB configs live outside repo (env-injected only, no templates)\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium monorepo / low single-root\nscope_limited:  multi-repo system -> estimated + scope-limited (\"system topology beyond repo\")","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: shared DBs or occasional cross-joins detected, no proc logic\n- `1`: shared DB ∧ logic-heavy procs ∨ pervasive cross-context joins\n- `3`/`0` unreachable by construction","fact_schema":"{\"data02\": {\n  \"logical_dbs\": [\"orders\", \"billing\"],\n  \"shared_db_services\": [{\"db\": \"orders\", \"roots\": [\"api\", \"worker\", \"reports\"]}],\n  \"cross_context_joins\": 3,\n  \"stored_procs\": {\"count\": 12, \"logic_heavy\": 5}}}","budget_class":"fast","evidence":"basis: \"db-coupling: {d} logical DBs; shared by {s} roots ({worst}); procs {p} (logic-heavy {h})\"","remediation":{"quick_win":"document all cross-service DB reads/writes (the hidden map), move the worst cross-read behind an API or event.","structural":"bounded-context data ownership with a public API/event boundary per service, migrate stored-proc logic into application code, run schema ownership checks in CI.","gold_standard":"Each service owns its tables; cross-context access is via API/events only; zero business logic in stored procedures; a change to one context can't break another.","effort":"🔶 ~2–4 h"}},
  "DATA-03": {"id":"DATA-03","category":"DATA","name":"Data Integrity & Constraint Degradation","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"The schema lacks integrity guards — missing foreign keys, no `NOT NULL`/`CHECK` constraints, no uniqueness, untyped or loose-typed columns — so the database silently accepts invalid, duplicate, and orphaned data.","why":"Constraints are the DB's own test suite. Their absence means the data degrades silently, every query becomes an \"is the data even valid?\" compromise, and application code must re-defend against garbage that should've been impossible. Integrity debt is a leading driver of \"we can't trust the numbers.\"","manifests":"Tables without FKs (often from the era before InnoDB FKs), columns storing `\"true\"`/`\"false\"` strings, nullable columns that every code path treats as required, duplicate identity rows, orphaned children, no unique index on natural keys, `\"0.00\"` price strings.","detection":"Schema audit — query the SQL catalog for FK/constraint coverage (`information_schema`), run integrity probes (find orphaned rows: `SELECT * FROM child LEFT JOIN parent ... WHERE parent IS NULL`), check for duplicate natural keys, check column types vs. code expectations; DB lint tools (e.g., `sqllint`, custom SQL); compare the schema's promises to the ORM's assumptions.","yellow":"Missing constraints in non-core tables; occasional orphaned rows; some loose-typed columns.","red":"No FKs/constraints in core tables, silent data corruption patterns (duplicate identities, orphaned money rows), or app code compensating with cleanup jobs as a permanent state.","yellow_rationale":"warning — data is 95% fine, the guard is just patchy.","red_rationale":"the database has no integrity guarantee at all — \"cleanup scripts\" are the sound of it failing.","criteria":{"0":"no integrity guarantee, silent corruption.","1":"core gaps with cleanup-job compensation","2":"gaps in non-core tables","3":"constraints high, probes green"},"scope":"Integrity constraint posture; the coupling those schemas create is DATA-02; shape rigidity is DATA-08.","applicability":"DATA-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # declared ≠ enforced; drift possible\nestimated_when: >=80% of tables reconstructed # clamp [1,2]; confidence medium iff full chain replayable\nunknown_when:   schema state unreconstructable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium with complete replay; low from partial snapshots\nscope_limited:  sampled table set -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: constraints mostly present (`fk_coverage >= Y_FK`), gaps in non-core tables\n- `1`: `fk_coverage < Y_FK` ∨ core-table ref-columns without FK\n- `3`/`0` unreachable by construction","fact_schema":"{\"data03\": {\n  \"tables\": 48,\n  \"fk_coverage_pct\": 62.0,\n  \"ref_cols_without_fk\": [{\"table\": \"orders\", \"cols\": [\"customer_id\"]}],\n  \"check_constraints_total\": 9,\n  \"not_null_share\": 0.71}}","budget_class":"fast","evidence":"basis: \"declared-schema {n} tables: FK {p}%; missing FK e.g. {examples}; checks {c} [declared≠enforced]\"","remediation":{"quick_win":"add the missing FKs/unique indexes (backfill orphans first, then constraint), fix the top data-quality violations.","structural":"constraints-when-shipping policy, data-quality probes as recurring CI/data checks, typed columns everywhere, a data steward owns integrity.","gold_standard":"FKs + constraints close to 100%, integrity probes green, zero known duplicate/orphan patterns, cleanup jobs retired.","effort":"🔶 ~2–4 h"}},
  "DATA-04": {"id":"DATA-04","category":"DATA","name":"Legacy Storage Technology","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"PART","rollup":"standard","gates":[],"definition":"Core data lives in storage technologies that are unmaintained, hard to query, or impossible to evolve — flat files, XML blobs, legacy NoSQL with no maintenance, file-based state, mainframe-adjacent stores, object graphs hand-rolled on top of file systems, or databases long off the vendor's support matrix.","why":"Storage is the deepest lock-in a codebase has. When the *format/technology* is EOL, the code's options collapse: every feature is a fight with a dead file layout, and migrations out are expensive and risky. This is the data-layer version of ECOS-01.","manifests":"XML/flat-file/CSV stores for core records, proprietary binary formats, a database version supported no longer (e.g., ancient MySQL), file-system blobs with indexes in code, abandoned document stores, \"the data is in the files on `//oldfs`\", archived formats no tool reads.","detection":"Storage inventory — enumerate the systems of record (DBs, file stores, queues, archives), check vendor support/lifecycle for each (endoflife for DB versions), inspect the formats of the files (headers, extensions, queryability), measure share of critical data in unqueryable/unmaintained stores.","yellow":"Some non-core data in legacy formats/stores; a supported-but-old DB version; filesystem blobs with an index layer.","red":"Core data (money, identity, compliance) in an unsupported/unmaintainable store, or a proprietary format whose tooling has vanished.","yellow_rationale":"warning — friction but not crisis.","red_rationale":"the data can't be queried, migrated, or secured — a locked vault with no key.","criteria":{"0":"core of record unmaintainable.","1":"legacy reads in core","2":"legacy in non-core","3":"all stores supported"},"scope":"Storage technology choices/lifecycle; runtime contention is DATA-05, backup posture DATA-06.","applicability":"DATA-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # inventory completeness beyond repo unknowable\nestimated_when: >=1 storage reference enumerated   # clamp [1,2]; confidence medium if versioned+lifecycle-resolved\nunknown_when:   zero storage references in a tree that otherwise has persistence signals\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when all systems version-pinned; low otherwise\nscope_limited:  managed-cloud-only shops (no infra in repo) -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: modern systems present ∨ legacy only for niche/archival data\n- `1`: EOL-or-legacy system carrying non-core data ∨ unversioned legacy present\n- `3`/`0` unreachable by construction","fact_schema":"{\"data04\": {\n  \"systems\": [{\"kind\": \"rdbms\", \"name\": \"postgresql\", \"version\": \"9.6\", \"eol_past\": true, \"source\": \"docker-compose:14\"},\n               {\"kind\": \"flat-file\", \"name\": \"access-mdb\", \"evidence\": \"data/registry.mdb\"}],\n  \"unversioned\": 2}}","budget_class":"api-budgeted","evidence":"basis: \"storage-inventory {n} systems: {list}; eol-past={bool} ({source}) [repo-visible set only]\"","remediation":{"quick_win":"stand up a read side (index the files into a modern store, keep legacy as archive), build the extraction utilities.","structural":"a data-migration program — move systems of record to maintained technology one store at a time (strangler pattern for data), keep legacy read-only during migration, archive what's truly dead.","gold_standard":"All systems-of-record on maintained technology; legacy formats readable/exportable or archived with access paths; critical data queryable with modern tooling.","effort":"🔷 ~1–2 days"}},
  "DATA-05": {"id":"DATA-05","category":"DATA","name":"Lock Contention & Scaling Bottleneck","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"standard","gates":[],"definition":"The database cannot scale with load because of lock contention — hot rows, table-level locks, un-indexed joins, full-table scans under traffic, or a single-instance design that caps throughput. \"Vertical scaling required for traffic spikes.\"","why":"Scalability is where the data layer reveals its design era. Tables designed before concurrency, engines with table locks (MyISAM), innefficient indexes, and single-writer assumptions all cap the system at current traffic — and die on spikes. It's also the hidden cost: you buy vertical upgrades instead of fixing the schema.","manifests":"`LOCK WAIT` entries in DB logs, slow-query logs with full-table scans at p95, hot-row contention (a single row updated by every request, e.g., a global counter), table-level locks from old engines, index-less foreign keys, \"we upgraded the instance twice this year.\"","detection":"Profiling/data — `SHOW PROCESSLIST`/`pg_stat_activity` histogram during peak, slow-query log analysis (`pt-digest`), `EXPLAIN` on p95 queries (seq scans, missing index scans), lock-wait graphs (Percona, Datadog DB), load testing with concurrency ramp (k6/pgbench) to find the throughput ceiling.","yellow":"Occasional lock waits and a few full-table scans; vertical scaling used for the last spike.","red":"Hot-row or table-level lock contention under *standard* load, or the only scaling lever is a bigger instance, or lock waits cause user-visible stalls.","yellow_rationale":"warning — the ceiling exists and was brushed up against.","red_rationale":"the design caps throughput — the next spike is a downtime.","criteria":{"0":"blocked from scaling, vertical-only.","1":"contention under spikes","2":"occasional waits, mitigated","3":"no contention at 3× peak"},"scope":"Runtime DB contention; ORM patterns that *invite* it are DATA-07's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # plan/lock behavior cannot be inferred from text reliably either way\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"data05\": {\"status\": \"unknown\",\n             \"reason\": \"contention provable only under live load\",\n             \"static_hints\": {\"for_update_sites\": 7}}}","budget_class":null,"evidence":"emission: \"unknown — needs peak-window profiling + EXPLAIN on p95 queries (deep scan)\"","remediation":{"quick_win":"index the exploitable gaps that full-table scans reveal, split the hot row (counter → per-shard), add read replicas for read-heavy load.","structural":"bounded-context data design (DATA-02), remove the contention points (sequence/counter patterns rewritten), tuned isolation levels where safe, load tests with concurrency in CI, capacity per feature, not per \"make it bigger.\"","gold_standard":"Lock waits near zero at peak, index strategy documented and maintained, scaling via standard horizontal levers, load tests show headroom > 3×.","effort":"🔷 ~1–2 days"}},
  "DATA-06": {"id":"DATA-06","category":"DATA","name":"Data Lifecycle Management Deficits","tier":"B","default_status":"unknown","effort":"⚡ ≤30 min","v1":"PART","rollup":"standard","gates":["G7"],"definition":"No coherent data lifecycle — retention is unmanaged (\"keep everything forever\" or \"deleting is terrifying\"), archival doesn't exist, backups are untested, PII has no expiry, and restore is a rumor.","why":"Lifecycle management is a modern compliance/ops baseline. Its absence means: storage costs grow unbounded, GDPR/CIPA/retention obligations are unmet, and — the worst failure mode — the system has no *verified* recovery path. A database you've never restored doesn't actually protect anything. This is also a legal/liability liability that compounds with every passing year.","manifests":"No retention policy documentation, prod data copied everywhere (dev DBs full of PII), backups run but never restore-tested, no archival tier, GDPR deletion requests \"manually handled,\" data shuffling \"just in case.\"","detection":"Audit — retention policy docs vs. actual jobs; backup logs and *restore test evidence* (last successful restore drill); PII copy map (which envs/dumps hold production PII); storage growth vs. retention trend; erasure feature exists and is exercised in tests.","yellow":"Backups run but restore untested (> 90 days), no retention policy, some prod-data sprawl to dev.","red":"No backups at all, or restore never successfully performed/untestable, or retention/erasure legally required and absent.","yellow_rationale":"warning — the pounce path is unverified.","red_rationale":"you cannot recover the data you legally must manage — operational and compliance failure.","criteria":{"0":"no backups or no legal capability.","1":"no restore evidence, retention absent","2":"backups untested/retention partial","3":"restore-verified, retention automated"},"scope":"Lifecycle/backup/restore posture; storage technology age is DATA-04, compliance retention controls SEC-08.","applicability":"DATA-01 clause-b (holds critical data? if no persistence layer at all → N/A). Else applicable.","statusing":"measured_when:  never auto-measured            # drill evidence lives outside repo mostly\nestimated_when: >=1 lifecycle artifact enumerated  # clamp [1,2]; confidence medium iff backup+retention both seen\nunknown_when:   no infra/config in repo (managed elsewhere)\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     low when evidence is absence-shaped (\"no backups visible\" ≠ \"no backups\")\nscope_limited:  managed-cloud posture -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: automated backups ∧ some retention config; drills unevidenced\n- `1`: ad-hoc scripts only ∨ retention absent ∨ nothing visible for a critical-data system\n- `3`/`0` unreachable by construction","fact_schema":"{\"data06\": {\n  \"backup_jobs\": [{\"kind\": \"ci-cron\", \"evidence\": \".github/workflows/backup.yml\", \"retention_configured\": false}],\n  \"iac_pitr_or_versioning\": true,\n  \"restore_drill_evidence\": false,\n  \"lifecycle_rules_present\": false}}","budget_class":"fast","evidence":"basis: \"lifecycle-sweep: backup={kind@path}; retention={bool}; drill-evidence={bool} [repo-visible set]\"","remediation":{"quick_win":"prove restore works this week (schedule a drill), set retention tiers, stop seeding dev with PII.","structural":"automated backup verification, retention/archival jobs, PII minimization (anonymization in non-prod), erasure workflow as software, RTO/RPO SLOs with drills scheduled.","gold_standard":"Restore drills quarterly and green, retention automated, zero PII sprawl in dev, erasure request fully exercisable, RTO/RPO met.","effort":"⚡ ≤30 min"}},
  "DATA-07": {"id":"DATA-07","category":"DATA","name":"ORM / Query Performance Smells","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The ORM layer generates bad queries — N+1 races, lazy-loading storms, implicit projection of entire rows, missing eager loading, cartesian products from bad fetches — and there's no index/query strategy to compensate. Application code triggers data-layer crashes under real use.","why":"ORM abuse is the classic \"the code works on the test fixtures\" trap: SQL looks fine, then dies at 10× data. It's a sign the data layer was written without a performance understanding, then never revisited — two generations of schema and data growth later, it's a query minefield.","manifests":"N+1 in list endpoints (1 query + N queries per row), lazy loads in loops, giant `SELECT *`, fetch bypassing indexes, unused indexes, missing indexes on query-adjacent columns, \"works in dev, dies in prod,\" SQL in logs showing 4,000 queries per request.","detection":"ORM query analysis — enable query logging (Django debug toolbar, Rails logger SQL, Hibernate stats, Entity Framework SQL log), count queries per endpoint, look for N+1 patterns (same query × N), use perf tooling (Bullet gem, django-silk, SQLAlchemy `echo`), `EXPLAIN` on generated SQL, index-usage stats (`pg_stat_user_indexes`, Percona).","yellow":"N+1 and wide fetches in non-critical endpoints; query counts 2–5× reasonable.","red":"N+1/implicit queries in core flows causing timeouts under moderate data, or no index strategy at all while slow-query logs show the same misses daily.","yellow_rationale":"warning — slow but not on fire.","red_rationale":"the data layer degrades linearly with growth — a time bomb.","criteria":{"0":"core N+1 storms / no index strategy.","1":"core smells, timeouts occasionally","2":"smells in non-core","3":"query budgets + clean"},"scope":"Query-shape smells in code; live contention is DATA-05, coupling via shared schemas DATA-02.","applicability":"`na_when: no ORM or query-building code detected` (clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # N+1 confirmation needs execution\nestimated_when: >=1 ORM pack ran               # clamp [1,2]; confidence medium when schema cross-check joined\nunknown_when:   no supported ORM parsed\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium with index cross-check; low without\nscope_limited:  sampled modules -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: smell sites exist outside core paths only\n- `1`: N+1-able patterns in core request paths ∨ unindexed hot filters on core tables\n- `3`/`0` unreachable by construction","fact_schema":"{\"data07\": {\n  \"orm\": \"django\", \"n1_suspects\": [{\"file\": \"api/views.py\", \"shape\": \"loop .filter\"}],\n  \"n1_in_core\": 6,\n  \"unindexed_hot_filters\": [{\"model\": \"Order\", \"col\": \"status\"}],\n  \"raw_sql_interpolation_sites\": 3}}","budget_class":"fast","evidence":"basis: \"orm-scan({orm}): {k} N+1 suspects ({c} core); {u} unindexed hot filters [static shapes]\"","remediation":{"quick_win":"fix the top 10 N+1s with eager loading/joins, add the missing indexes on the hot path, reduce column projection.","structural":"query budget per endpoint (assert queries-per-request in tests), index strategy documented and reviewed, offload heavy reads (search, aggregates) to appropriate engines, performance tests with realistic data volume in CI.","gold_standard":"Query counts per endpoint budgeted and tested, N+1 class eliminated, index strategy current, p95 latency flat as data grows 10×.","effort":"🔶 ~2–4 h"}},
  "DATA-08": {"id":"DATA-08","category":"DATA","name":"Schema Overfitting & Model Rigidity","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The schema bakes in business decisions rather than business facts — columns named after UI features, one-off statuses, booleans like `use_new_pricing_v2`, meanings encoded in column values, and no room for the domain to evolve — making every product change a migration.","why":"Data should model the *domain* (durable facts), not the *implementation* (transient decisions). Overfit schemas freeze the product: each rule change needs a schema change, and after years the schema is a fossil of every abandoned experiment. It's the data-layer version of ARCH-01's god-object thinking.","manifests":"Columns like `migration_batch_84`, `is_v2_enabled`, `old_tax_rounding_v1`, status values that spool dozens of variants, data copied into new columns rather than normalized, events never recorded (only current state), business rules hidden in trigger/constraint names.","detection":"Schema archaeology — review table/column names (grep for version words, `old_`, boolean flags, feature names); count of \"append-only garbage columns\"; check whether the schema would support an unanticipated product change (a \"ergonomic test\": add a new price type — how many tables/columns move?); look for a noconcepts-of-the-domain (customers stored as `users.type`), no event/audit structures.","yellow":"Some versioned/flag columns and historical cruft, mostly non-core.","red":"Core domain is modeled around implementation history, or every product change requires a schema migration, or the schema has no way to represent domain evolution (no events/effective-dating).","yellow_rationale":"warning — the museum is forming but isn't load-bearing.","red_rationale":"the model is an anchor — product velocity is now a schema project.","criteria":{"0":"implementation-fossil schema, every feature is a migration.","1":"core partially overfit","2":"cruft in non-core columns","3":"domain-fact schema"},"scope":"Shape rigidity of the model; migration mechanics are DATA-01, audit-readiness structure DATA-09.","applicability":"DATA-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # rigidity judgment is inferential\nestimated_when: schema state available         # clamp [1,2]; confidence medium iff full replay\nunknown_when:   no schema reconstructable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium full-replay; low snapshot-only\nscope_limited:  sampled tables -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: scattered marker/flag columns in non-core tables\n- `1`: core tables carrying legacy markers ∨ EAV-in-core ∨ heavy flag-column density\n- `3`/`0` unreachable by construction","fact_schema":"{\"data08\": {\n  \"legacy_marker_cols\": [{\"table\": \"users\", \"cols\": [\"email_old\", \"plan_v2\"]}],\n  \"flag_columns_total\": 23,\n  \"eav_tables_in_core\": true,\n  \"churn_hotspot_table\": \"orders\"}}","budget_class":"fast","evidence":"basis: \"schema-archaeology: {m} marker cols ({examples}); {f} flag columns; eav-core={bool}\"","remediation":{"quick_win":"kill the obvious versioned/flags columns behind an additive migration, document the domain model properly.","structural":"remodel around domain facts — normalize flags into real entities, adopt effective-dating/event structures for changeable rules (see DATA-09), a domain model owned by the team, schema reviewed as domain design not storage plumbing.","gold_standard":"Schema expresses domain facts; product rule changes land without schema surgery; events/snapshots support evolution; archaeology columns gone.","effort":"🔶 ~2–4 h"}},
  "DATA-09": {"id":"DATA-09","category":"DATA","name":"Event Sourcing / Audit Readiness","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"The system records only current state, has no event/audit trail of changes, and cannot answer \"what happened and why\" — no append-only log, no effective dating, no immutable history. Business rules are re-run to reconstruct states rather than queried from records.","why":"Immutable, append-only history is how modern systems handle audit, time-travel debugging, replay, and compliance. Its absence makes \"what did the customer see on X date\" a reverse-engineering project, makes reconciliation impossible, and blocks compliance and analytics (this connects to SEC-05's audit logging at the domain level).","manifests":"No history tables, no event store, state mutated in place (`UPDATE` overwrites), \"we can't tell you what changed,\" reconciliation by re-running old code, audit requests answered with spreadsheets, effective-dating absent for changeable data.","detection":"Model audit — check for history/version tables, event/audit columns (`updated_by`, versions), an event log or outbox; test an \"as-of\" query (what was the state on date X? — if impossible without backups/time-travel, it's absent); review whether domain changes create durable records or just update a row; look for immutable/mutable split.","yellow":"Some history/audit exists for core aggregates; as-of queries possible for some domains; events for a few flows.","red":"No history or events at all for core business facts, as-of reconstruction impossible, and compliance/analytics depend on it.","yellow_rationale":"warning — partial readiness, gap is known.","red_rationale":"the past is provably unrecoverable — a systemic blind spot.","criteria":{"0":"no history, reconstruction impossible.","1":"history ad hoc/backup-based","2":"partial (some aggregates)","3":"full eventing"},"scope":"History/event structure presence; shape rigidity is DATA-08.","applicability":"DATA-01 clause-b. Else applicable.","statusing":"measured_when:  schema/model parse completed    # structure inventory is fact (presence-only)\nestimated_when: partial parse coverage          # clamp [1,2], confidence low\nunknown_when:   no persistence artifacts\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  sampled models -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: event/outbox structures ∧ audit columns pervasive ∧ history tables\n- `2`: timestamp-audit columns pervasive, no event structures\n- `1`: audit columns partial on core tables only\n- `0`: no history/audit/event evidence anywhere on core tables","fact_schema":"{\"data09\": {\n  \"history_tables\": [\"orders_versions\"],\n  \"event_structures\": {\"outbox\": true, \"event_store\": false},\n  \"audit_columns_share\": 0.82,\n  \"posture\": \"outbox\"}}","budget_class":"fast","evidence":"evidence: \"model-audit: posture={posture}; history={list}; outbox={bool}; audit-cols {p}%\"","remediation":{"quick_win":"add an append-only event/audit log for the top 3 core aggregates going forward (capture authoritative mutation events, not screenshots).","structural":"eventing strategy for core facts (outbox, event store, or time-boxed history), as-of query support, replay/drills, compliance-backed retention of the history.","gold_standard":"Core aggregates are fully evented with versioned state; as-of queries are routine and tested; history feeds audit and analytics directly.","effort":"🔷 ~1–2 days"}},
  "DATA-10": {"id":"DATA-10","category":"DATA","name":"Environment Schema Drift","tier":"A","default_status":"measured","effort":"🔷 ~1–2 days","v1":"NO","rollup":"standard","gates":[],"definition":"Dev/test/staging/prod schemas have drifted from each other and from the migration baseline — fixtures that no longer match, environments built by hand, migrations applied differently per environment, and \"works in test, breaks in prod\" as a normal condition.","why":"Drift means the environments are not the same product — every deployment is a gamble on the gap between what was tested and what exists. It invalidates the entire QA pipeline and is usually the companion of DATA-01's migration disorder at the environment level.","manifests":"Staging misses 12 tables that prod has; dev DBs differ per engineer; test fixtures fail after migrations; \"the bug only reproduces on prod,\" schema comparison tools run manually; env-specific migrations; rotation/persist scripts per env.","detection":"Schema diff — run a schema-diff tool (mysqldiff, pg-diff, `schema-diff`, Liquibase `diff`) between dev→staging→prod and the migration baseline; check fixture strategy (are fixtures migration-generated or hand-maintained?); compare CI's fresh-env build against prod; measure the \"time to stand up a prod-like env.\"","yellow":"Small diffs between environments, mostly non-critical columns; fresh env build mostly works.","red":"Meaningful schema drift between all environments, or fresh envs can't be built from migrations, or \"prod-only bug\" is a standing category.","yellow_rationale":"warning — the crack exists, prod-only bugs are appearing.","red_rationale":"test results don't transfer to prod — the QA function is invalid.","criteria":{"0":"environments are not the same product.","1":"meaningful drift, prod-only bugs","2":"minor drift, quick to reconcile","3":"zero drift, reproducible"},"scope":"Cross-env drift; the migration chain that should prevent it is DATA-01.","applicability":null,"statusing":"measured_when:  never from URL\nestimated_when: never                            # fixture hints prove nothing about prod drift\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"data10\": {\"status\": \"unknown\",\n             \"reason\": \"requires schema diffs across live environments\",\n             \"fixture_hint\": {\"hand_maintained_fixtures\": true}}}","budget_class":null,"evidence":"emission: \"unknown — needs dev→staging→prod schema diffs against migration head (M&A access)\"","remediation":{"quick_win":"run diffs, reconcile to the migration baseline, rebuild staging from migrations.","structural":"migrations-as-only-path for every env, fresh-env CI per PR, schema-diff check in CI (fail on env drift), fixture strategy generated from migrations.","gold_standard":"Zero diffs between baseline and any env; fresh environments reproducible; \"prod-only bug\" eliminated as a category.","effort":"🔷 ~1–2 days"}},
  "API-01": {"id":"API-01","category":"API","name":"API Contract Drift","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Interfaces are not governed by a formal contract — no OpenAPI/Swagger/GraphQL schema/Protobuf for many/all endpoints, response shapes drift between deploys, fields appear/disappear silently, and consumers cope by sniffing.","why":"A contract is the API's type system — it lets consumers, tests, generators, and mock servers depend on something stable. Its absence returns the world to \"read the code, guess the shape,\" which is the definition of a pre-standard-era integration practice. Contract drift is also a direct cause of \"it worked yesterday\" integration bugs.","manifests":"Endpoints with no schema/spec, response shapes assembled by hand (`res.json({...})` ad hoc), breaking field renames shipped in minor versions, no contract test, consumers parsing `docs/README_old.txt`, Swagger file that predates half the endpoints.","detection":"Contract inventory — list all endpoints and check each against a spec (OpenAPI file exists? up to date? enforced?); diff spec vs. actual responses (OpenAPI validator middleware, `swagger-validator`, API lint `redocly lint`, spec-probe scripts); check generator usage (clients/tests generated from spec or hand-written); look for `\"type\":\"any\"`/untyped responses.","yellow":"Spec exists but stale/partial; some endpoints undocumented; clients hand-written.","red":"No contracts at all (or contracts so stale they're misleading), and/or breaking response changes ship freely.","yellow_rationale":"warning — the contract exists in name, drift is accumulating.","red_rationale":"consumers have no stable target — integration is archaeology.","criteria":{"0":"no contracts, free drift.","1":"mostly undocumented","2":"partial/stale coverage","3":"contracts current + enforced"},"scope":"Spec-vs-route currency; versioning discipline is API-02, evolution process is API-10.","applicability":"`na_when: no HTTP server surface detected` (clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # live responses never observed\nestimated_when: routes enumerable              # clamp [1,2]; confidence medium when both sets parsed cleanly\nunknown_when:   routes unparseable and no spec found\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium; low if <70% fuzzy-match confidence\nscope_limited:  multi-service monorepo -> aggregate + scope-limited if truncated","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: spec present, drift below Yellow share, enforcement optional\n- `1`: no spec ∧ routes exist ∨ drift above Yellow ∨ spec stale (>R_DAYS older than last route commit)\n- `3`/`0` unreachable by construction","fact_schema":"{\"api01\": {\n  \"spec_present\": true, \"spec_endpoints\": 41, \"route_total\": 58,\n  \"undocumented\": 19, \"ghost\": 2,\n  \"validator_middleware\": false,\n  \"match_confidence\": \"medium\"}}","budget_class":"fast","evidence":"basis: \"contract-inventory: {u}/{n} undocumented, {g} ghost; validator wired={bool}\"","remediation":{"quick_win":"generate accurate specs from code (OpenAPI annotations/`apischema`, `drf-spectacular`, NestJS Swagger), validate specs vs. responses in CI.","structural":"contract-first or contract-enforced development (spec is source of truth, generators produce clients/mocks/tests), a lint gate on spec changes.","gold_standard":"Every endpoint covered by a current, accurate contract; clients and tests generated from it; spec drift impossible (CI enforces).","effort":"🔶 ~2–4 h"}},
  "API-02": {"id":"API-02","category":"API","name":"Versioning & Breaking-Change Discipline","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"API changes are not versioned or announced — breaking changes ship in patch/minor releases, old versions die without notice, and consumers discover changes at runtime.","why":"Versioning is the social contract of an API: it says \"we will not break you silently.\" Its absence is a trust failure that forces every consumer to freeze-and-fear updates, blocks external integrations, and argues against ever exposing the API publicly. Modern practice is explicit versioning (path/header/negotiated) + deprecation policy + release cycle.","manifests":"No `v1`/`v2` in paths or media types, breaking field removals in minor releases, no deprecation headers/announcements, old versions deleted immediately, consumers pinned to ancient versions with no migration path.","detection":"Version audit — URL/media-type versioning presence; semantic-release discipline (do breaking changes bump major? inspect release history + CHANGELOG); deprecation mechanism (headers, docs, schedule); consumer migration practice (existence of a version retirement policy).","yellow":"Versioned, but breaking changes slip into minors occasionally; deprecation communicated informally.","red":"No versioning at all, breaking changes ship without announcement, or consumers broke in the last 12 months as a result.","yellow_rationale":"warning — the gate exists but is leaky.","red_rationale":"the platform cannot have external consumers or stable partner integrations — modernization foreclosed.","criteria":{"0":"no versioning, silent breakage.","1":"versioned partially / reactive","2":"versioned with leaks","3":"versioned + disciplined"},"scope":"Versioning/deprecation mechanics; contract currency is API-01, consumer awareness is API-08.","applicability":"`na_when: no HTTP server surface` (API-01 clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # discipline is a judgment over inferred breakage\nestimated_when: >=2 of {markers, deprecation, release-audit} computed   # clamp [1,2]\nunknown_when:   no API surface parseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when release history rich (>20 tags)\nscope_limited:  few releases -> estimated low (\"history too thin\")","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: versioning present ∧ minor lapses only\n- `1`: no versioning scheme ∨ repeated breaking-without-major pattern ∨ no deprecation path\n- `3`/`0` unreachable by construction","fact_schema":"{\"api02\": {\n  \"url_versioning\": true, \"media_type_versioning\": false,\n  \"deprecation_headers\": false,\n  \"breaking_without_major\": [{\"tag\": \"v2.3.0\", \"signal\": \"'BREAKING' in notes\"}],\n  \"migration_guides_linked\": true}}","budget_class":"api-budgeted","evidence":"basis: \"versioning-probe: url={bool}; deprecations={bool}; {k} breaking-no-major of {n} releases\"","remediation":{"quick_win":"introduce versioning at the least cost (path `v2` for the contract-breaking surface; keep `v1` alive with a retirement date).","structural":"versioning policy (what counts as breaking), deprecation headers + documented schedule, sunset coach with migration guides, semver discipline wired into release automation.","gold_standard":"Explicit versioning everywhere; breaking changes only in majors with deprecation windows; a deprecation calendar; zero silent consumer breakage for two years.","effort":"⚡ ≤30 min"}},
  "API-03": {"id":"API-03","category":"API","name":"Integration Point Bloat","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"The system has a sprawling, unmanaged mesh of point-to-point integrations — direct service-to-service calls, services reading each other's DBs (see DATA-02), N-way connections that only the longest-serving engineers understand, no gateway/registry, and integration sprawl that grows with every feature.","why":"Each integration point is a hidden dependency: a deployment, a security surface, an outage path. When the mesh grows without governance, changes ripple invisibly and the \"system\" is unknowable — a defining property of organic, pre-platform-era architectures.","manifests":"A hand-drawn \"integration spaghetti\" diagram, services calling 5+ other services directly, shared DBs between services, no service registry/API gateway, a network diagram nobody can update, \"if X changes we have to check these 11 things.\"","detection":"Topology mapping — build the integration graph from configs (service discovery, env vars, DNS targets, HTTP client configs, DB connection strings), visualize it, count edges per node; check for a platform gateway/registry; interview \"who can name every integration?\" Compute graph density and cross-service DB reads.","yellow":"Dense point-to-point graph (5–10 edges/service), growing, but documented; a registry/gateway is absent.","red":"Every service talks to every other / shared DBs are the integration bus, the graph is undocumented, or a deployment integral to another service is routinely discovered by incident.","yellow_rationale":"warning — still navigable, governance is missing.","red_rationale":"the topology is unknowable — no change is local anymore.","criteria":{"0":"unknowable graph / DB-as-integration-bus.","1":"dense, no registry","2":"dense but documented","3":"governed mesh"},"scope":"Integration-point inventory; sync-vs-async shape is API-04, vendor risk per dependency is API-05, DB edges are DATA-02.","applicability":"`na_when: zero outbound integrations and single-service layout` (clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # bloat judgment over partial graph is inferential\nestimated_when: >=1 config surface enumerated  # clamp [1,2]; confidence medium in monorepos\nunknown_when:   no configs found in an integration-suspected tree\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when env templates + manifests both parsed\nscope_limited:  multi-repo topology -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: moderate fan-out, most clients abstracted\n- `1`: high unabstracted fan-out ∨ duplicate bindings to same target via different protocols\n- `3`/`0` unreachable by construction","fact_schema":"{\"api03\": {\n  \"outbound_edges\": [{\"target\": \"stripe-api\", \"protocol\": \"https\", \"abstracted\": true}],\n  \"queue_bindings\": [\"orders.created\"],\n  \"fan_out_total\": 17,\n  \"gateway_present\": false,\n  \"unabstracted_direct_clients\": 9}}","budget_class":"fast","evidence":"basis: \"integration-graph: {n} outbound edges ({u} direct/unabstracted); queues {list}; gateway={bool}\"","remediation":{"quick_win":"build the topology map (automated), as the source of truth, and start routing traffic through a gateway for the top 5 hubs.","structural":"platform governance — service registry, gateway/boundary routing, event-based decoupling for the densest paths, rules against direct cross-service DB access.","gold_standard":"Known topology (auto-mapped, current), integration governance (registry/gateway/events), a change to one service locally verifiable, density trending down.","effort":"🔶 ~2–4 h"}},
  "API-04": {"id":"API-04","category":"API","name":"Synchronous Coupling & Chatty Interfaces","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Core flows string many synchronous calls end-to-end — one request fans out into a chain of blocking HTTP calls where any slow/failing dependency is paid by the user, with no async boundaries, no bulkheads, no circuit breakers, no timeouts/SLOs per hop.","why":"Synchronous fan-out turns every downstream dependency into your p99 and your outage — \"the slowest link owns your product.\" Modern architecture truncates these chains with async/eventing, bulkheads, and resilience patterns. It's also why legacy systems are so hard to modernize: the failure mode is coupled to latency, not correctness.","manifests":"A checkout/onboarding flow instrumented as 8 sequential HTTP calls, no message queue anywhere, no circuit breaker/timeout config, a service that blocks on an ETL's endpoint, \"the third-party is slow today so the app is slow.\"","detection":"Trace analysis — distributed tracing (from PERF-01) to count hops and N+1-of-services per request, temporal latency waterfall; code review of core flows for `await`/blocking chains; presence of queues/event bus; resilience config audit (timeouts, retries, circuit breakers, batching).","yellow":"Long sync chains in non-core flows; a couple of hot paths with fragile timeouts.","red":"Core flows block on chains of slow/unreliable sync dependencies with no async escape, or an outage in one dependency takes down the primary flow (no bulkheads).","yellow_rationale":"warning — the pattern exists but isn't load-bearing everywhere yet.","red_rationale":"the product's latency and uptime are hostage to the weakest link.","criteria":{"0":"primary flow hostage to one dependency.","1":"fragile chains in core with no fallback","2":"sync chains outside core","3":"minimal live deps, resilient"},"scope":"Sync coupling shape in code; integration inventory is API-03, runtime latency is PERF's plane.","applicability":"API-01 clause-b (needs a request-handling surface). Else applicable.","statusing":"measured_when:  never auto-measured            # hop-count truth needs traces\nestimated_when: >=2 of {chain-depth, loop-calls, resilience} probes ran   # clamp [1,2]\nunknown_when:   handlers unparseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when all three ran on supported framework\nscope_limited:  sampled routes -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: moderate serial chains, resilience present\n- `1`: deep chains on core routes ∧ no breaker ∨ loop-outbound patterns present\n- `3`/`0` unreachable by construction","fact_schema":"{\"api04\": {\n  \"deep_serial_handlers\": [{\"route\": \"POST /checkout\", \"await_depth\": 6}],\n  \"loop_outbound_calls\": 3,\n  \"resilience\": {\"breaker\": false, \"timeouts\": true, \"retry\": true},\n  \"queue_alternatives_present\": false}}","budget_class":"fast","evidence":"basis: \"sync-shape: {d} deep-serial handlers ({worst} depth={x}); loop-calls {l}; breaker={bool}\"","remediation":{"quick_win":"add timeouts + circuit breakers on the fragile hops, cache the slow reads.","structural":"slice the sync chain with events/async (compute off-path, return fast), bulkhead partitions by dependency, SLO-per-hop, degrade gracefully.","gold_standard":"Core flows touch the minimum live dependencies; slow work is async; circuit-broken fallbacks in place; the weakest link cannot sink the product.","effort":"🔶 ~2–4 h"}},
  "API-05": {"id":"API-05","category":"API","name":"Third-Party & Vendor API Dependency Risk","tier":"B","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Core functionality depends on external APIs/SaaS/vendors that are unmanaged as risks — no fallback, no circuit breaker, no documentation, no SLA awareness, vendors on deprecated APIs, API keys held by one person, no contract/license review.","why":"External dependencies are bets: the vendor can change, deprecate, rate-limit, or vanish. Unmanaged, those bets become surprises. A modern integration surface manages external risk like insurance — fallbacks, abstraction, monitoring, license review, replacement paths. This is often where \"the system was built on a promise\" class of debt lives.","manifests":"Core flows calling a vendor endpoint directly, vendor API deprecated (per their changelog) and still used, no abstraction layer (swap = rewrite), API keys in code/one person's laptop, no vendor SLA/monitoring, single-vendor dependency with no alternative.","detection":"External-dependency inventory — grep for third-party hosts/APIs, audit each: is it abstracted (behind a port) or called directly? Is the vendor API current (their changelog/deprecation)? Is there a fallback path? Who owns the key and contract? Is usage monitored? Rate-limit margins known?","yellow":"Some external calls unabstracted/non-critical; vendor deprecations vaguely watched; no fallback for most.","red":"Core flows directly coupled to a deprecated/unmaintained vendor API with no abstraction and no fallback, or a single vendor is a silent single point of failure for revenue.","yellow_rationale":"warning — manageable until the vendor moves.","red_rationale":"the vendor's roadmap now *is* your roadmap — you ship when they do.","criteria":{"0":"revenue on a deprecated vendor API with no path.","1":"core calls unabstracted, deprecations watched informally","2":"some unabstracted non-core","3":"abstracted + monitored + fallbacked"},"scope":"Third-party API dependency posture; package-level supply-chain risk is ECOS-03/10, integration count is API-03.","applicability":"`na_when: zero third-party API dependencies` (clause-b over manifests+configs). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # vendor-risk judgment is inferential\nestimated_when: >=1 vendor enumerated          # clamp [1,2]; confidence medium when manifests+hosts agree\nunknown_when:   endpoints fully env-injected with no templates/SDK deps\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium; low if only URL-literal evidence\nscope_limited:  private/internal APIs invisible -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: vendors abstracted, minor staleness, core flows have fallbacks or low vendor count\n- `1`: unabstracted core-flow vendor ∨ stale major SDKs ∨ no fallback anywhere\n- `3`/`0` unreachable by construction","fact_schema":"{\"api05\": {\n  \"vendors\": [{\"name\": \"stripe\", \"sdk\": true, \"abstracted\": true, \"on_core_flow\": true, \"fallback\": false}],\n  \"direct_host_calls_unabstracted\": [\"api.twitter.com\"],\n  \"stale_sdks\": [{\"dep\": \"stripe-node\", \"majors_behind\": 2}]}}","budget_class":"fast","evidence":"basis: \"vendor-sweep {n}: unabstracted-core={list}; stale sdks={list}; fallbacks={k}/{n}\"","remediation":{"quick_win":"wrap the top 3 vendor calls behind ports (adapters), add fallback paths where feasible, assign a vendor-risk owner + deprecation watch.","structural":"integration abstraction for critical vendors, SLA monitoring + circuit breakers, contract/license review, documented replacement paths, vendor deprecation calendar.","gold_standard":"External dependencies abstracted, fallbacked, monitored, and reviewed; vendor deprecations tracked and migrations planned; no revenue path is call-vendor-and-pray.","effort":"🔶 ~2–4 h"}},
  "API-06": {"id":"API-06","category":"API","name":"Protocol & Data-Format Legaciness","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The system still speaks legacy/modern-hostile protocols and formats on its load-bearing interfaces — SOAP, XML-RPC, REST-less RPC, proprietary binary serialization, XML everywhere, CORBA-era patterns, or hand-rolled wire formats — where modern equivalents (REST/OpenAPI, gRPC, message queues, JSON/Protobuf, AS2/EDIFACT-era interop) are expected.","why":"Protocol choice is the era stamp of an integration layer. Legacy protocols carry high operational overhead (web services stacks, ceremony, XML pain), lock out modern tooling (typed clients, gateways, observability), and are where staffing, security, and interop friction concentrate. Pairs with ARCH-06 at the interface level.","manifests":"WSDL files, SOAP envelopes, XML namespace ceremony, custom binary formats with hand-maintained mappers, an integration layer gated on a 2005-era middleware, mainframe/interconnect stubs, no JSON/REST/typed-schema path for new integrations.","detection":"Protocol inventory — list all wire protocols across integrations (inspect clients/servers, WSDL/Proto/OpenAPI presence), check each against the ecosystem norm; measure the share of core traffic on legacy protocols; check newer-format support (JSON, Protobuf, OpenAPI, events) exists at all.","yellow":"Some legacy-protocol integrations in non-core corners (a partner still on SOAP/EDI), modern formats available for the rest.","red":"Core flows bind on SOAP/XML/binary/proprietary protocols with no modern alternate, or the middleware that speaks them is itself EOL.","yellow_rationale":"warning — a cost center, but contained.","red_rationale":"every new integration inherits the museum protocol and its staffing tax.","criteria":{"0":"core binds on EOL middleware/protocols.","1":"core on legacy protocols with a plan","2":"legacy in non-core corners","3":"modern protocols"},"scope":"Wire-protocol/format choices; the endpoints' contract currency is API-01, vendor lifecycle is API-05.","applicability":"`na_when: no integration surface at all` (API-01 clause-b). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  tree enumerated                # inventory + classification is deterministic given era table\nestimated_when: era-table gaps for exotic protocols   # clamp [1,2], confidence low\nunknown_when:   no parseable surface\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  vendored client libs excluded -> noted","score_mapping":"Y/R values: see §3.\n\n- `3`: all-modern inventory\n- `2`: legacy protocols present but zero core-touch\n- `1`: legacy in isolated core-adjacent paths\n- `0`: legacy protocol carrying core flows ∨ removed-standard protocols still active","fact_schema":"{\"api06\": {\n  \"protocols\": [{\"kind\": \"soap\", \"evidence\": [\"wsdl/partner.wsdl\", \"zeep in requirements\"], \"legacy\": true}],\n  \"modern_share\": 0.7,\n  \"core_legacy_touch\": true,\n  \"schema_registry_present\": false}}","budget_class":"fast","evidence":"evidence: \"protocol-inventory {n}: legacy={list} ({k} core-touching); modern share={p}%\"","remediation":{"quick_win":"stand up modern endpoints (REST/JSON or gRPC) alongside the legacy ones for new traffic, put a gateway in front to let consumers choose.","structural":"migrate integrations off legacy protocols where feasible (strangler at the protocol layer), retire the EOL middleware, offer modern contracts for every legacy consumer.","gold_standard":"Core traffic on modern protocols, legacy formats behind adapters/bridges and shrinking, no EOL middleware, new integrations never require the museum stack.","effort":"🔶 ~2–4 h"}},
  "API-07": {"id":"API-07","category":"API","name":"Error Handling & API Observability Semantics","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The API surface has poor error semantics — generic 500s swallowing root causes, unstructured error bodies, no standard error contract, no request IDs/correlation, clients can't distinguish retriable/permanent/validation errors, and errors are invisible in logs.","why":"Error contracts are the API's exception handling contract: they tell clients *what to do*. Absent them, every failure is a mystery, debugging is archaeology (no request ID to trace), and consumer code is a basket of string greps. Modern APIs define errors structurally (RFC 7807-style, typed codes, correlation IDs).","manifests":"Bare 500s with HTML error pages, `{\"error\": \"something went wrong\"}`, no `requestId`/trace id in responses, no error-code taxonomy, validation errors that differ per endpoint, logs of errors without the request context, monitoring that can't tell retriable from fatal.","detection":"Error-contract audit — sample responses (curl status codes + bodies), check status-code semantics (4xx/5xx correctness), look for a shared error schema/framework, check request IDs in headers/logs; check error tracking (correlated stack traces per endpoint); verify monitoring can segment error classes.","yellow":"Inconsistent error bodies and some misclassified status codes, request IDs partial.","red":"Generic 500s (or worse, HTML error pages) as normal practice, no request correlation anywhere, or error logs that can't reconstruct a single failing request.","yellow_rationale":"warning — debugging is slow, not impossible.","red_rationale":"every incident is archaeology — MTTR structurally high.","criteria":{"0":"500s + HTML + zero correlation.","1":"mostly generic, no correlation","2":"partial/inconsistent","3":"structured + correlated"},"scope":"Error-contract semantics; duplicated handling infrastructure is ARCH-12, log infrastructure quality is PERF-01.","applicability":"API-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # semantic correctness needs observed responses\nestimated_when: >=2 of {contract, correlation, smells} probes ran   # clamp [1,2]\nunknown_when:   handlers unparseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when contract+correlation both present/absent cleanly\nscope_limited:  sampled handlers -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: central contract ∧ correlation present; minor smell count\n- `1`: no shared schema ∨ no correlation IDs ∨ pervasive catch-all-500 pattern\n- `3`/`0` unreachable by construction","fact_schema":"{\"api07\": {\n  \"error_contract\": {\"rfc7807\": false, \"central_handler\": true, \"schema_file\": \"errors.py\"},\n  \"request_id_middleware\": true,\n  \"static_smells\": {\"catch_all_500\": 12, \"success_wrapped_errors\": 3},\n  \"tracker_sdk\": \"sentry\"}}","budget_class":"fast","evidence":"basis: \"error-semantics: contract={kind}; correlation={bool}; smells {k} ({classes}); tracker={sdk}\"","remediation":{"quick_win":"standardize an error contract (RFC 7807 or a JSON schema: code, message, correlationId, retriable flag), add request IDs everywhere, fix the worst misclassifications.","structural":"framework-level error middleware (single source of truth), typed error taxonomy, API-monitoring that segments by error class, error payloads free of PII.","gold_standard":"Every endpoint returns structured, typed, correlated errors; 4xx/5xx semantics correct; a failing request is traceable in seconds; clients can act on errors programmatically.","effort":"🔶 ~2–4 h"}},
  "API-08": {"id":"API-08","category":"API","name":"Consumer Blindness & Backward Compatibility","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"NO","rollup":"deep-dive","gates":[],"definition":"The team doesn't know its API consumers — no consumer registry, no usage telemetry on endpoints/fields, no deprecation communication channel, and breaking changes are discovered via angry emails rather than design.","why":"An API you can't see is an API you can't manage. Modern API platforms know their consumers (who calls what, which fields, which versions), so changes are rational. Legacy APIs are usually blind — grief-driven, reactive, and hostile to change, which freezes the whole platform.","manifests":"No consumer registry, no endpoint analytics, \"who uses this?\" → \"some client from 2017 maybe,\" no changelog/deprecation announcements, consumer teams discovered when they break, no rate-limit/usage data per client.","detection":"Telemetry/inventory — is there endpoint analytics (each client's call voland field usage)? A consumer registry or at least API-key/credential per consumer? Deprecation announcement channel (changelog, emails, status page)? Interview: can the team answer \"which external systems call endpoint X\"? Measure breach incidents of the last year.","yellow":"Some analytics (API keys, traffic per endpoint), no full consumer registry, deprecation ad hoc.","red":"Zero consumer visibility, changes shipped without any ability to know who's affected, or repeated consumer-breakage incidents.","yellow_rationale":"warning — awareness is partial.","red_rationale":"the API is unowned — every change is a blind shot.","criteria":{"0":"blind changes, repeated breakage.","1":"analytics silo'd, no registry","2":"partial analytics","3":"full visibility + registry"},"scope":"Consumer-awareness gap; the versioning mechanics that serve them are API-02.","applicability":null,"statusing":"measured_when:  never\nestimated_when: never                            # key-in-config hints prove registration exists, not awareness quality\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"api08\": {\"status\": \"unknown\",\n            \"reason\": \"field-usage/consumer inventory requires telemetry or registry access\"}}","budget_class":null,"evidence":"emission: \"unknown — needs per-consumer call-volume/field telemetry (deep scan with org access)\"","remediation":{"quick_win":"add per-consumer API keys + endpoint analytics (who, what, how often), start a consumer registry doc.","structural":"full usage telemetry (endpoint + field level), a deprecation communication channel (changelog + consumer mailer + status page), consumer onboarding/registration as standard, usage dashboards for product decisions.","gold_standard":"Every consumer known + registered, endpoint/field usage visible, deprecations announced with migration guides, zero surprise consumer breakage.","effort":"🔶 ~2–4 h"}},
  "API-09": {"id":"API-09","category":"API","name":"Idempotency & Retry Semantics","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"The API has no idempotency guarantees or retry contract — clients cannot retry safely; duplicate submissions double-charge/duplicate records, and there's no `Idempotency-Key`/`idempotency` mechanism or documented retry policy.","why":"In a network world, retries are inevitable — a retryable-without-idempotency API converts network blips into business-correctness bugs (double payments, duplicate orders). Modern API design treats idempotency as a first-class guarantee for state-changing operations. Its absence is a correctness-era artifact.","manifests":"Payment/order/import endpoints without idempotency keys, no deduplication keys, timeouts without conflict-surfacing, docs silent on retry behavior, \"we had a double-charge issue last month\" incidents.","detection":"Design audit of all state-changing endpoints — idempotency mechanism (`Idempotency-Key` header, `client_ref`, unique constraints) present and enforced; retry policy documented; test the behavior (replay same payload twice; check duplicate side effects); incident history for duplicate-processing.","yellow":"Most state-changing endpoints lack idempotency; retry/duplicate incidents occasional and manually reconciled.","red":"Core money/mutation endpoints have no idempotency and no dedupe, and duplicate side effects have already cost money/duplicated records.","yellow_rationale":"warning — currently handled by reconciliation heroics.","red_rationale":"this is a standing correctness breach for the money path.","criteria":{"0":"duplicates have already occurred.","1":"money/mutation flows lack it","2":"most, gaps in peripheral","3":"all state-changing enlistments idempotent"},"scope":"Idempotency/retry semantics; generic error handling is API-07, sync-coupling shape API-04.","applicability":"API-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # enforcement proof needs a replay test\nestimated_when: route set enumerated           # clamp [1,2]; confidence medium when dedupe-store evidence clear\nunknown_when:   handlers unparseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  sampled routes -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: most state-changing core routes idempotent-by-design; minor gaps\n- `1`: retries configured against non-idempotent endpoints ∨ no idempotency machinery at all on payment-class flows\n- `3`/`0` unreachable by construction","fact_schema":"{\"api09\": {\n  \"state_changing_routes\": 26,\n  \"idempotent_by_design\": 8,\n  \"dedupe_store_present\": true,\n  \"outbound_retries_without_idempotency\": [{\"client\": \"payment-svc\", \"route\": \"POST /charge\"}]}}","budget_class":"fast","evidence":"basis: \"idempotency-probe: {k}/{n} state-changers idempotent-by-design; unsafe retry pairs={list}\"","remediation":{"quick_win":"add an idempotency key + response-replay on the top money flows, add a unique constraint (order/client_ref) as a backstop.","structural":"idempotency as a platform primitive (framework middleware, key storage, replay store), document retry semantics, idempotency tests in CI for all mutation endpoints.","gold_standard":"All state-changing endpoints idempotent + tested, retry policy documented, duplicate side effects impossible.","effort":"🔷 ~1–2 days"}},
  "API-10": {"id":"API-10","category":"API","name":"Contract Schema Evolution Process","tier":"A","default_status":"measured","effort":"🔷 ~1–2 days","v1":"YES","rollup":"deep-dive","gates":[],"definition":"There is no process for evolving API contracts safely — no schema registry, no compatibility checking (additive-only change policy, protobuf/OpenAPI backward-compat rules), no versioned schema lifecycle, so \"just change the field\" is the default even when it breaks consumers.","why":"Schema evolution is the discipline behind versioning (API-02): a defined set of moves that are safe (add field, add optional, widen) vs. breaking. Without it, contract changes are decided by mood, and consumers break by accident. Modern platforms centralize this (schema registry + compat checks in CI).","manifests":"No schema registry, no `openapi-diff`/`buf breaking` in CI, breaking field removals pass review, event schemas changed with no consumer migration, \"we thought it was private\" surprises, no additive-value policy.","detection":"Process audit — is there a schema registry/repo of record? A compatibility gate in CI (openapi-diff, `buf`, protobuf `buf breaking`, JSON-schema compat check)? Events versioned with schemas? Check review history for breaking changes that merged; measure consumer breaks caused by schema changes.","yellow":"Additive-change culture informally, no registry or gate, breaking merges rare but possible.","red":"Breaking contract changes merge regularly with consumer breakage, or event schemas change with no consumer awareness, and no registry/gate/culture exists.","yellow_rationale":"warning — working by shared etiquette, one new hire from a breakage.","red_rationale":"the contract is owned by no one — evolution is an incident factory.","criteria":{"0":"regular silent schema breakage.","1":"occasional breaking merges","2":"additive culture, no tooling","3":"registry + gate"},"scope":"Evolution infrastructure/process; contract currency is API-01, versioning mechanics API-02.","applicability":"API-01 clause-b. Else applicable.","statusing":"measured_when:  never auto-measured            # \"process\" maturity is not fully artifact-provable\nestimated_when: >=2 of {registry, gate, events-versioning} probes computed   # clamp [1,2]\nunknown_when:   no schema surface found\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when blocking gate evidenced\nscope_limited:  thin release history -> estimated low","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: registry or versioned events present ∧ non-blocking or partial gate coverage\n- `1`: schemas exist with no registry ∧ no compat gate ∨ gate advisory-only\n- `3`/`0` unreachable by construction","fact_schema":"{\"api10\": {\n  \"registry\": {\"kind\": \"buf\", \"evidence\": \"buf.yaml\"},\n  \"compat_gate\": {\"present\": true, \"blocking\": true, \"step\": \"ci.yml:42 buf breaking\"},\n  \"events_versioned\": true,\n  \"breaking_without_note_sampled\": 0}}","budget_class":"api-budgeted","evidence":"basis: \"evolution-probe: registry={kind}; compat-gate={bool}(blocking={b}); events versioned={bool}\"","remediation":{"quick_win":"add an OpenAPI/buf compatibility check to CI (fail on breaking changes), document the additive-change policy.","structural":"schema registry + versioned schemas (event + API), compat gate enforced, consumer-migration process for breaking changes (deprecate → migrate → remove), telemetry of consumers (API-08).","gold_standard":"Compat gates in CI, schema registry current, breaking changes rare and migration-led, event schemas versioned with consumers tracked.","effort":"🔷 ~1–2 days"}},
  "VEL-01": {"id":"VEL-01","category":"VEL","name":"CI/CD Build Duration","tier":"B","default_status":"estimated","effort":"⚡ ≤30 min","v1":"PART","rollup":"standard","gates":[],"definition":"The time from push to mergeable feedback — build, lint, tests, quality gates — in CI is measured in many minutes to hours, occasionally times out, and has been drifting upward for quarters.","why":"CI feedback latency is *the* throttle on delivery: the longer it is, the less often it runs, the more it's skipped, and the more merge queues and context-switching cost. DORA research is unambiguous — throughput tracks feedback speed. A growing build time is also a proxy for test bloat and unowned pipelines.","manifests":"CI analytics (pipeline duration trend), \"Merge queue is full\" symptoms, engineers running subsets locally (\"I won't trigger the full build\"), build timeouts, weekend batch CI runs.","detection":"Pipeline analytics — GitHub Actions/GitLab/Jenkins duration stats per stage, P95 push-to-feedback, trend over 6–12 months; breakdown by stage (install/build/test/quality); check what's serial vs. parallel.","yellow":"15–30 min feedback loop; growing; partial parallelization.","red":"> 30 min loop or regular timeouts, or tests so slow they're split/dropped (connects TEST-04), or the trend is steeply up.","yellow_rationale":"warning — above modern norms, still survivable, tax is compound.","red_rationale":"the loop has broken — CI is no longer a feedback tool, it's a queuing tax.","criteria":{"0":"loop so slow it's routinely skipped.","1":"> 30 min or split/hope","2":"15–30 min","3":"< 10 min"},"scope":"End-to-end build latency; test-suite duration specifically is TEST-04 (stage attribution separates).","applicability":"`na_when: zero CI workflows` → N/A? No — zero CI is scored 0 territory of TEST-08/VEL rows generally; here N/A is admissible only if repo has no build at all (docs-only). Otherwise unknown.","statusing":"measured_when:  never in v1                      # elapsed wall-time ≠ instrumented stage timing\nestimated_when: >=5 runs sampled                 # clamp [1,2]; confidence low (\"elapsed signal\" caveat mandatory)\nunknown_when:   <5 runs / no CI\nna_when:        no-build tree\nclamp:          [1,2]\nconfidence:     low by rule","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: `p95 < R_MIN`\n- `1`: `p95 >= R_MIN` ∨ serial-bottleneck job dominating median\n- `3`/`0` unreachable by construction","fact_schema":"{\"vel01\": {\n  \"workflow\": \"ci.yml\", \"runs_sampled\": 25,\n  \"median_min\": 11.4, \"p95_min\": 26.0,\n  \"stage_split_known\": true,\n  \"serial_bottleneck_job\": \"e2e\"}}","budget_class":"api-budgeted","evidence":"basis: \"actions n={k}: push-to-green median {m}m, p95 {p}m (elapsed signal)\"","remediation":{"quick_win":"turn on caching, parallelize shards, drop the slow E2E from the merge path (TEST-04), float the slowest 10 tests once.","structural":"a CI budget (SLO on feedback time), dependency pruning (ECOS-06), test-suite redesign (TEST-03), and monitoring of pipeline trend.","gold_standard":"P95 feedback < 10 min; trend flat/declining; no timeouts; every engineer runs the pipeline before merge by habit.","effort":"⚡ ≤30 min"}},
  "VEL-02": {"id":"VEL-02","category":"VEL","name":"Local Dev Setup Time & Friction","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Getting a working local environment takes 1+ days, requires undocumented manual steps, depends on shared remote infrastructure (staging DBs, third-party credentials), or works only for the people who built it.","why":"Onboarding friction is a leading indicator of environment debt: it measures how far the codebase is from \"clone → `make dev` → code.\" Every extra day is a day of not shipping plus a chunk of your senior engineers' time being \"the database whisperers.\" It's also the first thing candidates/new hires report.","manifests":"Multi-page setup wiki with un-documented \"gotchas,\" `docker-compose` that half-works, devs pointing at shared remote DBs, setup requires obtaining 6 service credentials \"from Alex,\" \"it works on my machine\" as a known phrase, no `make dev`/Taskfile/script of record.","detection":"Onboarding tracking (time-to-first-green-build for new hires, \"Golden Path\" walkthrough), dev-experience survey, try-it test (have someone time a clean-machine setup), config audit (containers, seed scripts, env templates).","yellow":"1–2 days depending on custom local steps.","red":"> 3 days, or requires shared remote staging DBs / a single human's credentials / a \"provision me\" ticket.","yellow_rationale":"warning — above modern norm; the tax is real but survivable.","red_rationale":"the environment can't be reproduced — it's tribal infrastructure, not a codebase.","criteria":{"0":"tribal environment owned by individuals.","1":"> 3 days / shared deps","2":"1–2 days, custom steps","3":"one-command dev up"},"scope":"Setup friction posture; ARCH-09 scores agent-operability composition, DOCS-04 the guide's existence/currency.","applicability":"never N/A for scored repos (setup friction exists even when tooling absent).","statusing":"measured_when:  never auto-measured            # real time-to-first-green needs a timed run (execution)\nestimated_when: >=3 of {container, runner, env-template, docs} probes computed   # clamp [1,2]\nunknown_when:   tree unparseable\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium when full surface inventoried\nscope_limited:  none typical","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: scripted/containerized partial coverage; some manual steps remain\n- `1`: documented-manual-only ∨ missing env templates ∧ no task runner\n- `3`/`0` unreachable by construction","fact_schema":"{\"vel02\": {\n  \"devcontainer\": false, \"compose_dev\": true,\n  \"one_command_target\": \"make dev\",\n  \"env_example\": true, \"seed_script\": false,\n  \"readme_manual_steps_est\": 9,\n  \"posture\": \"scripted\"}}","budget_class":"fast","evidence":"basis: \"setup-inventory: posture={posture}; compose={bool}; make={target}; ~{n} manual steps in docs\"","remediation":{"quick_win":"containerize the stack with a one-command up, ship `.env.example`, write a working setup doc, document the \"Golden Path.\"","structural":"hermetic local env (containers, local deps with `testcontainers`), zero shared-remote requirement, setup scripted and CI-tested (a fresh container proves the guide works), \"works on my machine\" made unfalsifiable.","gold_standard":"`git clone && make dev` brings up a working local system in < 30 min with no external dependencies; the instruction is CI-verified.","effort":"🔶 ~2–4 h"}},
  "VEL-03": {"id":"VEL-03","category":"VEL","name":"Deployment Failure Rate (CFR)","tier":"B","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":["G6"],"definition":"A meaningful share of deployments either fail, are rolled back, or require emergency/incident-level intervention after the fact (DORA's Change Failure Rate), and the trend is not improving.","why":"CFR is the honest verdict on the whole \"system is shippable\" question. High CFR means every release is a bet — teams respond by shipping less (deploy frequency drops), which compounds: fewer deploys, bigger deploys, more failure. It's also a *gate* (G6) when it hits 30%+ with manual intervention.","manifests":"Rollback logs, incident tickets tagged \"deployment\", \"it broke after the release\" post-release issues, datadog deploy-markers with red cliffs, GitHub release history with hotfixes.","detection":"DORA metrics tracking — calculate CFR from deploy vs. rollback/hotfix data (commit rollout tracking, release annotations, incident tags), dashboards (Datadog, Sleuth, Faros/LinearB), manual release-history mining; distinguish failed-deploy vs. emergency-fix.","yellow":"CFR 15–30%, or rollbacks concentrated in specific release types.","red":"CFR > 30%, or deployments *requiring* manual intervention as standard, or rollback ceremony itself is an incident (triggers **G6**).","yellow_rationale":"warning — DORA's \"medium\" band; clearly improvable but not catastrophic.","red_rationale":"releases are the top risk surface — DORA's low band with extra hazard.","criteria":{"0":"> 30% + manual-only (G6).","1":"> 30% with some automation","2":"15–30%","3":"CFR < 15%, automated rollback"},"scope":"Deploy failure rate; release-path automation is VEL-08, deploy frequency VEL-04.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # outcome-free proxies would be exactly a scored guess\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"vel03\": {\"status\": \"unknown\",\n            \"reason\": \"failure rate requires deploy-outcome join\",\n            \"context_hints\": {\"hotfix_commits_last_90d\": 7}}}","budget_class":null,"evidence":"emission: \"unknown — needs deploy-vs-rollback join (deep scan); hotfix density {k}/90d as context\"","remediation":{"quick_win":"implement fast rollback (repo-state rollback, feature flags, DB-migration backup), add canary/smoke checks to catch the common failure classes, post-release verification automation.","structural":"smaller safer deploys (deploy frequency up = risk down), progressive delivery (canary, blue-green), automated rollback + observability slices, DORA tracked and reviewed monthly.","gold_standard":"CFR < 15% and falling, rollback is automated and boring, deploys are small and frequent, no manual prod intervention.","effort":"🔶 ~2–4 h"}},
  "VEL-04": {"id":"VEL-04","category":"VEL","name":"Deployment Frequency & Lead Time","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"The system deploys rarely (weekly→monthly→quarterly) with long lead times between code merge and production, and releases are \"big bang\" events rather than a steady stream.","why":"Rare, batched releases are a *symptom* of every other debt (slow CI, no tests, risky deploys) and a *multiplier* of it: the bigger the release, the harder to debug, the more likely the rollback, the less the business can iterate. DORA's elite band deploys on demand; legacy bands ship by calendar.","manifests":"Release calendar with named \"deploy days,\" monthly release trains, release freeze windows, \"merge window\" rules, multi-service coordinated releases, deploy frequency hidden (no data at all).","detection":"Release analytics — count production deploys per service per month (CI/CD + deployment tools), measure merge-to-prod lead time (median), inspect release process (release branch? freeze? feature-toggle zero?), interview \"when did you last release on a Tuesday on purpose?\"","yellow":"Weekly deploy cadence (or biweekly), lead time 1–5 days, some coordination required.","red":"Monthly-or-less cadence, lead time > a week, or every release is a coordinated multi-service event with a named human \"release manager\".","yellow_rationale":"warning — survivable but clearly below modern norms.","red_rationale":"the codebase's risk is now scheduled like a moon landing.","criteria":{"0":"coordinated calendar-driven releases as the norm.","1":"biweekly–monthly trains","2":"weekly, a few days","3":"on-demand deploys, < 1 day lead"},"scope":"Frequency/lead-time; failure outcomes are VEL-03, manual-step burden VEL-08.","applicability":"never N/A for scored repos; zero release events → score-0-territory measured facts (frequency ~0) with caveat.","statusing":"measured_when:  never in v1                      # tag ≠ deploy truth (04 §5 caveat mandatory)\nestimated_when: >=5 events in window             # clamp [1,2]; confidence low always\nunknown_when:   API unavailable / rate-limited\nna_when:        never\nclamp:          [1,2]\nconfidence:     low by rule (\"tag-based proxy, not deploy logs\")","score_mapping":"Y/R values (DORA bands): see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: monthly-or-faster cadence ∧ lead time below Red band\n- `1`: quarterly-or-slower ∨ lead time in Red band\n- `3`/`0` unreachable by construction","fact_schema":"{\"vel04\": {\n  \"deploys_per_month_est\": 3.2,\n  \"lead_time_median_days\": 6.5,\n  \"source\": \"tags+deployments\",\n  \"cadence\": \"irregular\"}}","budget_class":"api-budgeted","evidence":"basis: \"release-proxy {n} events/12mo (~{d}/mo); lead-time median {l}d [tag-based]\"","remediation":{"quick_win":"remove freeze/merge windows, do Friday non-events, add a deploy button per service.","structural":"the classic modernization goal — trunk-based dev + feature flags + small CI/CD steps to get deployment-frequency up and lead time down; each elimination of coordination is a DORA win.","gold_standard":"Deploy on demand (multiple/week/service), lead time < 1 day, releases are boring non-events, no release manager role needed.","effort":"🔶 ~2–4 h"}},
  "VEL-05": {"id":"VEL-05","category":"VEL","name":"Onboarding Lead Time to First Production PR","tier":"D","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"A new engineer takes weeks (not days) to reach \"shipped my first change to production,\" and the lag is a feature of the codebase, not of the hire.","why":"Time-to-first-PR is the sum of every knowledge and environment debt in one number: unclear architecture, missing docs, painful setup (VEL-02), scary deploys, knowledge silos. It's also a recruiter's and retention metric — candidates who take a month to feel productive leave.","manifests":"Onboarding documentation sparse or stale, no starter tickets, architecture \"must shadow for 3 weeks before touching anything,\" complex setup blocks, tribal knowledge required to understand safe places to change, first PR weeks out.","detection":"Onboarding tracking — time from start to first merged prod-change PR per hire (git + HR data), onboarding survey (self-reported productiveness date), review of onboarding docs/tickets, \"first-change\" blocker log (what did they wait on?).","yellow":"2–4 weeks to ship first PR; onboarding partially documented.","red":"> 4 weeks for most hires, or onboarding is oral/tribal with no written path.","yellow_rationale":"warning — above the modern two-week line, still tolerable.","red_rationale":"the codebase's knowledge is not transferable — that's a structural timer on the team.","criteria":{"0":"onboarding entirely tribal.","1":"> 4 weeks, documented-ish","2":"2–4 weeks","3":"< 1 week"},"scope":"Onboarding time-to-contribution; the docs/tooling that influence it are DOCS-04/VEL-02 rows.","applicability":null,"statusing":"measured_when:  never\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"vel05\": {\"status\": \"unknown\", \"reason\": \"requires per-hire join of start date to first merged prod PR\"}}","budget_class":null,"evidence":"emission: \"unknown — needs git+HR join per hire (org data); setup posture proxies live in VEL-02\"","remediation":{"quick_win":"write a \"first PR in a day\" path (a safe starter ticket + doc patch + tiny config change), assign onboarding buddy + SLA, grant prod deploy gradually but early.","structural":"fix the underlying debts (setup VEL-02, docs DOCS, deploy VEL-03), curriculum-style onboarding (architecture walkthroughs, ADRs), starter-ticket backlog maintained.","gold_standard":"New engineers ship to prod within their first week, via documented path, with a clear map of the safe-to-change surfaces.","effort":"🔶 ~2–4 h"}},
  "VEL-06": {"id":"VEL-06","category":"VEL","name":"Bus Factor / Knowledge Concentration","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"Critical modules are known by one or two people; whole subsystems are \"only Paul understands\"; there's no redundancy, no docs (see DOCS), and Paul's vacation/exit is a risk event. At the extreme, one author owns most of the codebase.","why":"Knowledge concentration is the human face of the same problem as undocumented APIs: the system is maintained by memory, not by structure. It converts a normal life event (someone leaves) into an outage or a stall — and it's alarmingly common in \"the codebase only one person can touch\" legacy systems.","manifests":"Git author analysis (one author dominates critical files/whole repos), \"ask Paul\" as the architecture diagram, modules with zero review history, no ADRs/runbooks (DOCS-01/03), the person who \"knows the billing hack.\"","detection":"Git author distribution — `git shortlog -sne -- <critical module>` to find ownership concentration, per-file/blob authorship, review-history coverage (did a file ever get a second pair of eyes?); interview \"name the diagram you'd draw if Paul left.\"","yellow":"Single author responsible for > 50% of a critical module; a couple of know-it-all dependencies.","red":"A single author owns > 80% of an entire codebase (or every critical service is Paul), zero documentation, zero shared context.","yellow_rationale":"warning — reviewable, but the clock is ticking on retention.","red_rationale":"Paul leaving *is* a system failure — the codebase is functionally a memory he carries.","criteria":{"0":"one author owns the codebase (and it's now or never).","1":"single author on critical modules","2":"concentration in a couple modules","3":"distributed ownership"},"scope":"Who owns the knowledge; churn∩defect concentration is ARCH-05.","applicability":"`na_when: history < 6 months or single-committer repo from day one` → the latter is itself score-0 signal, so only thin-history → unknown. Else applicable.","statusing":"measured_when:  >=200 commits in window         # authorship distribution is fact\nestimated_when: truncated window                # clamp [1,2], confidence low\nunknown_when:   <6 months history\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  shallow-since clone -> estimated + scope-limited","score_mapping":"Y/R values (bus-factor bands): see §3.\n\n- `3`: repo bus factor ≥ Y_BF and no core module at 1\n- `2`: bus factor adequate repo-wide, single-owner peripheral modules\n- `1`: bus-factor-1 on isolated core module\n- `0`: bus-factor-1 across multiple core modules / majority of codebase","fact_schema":"{\"vel06\": {\n  \"window_days\": 365,\n  \"bus_factor_repo\": 3,\n  \"worst_modules\": [{\"path\": \"payments/\", \"bus_factor\": 1, \"top_author_share\": 0.91}],\n  \"review_coverage_pct\": null}}","budget_class":"fast","evidence":"evidence: \"git-mining {w}d: bus_factor={bf} ({n} committers); worst {path} bf=1 share={s}%\"","remediation":{"quick_win":"pair-and-document the top exclusive modules (forced bus-factor increase), get a second reviewer on every critical file from here on.","structural":"architecture that doesn't need a walking encyclopedia (simplify, DOCS), quarterly rotation of module owners, an \"unlearnable-list\" audit (which files can no one explain without the author).","gold_standard":"No module with single-author > 50%; anyone can explain/deploy any critical service within a day; a leaving engineer is a 1-day disruption, not an event.","effort":"⚡ ≤30 min"}},
  "VEL-07": {"id":"VEL-07","category":"VEL","name":"Environment Reproducibility / Works-on-My-Machine","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Local, staging, and prod environments drift so much that \"works on my machine\" is a standing phenomenon — configs differ, versions differ, data differs, and bugs only reproduce in one environment.","why":"Environment reproducibility is the ground truth behind every \"it works here\" argument. Its failure means the team's work product (a fix) doesn't reliably transfer to prod — the whole loop of develop→test→deploy is leaky. Pairs with DATA-10 (schema drift) but covers the whole stack.","manifests":"The \"works on my machine\" retort, environment-specific bugs, config files differing per env by hand, no containerized parity, feature flags on in one env only, \"we can't reproduce\" tickets, version skew local vs. prod.","detection":"Parity audit — compare dev/CI/staging/prod versions (runtime, deps, OS, configs); check for canonical config pipeline (IaC + env-config injection) vs. hand-edited files; try \"reproduce the prod bug in a container\" TIMED; survey \"last time a support bug was reproduced locally\".","yellow":"Some config/version divergence between envs, occasional prod-only bugs.","red":"Reproducing prod locally is routinely impossible, or configs are maintained per-env by hand with no source of truth.","yellow_rationale":"warning — the leak is real but not structural yet.","red_rationale":"you cannot develop against your product — every fix is blind until it's not.","criteria":{"0":"local ≠ prod, routine blind shipping.","1":"meaningful divergence, repro hard","2":"minor divergence","3":"full parity"},"scope":"Env-parity posture; flag/config mechanics are ARCH-10, IaC coverage PERF-06, schema drift DATA-10.","applicability":"never N/A for scored repos.","statusing":"measured_when:  never auto-measured            # parity truth is behavioral\nestimated_when: >=3 parity probes computed     # clamp [1,2]; confidence medium when pins+IaC+injection all seen\nunknown_when:   no deploy/config artifacts at all\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  none typical","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: mostly-canonical pipeline; minor hand-edited per-env residue\n- `1`: hand-edited per-env files with keyset divergence ∨ unpinned runtimes ∧ no containers\n- `3`/`0` unreachable by construction","fact_schema":"{\"vel07\": {\n  \"containerized\": true, \"iac_present\": true,\n  \"env_injection\": {\"ci_refs\": true, \"committed_per_env_files\": [\"config/prod.py\", \"config/staging.py\"]},\n  \"env_keyset_divergence\": 4,\n  \"runtime_pins_consistent\": true}}","budget_class":"fast","evidence":"basis: \"parity-inventory: containers={bool}; iac={bool}; injection={bool}; per-env divergence {k} keys\"","remediation":{"quick_win":"containerize dev for parity, make config canonical (one source of truth, injected per env), stand up a staging clone of prod config.","structural":"full parity — same containers/versions everywhere, IaC for all envs, config as code, \"prod reproduction\" as a standard step (spin replica to confirm).","gold_standard":"Any environment can be rebuilt to match prod; prod-only bugs are a thing of the past; config drift is zero-diff against the source of truth.","effort":"🔶 ~2–4 h"}},
  "VEL-08": {"id":"VEL-08","category":"VEL","name":"Manual Release Steps & Operability","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":["G6"],"definition":"Releasing requires human, tool-less steps — SSH-ing to prod, editing files there, running commands by hand, sharing credentials, a \"release manager\" clicking through, or no deploy automation at all.","why":"Manual releases are the coarse end of the CI/CD spectrum — they cap frequency, inherit human error, require privileged access by hand, and make auditing who-did-what impossible. In the era of a button per service, a script run by one person with prod SSH is a definition of operational debt. It's also the second half of gate G6.","manifests":"Deploy runbooks (\"SSH to x, pull, run migration, restart\"), no CI on release path, someone's terminal of recorded commands, vendor-wrap deploy steps, prod edited directly (hotfixes in vim), shared prod credentials, no audit of deployments.","detection":"Release-path audit — trace the last 5 releases end-to-end: was anything done by hand? cin which env did commands run? Is there a CI/CD artifact → environment promotion path? Check for prod direct edits, shell-history deploys, deployment audit logs.","yellow":"Some manual release steps (a couple of hand SQL/migrations, config push), automated enough to be \"mostly CI.\"","red":"Deploys *only* happen via manual scripts on prod hosts, or prod is routinely edited by hand (triggers **G6**).","yellow_rationale":"warning — a bit of heroic residue, still runnable by a trained person.","red_rationale":"the release path is one human's terminal — fragile, un-auditable, unscalable.","criteria":{"0":"script-on-prod is the release path (G6).","1":"mostly manual pipeline","2":"some manual residue","3":"fully automated + audited"},"scope":"Release-path mechanics; deploy outcomes are VEL-03, frequency VEL-04.","applicability":"never N/A for scored repos; no CI at all → measured score-0 territory (manual-by-default), clause-b evidence.","statusing":"measured_when:  tree enumerated                # automation presence/absence decidable statically\nestimated_when: partial CI parse               # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium\nscope_limited:  deploy infra outside repo -> estimated + scope-limited note","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: full CD chain ∧ rollback target ∧ zero prod-edit smells\n- `2`: automated build+push, one-command manual last mile\n- `1`: multi-step manual deploys ∨ rollback prose-only\n- `0`: no deploy automation at all ∨ prod-direct-edit culture signals on core ops","fact_schema":"{\"vel08\": {\n  \"cd_chain\": {\"build\": true, \"registry_push\": true, \"deploy_job\": false},\n  \"release_automation\": {\"tool\": null},\n  \"rollback_target\": false,\n  \"manual_procedure_steps_est\": 14,\n  \"prod_direct_edit_smells\": [{\"file\": \"ops/fix.sh\", \"pattern\": \"ssh prod\"}]}}","budget_class":"fast","evidence":"evidence: \"release-audit: cd-chain b/p/d={bool}/{bool}/{bool}; rollback={bool}; ~{n} manual steps; smells={k}\"","remediation":{"quick_win":"capture the manual steps as a CI/CD job (artifact → deploy), remove direct prod SSH, add an audit log of every deployment.","structural":"full automated promotion (CI build artifact → envs), IaC-managed infra (PERF-06), deploy from immutable artifacts (never from a checkout on a server), prod access by deploy pipeline only.","gold_standard":"Zero manual steps; deploys are CI pipeline promotions with audit; prod editability removed; an audience of \"the pipeline did it\" for every release.","effort":"🔶 ~2–4 h"}},
  "VEL-09": {"id":"VEL-09","category":"VEL","name":"PR & Code-Review Hygiene","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Code review is rubber-stamped or absent — low PR coverage, thousands-of-line PRs, admin merges and direct pushes, reviews with no changed-code reading — so quality and knowledge transfer depend on unfiltered commits.","why":"Review is the last human gate before code becomes shared truth. Its decay tracks maintenance abandonment: when nobody reads diffs, decisions stop being questioned, knowledge stops transferring, and both defect rate and bus factor rise quietly. Legacy repos typically show both extremes at once — none of the discipline, all of the ceremony.","manifests":"PRs merged without review or with an admin bypass, direct pushes to main, median PR sizes in the thousands of lines or multi-week lifetimes, \"LGTM\" reviews with zero comments, reviews concentrated in one person (feeds VEL-06), no review on the core/path-critical services.","detection":"GitHub/PR API mining — review coverage % of PRs, median and p95 PR size (additions+deletions), median time-to-first-approval, comment density (non-author comments per 100 LOC), bypass/admin-merge rate, direct-push count to protected branches; sample the top 20 PRs for \"was the diff actually read.\"","yellow":"Review coverage < 80% or rubber-stamp for some modules; median PR 500–1,000 LOC; review latency days.","red":"Reviews effectively absent — admin merges / direct pushes as normal practice, or core-path changes ship unreviewed, or median PRs > 1,000 LOC so reviews are theater by construction.","yellow_rationale":"mostly functioning, but the gate is leaking on size and speed.","red_rationale":"there is no longer a shared reading of the code — defects and knowledge holes land unchallenged.","criteria":{"0":"admin merges / direct pushes as the norm, no real review exists.","1":"core paths sometimes unreviewed or consistently oversized PRs","2":"some rubber-stamp, PRs 500–1,000, latency days","3":"full coverage, small PRs, substantive reviews"},"scope":"Review/PR process hygiene; branching topology is VEL-10's row.","applicability":"never N/A for scored repos.","statusing":"measured_when:  >=50 PRs sampled               # distributions are facts\nestimated_when: 10 <= n < 50                   # clamp [1,2], confidence low (\"small sample\")\nunknown_when:   <10 PRs (young repo) or API unreachable / non-GitHub forge\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium at full sample\nscope_limited:  sample truncated by budget -> estimated + scope-limited","score_mapping":"Y/R values: see §3.\n\n- `3`: coverage ≥ Y_COV ∧ sizes in healthy band ∧ bypass ≈ 0 ∧ no direct-push pattern\n- `2`: coverage present, p95 size above Yellow, latency elevated\n- `1`: coverage < Y_COV ∨ chronic oversized PRs ∨ regular bypasses\n- `0`: bypass/direct-push normative (majority of changes) ∧ no review culture evidence","fact_schema":"{\"vel09\": {\n  \"prs_sampled\": 200,\n  \"review_coverage_pct\": 0.86,\n  \"pr_size_median_loc\": 210, \"p95\": 1400,\n  \"time_to_first_approval_median_h\": 9.5,\n  \"bypass_rate_pct\": 0.04,\n  \"direct_pushes_default_branch\": 11}}","budget_class":"api-budgeted","evidence":"evidence: \"pr-mining n={k}: review {p}%; median {m} LOC (p95 {q}); approval {h}h; bypass {b}%\"","remediation":{"quick_win":"enforce branch protection with required reviews on core paths, ban direct pushes, add a PR-size lint (split > 400-LOC PRs), publish review-coverage metrics.","structural":"review as a first-class metric (coverage, size, latency tracked), pairing/small-PR culture, a second reviewer on security-adjacent paths, \"no unreviewed merge\" as an org rule.","gold_standard":"100% coverage on core paths, median PR < 400 LOC, reviews substantive (comments, not emoji), zero bypasses, review latency < 1 day.","effort":"🔶 ~2–4 h"}},
  "VEL-10": {"id":"VEL-10","category":"VEL","name":"Branching & Monorepo Strategy Legacy","tier":"A","default_status":"measured","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The branching model is a legacy ceremony — GitFlow-style long-lived branches, release branches that live for weeks, merge windows, trunk divergence — or a monorepo/multi-repo split that no longer matches how the team ships, so integration is a sprint in itself.","why":"Branch strategy is the plumbing of trunk-based delivery: the modern norm is short-lived branches, trunk as the source of truth, and continuous integration. Long-lived branches and forced merge windows are the *brakes* every other modernization win has to fight — they multiply merge cost, hide integration failures until merge time, and convert \"ship\" into a scheduled drama.","manifests":"`develop` vs `main` with a promotion ceremony, release branches older than 2 weeks, weeks-old \"feature\" branches, mandatory merge freezes, no enforcement of trunk stability (broken builds on main), a monorepo where every deploy drags everything, or a multi-repo where one logical change spans six PRs.","detection":"Git topology audit — branch age distribution (release + feature branch lifetimes), distance-from-trunk (commit divergence), merge-window/CI-config evidence (is main always green?), direct-push protection, monorepo/multi-repo change-span (how many repos does one logical change touch), PR-to-merge time outliers.","yellow":"GitFlow-style ceremony with mostly-short branches; occasional month-long branches; a couple of forced merge windows; multi-repo changes needing coordination.","red":"Release branches weeks old with accumulating divergence, trunk routinely broken, mandatory merge windows/freezes as policy, or a monorepo/multi-repo shape that makes every change a coordination event.","yellow_rationale":"friction is real but the train mostly runs.","red_rationale":"integration is a permanent tax — every DORA-style improvement is blocked at the plumbing.","criteria":{"0":"coordinated multi-week merge ceremony as the norm — plumbing blocks all modernization velocity.","1":"release branches drifting, trunk often red","2":"GitFlow ceremony, mostly short, occasional windows","3":"short-lived branches, trunk green, no windows"},"scope":"Branch/release topology; PR-level review behavior is VEL-09, multi-service skew ECOS-09.","applicability":"never N/A for scored repos.","statusing":"measured_when:  history >=6 months             # topology is fact\nestimated_when: truncated history / shallow clone   # clamp [1,2], confidence low\nunknown_when:   no usable history\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  branch list capped -> estimated + scope-limited","score_mapping":"Y/R values: see §3.\n\n- `3`: trunk-based or short-lived branches ∧ trunk green\n- `2`: some stale branches, no release-train lock-in\n- `1`: long-lived release branches ∨ heavy divergence on core dirs\n- `0`: multi-week integration windows ∨ cross-repo change span requiring lockstep releases without tooling","fact_schema":"{\"vel10\": {\n  \"branches_total\": 143, \"stale_over_30d\": 61,\n  \"model\": \"long-lived-release\",\n  \"max_divergence_commits\": 214,\n  \"merge_window_bursts\": true,\n  \"trunk_green_rate_30d\": null}}","budget_class":"fast","evidence":"evidence: \"git-topology: {n} branches ({s} stale>30d); model={model}; max-divergence {d} commits\"","remediation":{"quick_win":"trunk-based basics — short-lived branches < 3 days, protect main + require green CI, delete the oldest release branch with a manual backport policy.","structural":"move to trunk-based development with feature flags (ties ARCH-10), shrink multi-repo coordination via a platform or monorepo_tools strategy, enforce main-always-green with a CI gate.","gold_standard":"Branches live < 3 days, main is always mergeable and green, merges are small and continuous, no merge windows, one logical change fits in one repo/PR.","effort":"⚡ ≤30 min"}},
  "VEL-11": {"id":"VEL-11","category":"VEL","name":"Developer Experience Tooling","tier":"B","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"PART","rollup":"deep-dive","gates":[],"definition":"The local coding experience is primitive — no scaffolding/generators, no hot reload, no IDE integration, no codegen, no task runners of record, so modern DX affordances (AI tooling, named tasks, watch mode) either don't work or never existed.","why":"DX tooling is the difference between a codebase that feels \"built in the era it was made\" and one that feels current. It's also an objective check for modernization-readiness: AI-assisted tooling (copilots, agents, refactoring machines) performs dramatically worse on pre-modern setup (long builds, no types, no task definitions). It's the canary for \"can we tool this codebase going forward.\"","manifests":"No `Makefile`/Taskfile/`just`/npm scripts of record, no codegen/scaffolding (hand-copying boilerplate), no watch/hot reload, long cold starts per action, no language-server-friendly project structure, manual \"create a new endpoint\" rituals.","detection":"DX audit — inventory developer tooling (task runner, scaffolding, watch mode, codegen), measure cold-start time for the common inner-loop (edit→rebuild→test), check IDE/AI-tool friction (does the language tooling index cleanly? any `exclude` hacks?), survey \"name one script that makes you faster vs. one that makes you slower\".","yellow":"Inner loop 5–15 min, some tooling but no scaffolding, DX tax noticeable.","red":"Inner loop > 15 min (cold builds, manual steps), no task runner of record, no generator for boilerplate, and modern tooling/AI integration effectively impossible/agonizing.","yellow_rationale":"warning — above modern norms, survivable.","red_rationale":"the inner loop is the most frequent cost in software; this one is running at loss-leader rates.","criteria":{"0":"ritualistic manual inner loop.","1":"> 15 min with some scripts","2":"5–15 min inner loop","3":"fast inner loop, tooled"},"scope":"Tooling breadth/wiring; setup friction is VEL-02, agent-operability composition ARCH-09.","applicability":"never N/A.","statusing":"measured_when:  never auto-measured            # the decisive metric is timed inner-loop latency\nestimated_when: inventory completed            # clamp [1,2]; confidence medium when CI-wired evidence exists\nunknown_when:   tree unparseable\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium with usage proof; low presence-only\nscope_limited:  none typical","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: runner + partial automation (watch or codegen) wired\n- `1`: no task runner of record ∨ nothing wired into CI\n- `3`/`0` unreachable by construction","fact_schema":"{\"vel11\": {\n  \"task_runner\": {\"present\": true, \"tool\": \"make\", \"targets\": [\"dev\", \"test\", \"lint\"]},\n  \"scaffolding\": false, \"watch_scripts\": true, \"codegen\": [\"openapi-generator\"],\n  \"ci_wired_codegen\": true}}","budget_class":"fast","evidence":"basis: \"dx-inventory: runner={tool}; scaffolding={bool}; watch={bool}; codegen wired-in-ci={bool}\"","remediation":{"quick_win":"define a task runner of record (Makefile/Taskfile), add scaffolding commands for the top 3 boilerplates, enable watch mode.","structural":"invest in DX as product work — fast inner loop, generated code, language-server health, CI parity for local checks.","gold_standard":"Inner loop < 1 min, scaffolding for common work, task runner documented and CI-consistent, AI/IDE tooling first-class.","effort":"🔷 ~1–2 days"}},
  "VEL-12": {"id":"VEL-12","category":"VEL","name":"Incident Recovery / MTTR","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"Recovery from incidents is slow and manual — mean time to restore is hours-plus, runbooks are absent or wrong, rollback is manual, diagnosis relies on a few experts, and the same failure mode repeats because no systemic fix follows.","why":"MTTR is the operational output of the whole diagnosis chain (observability PERF-01, error semantics API-07, runbooks DOCS-03, deploy safety VEL-03). A system that fails and takes half a day to bring back is, from the business's point of view, half a day dead — and it's the standard legacy profile.","manifests":"On-call \"heroics,\" no runbooks (or stale), diagnosis by `ssh` + `grep`, manual rollback scripts, repeated incidents of the same class, no blameless postmortens, no incident metrics tracked at all.","detection":"Incident analytics — PagerDuty/incident-tool MTTR and MTTD, incident-class repetition (same cause ≥ 2×/quarter), rollback time measurement, runbook coverage/currency audit, postmortem quality (actions taken?) and backlog closure rate.","yellow":"MTTR 1–2 h, runbooks partial, rollback mostly manual, some repetition.","red":"MTTR > 4–6 h, no runbooks, rollback is a manual nightmare, or the same incident recurs quarterly.","yellow_rationale":"warning — under professional norms is achievable, currently over.","red_rationale":"hours of absolute downtime + a fix that never happens = business-critical failure.","criteria":{"0":"half-day incidents, recurring, no runbooks.","1":"> 4 h, manual","2":"1–2 h, runbooks partial","3":"MTTR < 30 min, drill-proven"},"scope":"Recovery-time outcomes; the runbook artifacts that support recovery are DOCS-03.","applicability":null,"statusing":"measured_when:  never\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"vel12\": {\"status\": \"unknown\", \"reason\": \"MTTR requires incident tooling history\"}}","budget_class":null,"evidence":"emission: \"unknown — needs incident-tool MTTR/MTTD history + rollback timing (org access)\"","remediation":{"quick_win":"write the top 5 runbooks (drill them), enable fast rollback (VEL-03), add the observability slices that made diagnosis slow (PERF-01).","structural":"incident-on-call excellence — accurate runbooks, ephemeral-infra-friendly rollback, self-healing where possible, every incident gets a blameless postmortem whose actions you actually fund, MTTR tracked as an SLO.","gold_standard":"MTTR < 30 min majority, runbook-based recovery, rollback automated, no incident class repeats, postmortem actions all shipped.","effort":"🔷 ~1–2 days"}},
  "PERF-01": {"id":"PERF-01","category":"PERF","name":"Observability Gaps","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The system cannot answer basic questions about its own runtime — no structured metrics (RED/USE), no distributed tracing (or tracing only in the new corner), no meaningful logging conventions, and debugging is done by SSH-ing and tailing raw output.","why":"Observability is the feedback loop of operations — \"what is the system doing right now?\" A system without it is run by flashlight. Modern practice (OpenTelemetry, metrics, logs, traces + SLOs) is a baseline; its absence forces archaeology on every incident and every performance question, and it silently blocks most modernization (you can't improve what you can't measure).","manifests":"No metrics endpoint/agent, `print`/`console.log` as the observability layer, no correlation between request and logs, no distributed tracing across services, debugging prod by `ssh` + `tail -f`, \"why is it slow\" answered by screenshots.","detection":"Instrumentation audit — is the app emitting metrics/logs/traces via a standard (OpenTelemetry/SLf4j/Prometheus)? Are logs structured (JSON), correlated (request IDs)? Is tracing present across service boundaries? Time a \"why is this slow\" question end-to-end and count how long it takes to answer with current tooling.","yellow":"Logs exist but unstructured/poorly correlated; metrics partial; tracing missing across microservices.","red":"No structured metrics at all; debugging prod requires SSH + raw log tailing; latency/errors invisible to any dashboard.","yellow_rationale":"warning — you can see something, not everything.","red_rationale":"you are operating blind — every incident is archaeology and every perf fix is a guess.","criteria":{"0":"blind operational flashlight.","1":"logs-only, no metrics/tracing","2":"partial","3":"OTel-standard full coverage"},"scope":"Instrumentation posture; audit-trail adequacy is SEC-05, error contracts API-07.","applicability":"`na_when: no runnable service surface` (library-only repo, clause-b).; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # coverage/correlation quality is runtime truth\nestimated_when: >=2 of {metrics, logs, correlation} probes computed   # clamp [1,2]\nunknown_when:   no service surface parseable\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when three-pillar probes all ran\nscope_limited:  sampled modules -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: metrics ∧ structured logs present; tracing absent\n- `1`: unstructured logging ∨ single-pillar coverage on a multi-service core\n- `3`/`0` unreachable by construction","fact_schema":"{\"perf01\": {\n  \"metrics\": {\"sdk\": \"prometheus-client\", \"endpoint\": true},\n  \"structured_logging\": true,\n  \"request_correlation\": true,\n  \"tracing\": {\"otel\": false},\n  \"dashboards_as_code\": false}}","budget_class":"fast","evidence":"basis: \"observability-inventory: metrics={sdk}; logs-structured={bool}; correlation={bool}; otel={bool}\"","remediation":{"quick_win":"add structured logging + request IDs everywhere (framework middleware), stand up a metrics endpoint with RED/U; USE basics, emit the top 6 metrics.","structural":"OpenTelemetry adoption (auto-instrumentation), tracing across services, an SLO + error-budget loop, observability as a deployment requirement (no deploy without instrumentation).","gold_standard":"Every service emits metrics/logs/traces standardly, requests are correlated end-to-end, dashboards answer latency/errors/capacity in seconds, and \"why is it slow\" never requires SSH.","effort":"🔶 ~2–4 h"}},
  "PERF-02": {"id":"PERF-02","category":"PERF","name":"Legacy Deployment Model","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The system runs on bare metal/VMs or a hand-managed fleet where servers are purchased, configured by hand (or by fragile scripts), statefully modified over time, and replaced/infra changes are a project rather than a deployment concern.","why":"The deployment model is infrastructure's era stamp. Containerization + orchestration + immutable infra is the modern baseline because it's reproducible, scalable, and auditable; the pre-container model is slow, snowflake-prone, and is where \"upgrades\" become multi-week efforts. Not every VM is legacy — but VMs configured by throwing commands at them are.","manifests":"`ssh`-configured servers, golden images that drift after setup, no containers anywhere, capacity added by buying/allocating a VM, deploys that are \"git pull on the host,\" snowflake servers named after the intern who set them up, no immutable/rebuilt concept.","detection":"Infra inventory — deployment targets and provisioning method (Terraform/cloud-init/Ansible vs. hand-run commands), containerization %, image-build pipeline for the app, drift between nominally-identical hosts, \"how would you add a 2nd instance?\" test (this answer reveals the model).","yellow":"Partial containerization/IaC; some VMs still configured by scripts; a couple of snowflakes.","red":"Bare-metal/VM with manual stateful modifications as the standard; scale = \"buy a bigger server.\"","yellow_rationale":"warning — the migration is underway but incomplete.","red_rationale":"every env change is a project and every size change is a downtime.","criteria":{"0":"hand-configured snowflakes.","1":"VMs + IaC-light","2":"partial","3":"containers + IaC"},"scope":"Deployment-model shape; release mechanics are VEL-08, IaC coverage PERF-06.","applicability":"never N/A for scored repos (something runs somewhere; absence of all modern artifacts is signal).","statusing":"measured_when:  tree enumerated                # artifact inventory decidable statically\nestimated_when: ambiguous mixed signals only   # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium\nscope_limited:  infra outside repo -> note in evidence","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: orchestrated/containerized or serverless with CI-built images\n- `2`: containerized without orchestration, CI-linked\n- `1`: VM-based with partial automation ∨ mixed model mid-migration\n- `0`: hand-run VM scripts only / no declared deploy path","fact_schema":"{\"perf02\": {\n  \"artifacts\": [{\"kind\": \"dockerfile\", \"path\": \"Dockerfile\"}, {\"kind\": \"vm-script\", \"path\": \"ops/deploy.sh\", \"smell\": \"systemctl restart\"}],\n  \"model\": \"mixed-vm-container\",\n  \"ci_builds_images\": false}}","budget_class":"fast","evidence":"evidence: \"deploy-inventory: model={model}; artifacts={list}; ci-builds-images={bool}; vm-smells={k}\"","remediation":{"quick_win":"containerize the app (it's usually the smallest step), move VM provisioning to IaC (Terraform/cloud-init), codify the laptop script.","structural":"immutable, containerized, orchestrated deployment (K8s/ECS) with IaC for everything, auto-scaling-ready, snowflakes eliminated by rebuild-from-code.","gold_standard":"Everything containerized + IaC-managed, instances are cattle (rebuildable in minutes), scale is a config change, drift impossible by construction.","effort":"🔶 ~2–4 h"}},
  "PERF-03": {"id":"PERF-03","category":"PERF","name":"Resource Waste / Leakage","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"standard","gates":[],"definition":"The system leaks or wastes resources as routine — memory leaks that force scheduled restarts, unbounded caches, connection/thread sprawl, oversized instances, or processes that degrade until reboot.","why":"Leaks are the runtime's passive decay: the system gets worse the longer it runs, and the fix (\"restart it weekly\") is a maintenance ritual, not an engineering answer. Bounded caches and clean resource handling are baseline expectations; their absence points to code that predates memory hygiene and to infrastructure tuned by folklore.","manifests":"Scheduled restarts to \"clear memory,\" unbounded in-memory caches/`HashMap` growth, connection-pool leaks, goroutine/thread sprawl, restarts-of-record in the on-call runbook, \"memory looks weird\" tickets, oversized instances rented so a leak fits.","detection":"Profiling — py-spy/`pprof`/JVM heap + GC logs/`dotnet` diagnostics over time (grab snapshots pre/post \"fixing restartus\"), memory-graph growth analysis (heap grows linearly until OOM?), cache-size inspection, connection pool metrics, restart logs correlated with memory; cloud cost analysis for instance oversizing.","yellow":"Scheduled off-peak restarts to manage memory, some unbounded caches, moderate waste.","red":"Process crashes under *standard* load due to memory leaks, or leaks that no one knows are leaks (restart-on-cron as tradition).","yellow_rationale":"warning — the manifest ritual is in place; the leak is real but managed.","red_rationale":"availability is being bought with restarts — the runtime is decaying in plain sight.","criteria":{"0":"regular crashes at standard load.","1":"leaks under spikes","2":"restart ritual in place","3":"no leak, high utilization"},"scope":"Runtime resource behavior; ORM query waste is DATA-07's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"perf03\": {\"status\": \"unknown\",\n             \"reason\": \"leakage provable only under runtime profiling\",\n             \"static_hints\": {\"unbounded_cache_sites\": 2}}}","budget_class":null,"evidence":"emission: \"unknown — needs load-sustained profiling + heap/connection snapshots (deep scan)\"","remediation":{"quick_win":"profile to find the leak(s), bound the caches (TTL + size limit), fix the top 3 resource leaks, enable heap diagnostics.","structural":"memory discipline as a code review concern, load tests that run > 24h to expose slow leaks, resource limits + monitoring (RSS trend), right-size instances to reality.","gold_standard":"No restart ritual; heap flat over weeks; caches bounded and sized deliberately; utilization reviewed; no OOM under 3–5× load.","effort":"🔷 ~1–2 days"}},
  "PERF-04": {"id":"PERF-04","category":"PERF","name":"Monolithic Scaling Bottleneck","tier":"B","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"NO","rollup":"standard","gates":[],"definition":"The system can only scale vertically — the DB or the app can't split, shard, or go horizontal, so traffic growth means bigger instances and eventually a wall, with lock/content/state preventing distribution.","why":"A single point that must get bigger is an architectural ceiling: it caps growth at the size of one machine and makes spikes a purchasing problem. Modern scale is *distribution* (horizontal + sharding + decompositions); the inability to distribute is the design signature of a pre-scale era — and of a system that has spent its \"scale budget\" (DATA-05 is the DB half).","manifests":"\"We scaled to 64 vCPU, 256 GB,\" vertical-only guidance, state in-memory that can't be shared, a DB lock/statelessness wall, sharding \"impossible because of joins,\" a single writer bottleneck, load tests that hit a wall at N instances.","detection":"Scale experiment — load test with increasing instance count (k6/Locust/artillery) and measure per-add throughput; check for horizontal levers (stateless app? read replicas? sharding? caching?). DB analysis (DATA-05), in-memory session/state audit (what would need to change to run 2 instances?), auto-scale feasibility.","yellow":"Horizontal scaling partially works (e.g., Iapplication scales, DB replica path limited, spikes absorbed vertically).","red":"Only way to grow is a bigger instance; adding instances adds nothing (stateful app or DB bottleneck); or the largest available instance is approaching.","yellow_rationale":"warning — a wall exists ahead, not yet hit.","red_rationale":"a hard ceiling on growth — the next spike is a purchase or a collapse.","criteria":{"0":"instance-size ceiling, growth ≈ new hardware.","1":"wall visible, vertical-only for spikes","2":"partially horizontal, vertical safety valve","3":"horizontally efficient"},"scope":"Scale-curve behavior; deployment model is PERF-02, autoscaling config PERF-05.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # readiness hints ≠ scaling truth either way\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"perf04\": {\"status\": \"unknown\",\n             \"reason\": \"scaling ceiling provable only under load\",\n             \"context\": {\"externalized_sessions\": true}}}","budget_class":null,"evidence":"emission: \"unknown — needs incremental-instance load test (deep scan); readiness hints as context\"","remediation":{"quick_win":"statelessness fixes (move session/key state to a distributed store), add read replicas + a cache tier to lift the DB ceiling, shard the hottest table.","structural":"the scalability roadmap — decompose the hot path (bounded contexts, API/events per DATA-02), sharding strategy, and a horizontal-efficiency load-test gate (new instance must add value).","gold_standard":"Adding instances scales throughput linearly past the previous wall; vertical spending is an exception not a norm; load tests prove horizontal efficiency.","effort":"🔷 ~1–2 days"}},
  "PERF-05": {"id":"PERF-05","category":"PERF","name":"No Auto-Scaling / Capacity Planning","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"Capacity is static and manual — no autoscaling (still \"provision for the peak\"), no capacity planning discipline, load surprises hit prod, and scaling is done by humans reacting to pages.","why":"Static capacity is a choice between wasting money (peaks provisioned always) or failing (demand exceeds fixtures). Autoscaling + telemetry-driven planning is the modern baseline; its absence means the system \"hopes\" about demand — and hope is where outages come from. Pairs with PERF-03/04; this is the *policy* while those are the *mechanics*.","manifests":"No HPA/ASG, instance counts hand-set, \"scale up\" is a runbook action, capacity reviews happen after incidents, no load forecasting, spikes trigger \"we need more servers\" tickets, employee sales events' traffic is a surprise.","detection":"Capacity-telemetry audit — autoscaling configs (HPA/ASG policy present?), utilization history (was there headroom waste?), past incident spikes vs. allocation, forecasting/load-testing cadence, \"what triggered the last 3 scale-ups?\" (human or system?).","yellow":"Some HPA/ASG; manual ceiling for critical services; capacity reviews ad hoc.","red":"No autoscaling at all, capacity is a manual sizing decision, or a peak load event caught the system flat-footed in the last 12 months.","yellow_rationale":"warning — the machinery is partial, humans still in the loop.","red_rationale":"you are one spike from an outage and one off-peak from waste.","criteria":{"0":"no scaling machinery, hand-on-dial.","1":"manual scaling with dashboards","2":"partial, manual for critical","3":"autoscaled everything"},"scope":"Scaling-policy posture; deployment model is PERF-02, live contention DATA-05.","applicability":"`na_when: PERF-02 shows serverless-only model` (scaling inherent — reason recorded). `unknown_when: no IaC/deploy manifests in repo` (managed elsewhere). Else applicable.; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # presence ≠ correct sizing under real load\nestimated_when: >=1 deploy artifact enumerated # clamp [1,2]; confidence medium when policy params visible\nunknown_when:   no infra manifests (clause: managed elsewhere)\nna_when:        serverless-only model\nclamp:          [1,2]\nconfidence:     low without policy parameters (\"presence proof only\" caveat mandatory per the catalog conventions)","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: autoscaling declared on primary services\n- `1`: static-capacity-only declarations ∨ no scaling config for a multi-instance model\n- `3`/`0` unreachable by construction","fact_schema":"{\"perf05\": {\n  \"hpa_or_asg_present\": true,\n  \"policies\": [{\"kind\": \"hpa\", \"path\": \"k8s/api-hpa.yaml\", \"min_max\": [2, 10]}],\n  \"capacity_review_artifacts\": false}}","budget_class":"fast","evidence":"basis: \"scaling-scan: {kind}@{path} min={a} max={b}; capacity-artifacts={bool} [presence-only]\"","remediation":{"quick_win":"set HPA/ASG on the top 5 workloads with sane thresholds, add utilization + headroom dashboards, run the scheduled-campaign checklist.","structural":"autoscaling everywhere + telemetry-driven capacity reviewing (monthly), load-testing against forecast demand, SLO-based scaling decisions.","gold_standard":"Autoscaling covers critical workloads; capacity changes are system-driven by policy; spikes are non-events; waste is continuously right-sized.","effort":"🔶 ~2–4 h"}},
  "PERF-06": {"id":"PERF-06","category":"PERF","name":"Missing IaC / Config Drift","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Infrastructure is not defined in code — servers/networks/load-balancers/queues are created and modified through consoles or scripts, with no reproducible declaration, so environments drift and rebuilding anything is a project.","why":"IaC is the difference between infrastructure being a *reproducible artifact* and being *an accumulation of manual acts*. Without it, nothing infra can be reproduced, upgraded, or audited cheaply (the 12-factor-adjacent \"treat servers as cattle\" baseline). Config drift is the operational symptom: nominal-identical envs that differ in invisible ways.","manifests":"Terraform/CloudFormation/Pulumi absent or < 50% coverage, infra built by clicking (console), \"how is our VPC configured?\" answered with screenshots, config changes made directly on resources with no precedent, snowflake envs, no drift detection.","detection":"IaC coverage audit — inventory resource types vs. what's declared in code (state file + code search), config-change audit trail (were changes made by CI/Terraform or by console?), drift-check runs against the declared state, rebuild-and-compare test (build env from code, diff).","yellow":"Partial IaC (core resources coded), some console drift, rebuild needs a helping hand.","red":"No IaC for most resources, environments only explainable by the person who clicked them, or a rebuild is effectively impossible.","yellow_rationale":"warning — the foundation exists, discipline is leaking.","red_rationale":"infra is memory — regeneration capacity is zero, and DR is theatrics unless this is fixed.","criteria":{"0":"no IaC, irreproducible infra.","1":"scattered IaC, console dominant","2":"partial coverage","3":"full IaC + drift gate"},"scope":"IaC coverage posture; deployment model is PERF-02, env-parity VEL-07.","applicability":"`na_when: PERF-02 shows fully serverless-managed model with zero infra surface` (reason recorded). Else applicable — including zero-IaC trees (that's score signal).; archetype+plane: `na_when archetype in {library, docs, agent-skills} && !has_data` (DATA) or `!has_deploy` (PERF) or `!has_server` (API) with exhaustive plane inventory — required rows never N/A","statusing":"measured_when:  never auto-measured            # coverage ratio is heuristic vs implied needs\nestimated_when: >=1 deploy artifact inventoried   # clamp [1,2]; confidence medium with multi-class IaC present\nunknown_when:   no deploy/config artifacts\nna_when:        applicability fired\nclamp:          [1,2]\nconfidence:     medium when both sides of the coverage join parsed cleanly\nscope_limited:  partial repo coverage -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: IaC present covering most implied classes; plan-gate optional\n- `1`: IaC absent ∨ major implied class undeclared ∨ hand-edited console-culture signals\n- `3`/`0` unreachable by construction","fact_schema":"{\"perf06\": {\n  \"iac_frameworks\": [\"terraform\"],\n  \"resource_classes_declared\": [\"db\", \"compute\", \"dns\"],\n  \"classes_implied_by_deploy\": [\"db\", \"compute\", \"cdn\"],\n  \"ci_plan_gate\": {\"present\": false},\n  \"undeclared_classes\": [\"cdn\"]}}","budget_class":"fast","evidence":"basis: \"iac-inventory: {frameworks}; declared={classes}; undeclared-implied={list}; plan-gate={bool}\"","remediation":{"quick_win":"adopt Terraform/Pulumi for the top resource types (VPC/DB/compute), add drift detection (initial run finds the gap), codify the \"documented console changes\" retroactively.","structural":"full IaC coverage with state remote + plan-diffs in CI, admin access least-privilege, rebuild-from-code as a tested path, drift = CI failure.","gold_standard":"Everything in code, changes flow through CI-plan-review, drift is zero or alerted, and rebuilding an env is an afternoon exercise.","effort":"🔶 ~2–4 h"}},
  "PERF-07": {"id":"PERF-07","category":"PERF","name":"No SLOs / Performance Budgets","tier":"C","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"PART","rollup":"standard","gates":[],"definition":"The system has no service-level objectives, no latency/availability budgets, no performance regression gates, and no load-testing baseline — \"fast enough\" means \"nobody complained loudly today.\"","why":"SLOs are how performance stops being a mood. Their absence means performance debt is invisible until users revolt, and every \"is it OK now?\" is a vibes check. Modern practice (latency budgets, error budgets, load-test baselines, perf regression gates in CI) turns performance into a verifiable property. A system without budgets can't even *see* that it's obsolete.","manifests":"No latency targets, no error-budget tracking, p95 unknown, \"it got slower\" with no baseline, no load test in CI, perf regressions discovered by user complaints, \"SPOF acceptable\" undocumented.","detection":"SLO inventory — documented latency/availability SLOs per service? Are they *measured* (dashboards alert on budget burn)? Is there a perf regression gate in CI (load test on every PR? synthetic checks)? Baseline latency chart available? Error budgets defined and traded?","yellow":"Informal latency targets for some services, no error budgets or CI gate, no perf baseline.","red":"No SLOs or budgets anywhere, no perf gate or baseline, and perf regressions reach users undetected.","yellow_rationale":"warning — performance is a feeling, not a number yet.","red_rationale":"performance decay is structurally invisible — the system quietly gets worse and nobody can say no.","criteria":{"0":"no numbers at all, drift by feeling.","1":"informal targets","2":"some services measured","3":"SLOs everywhere + gates"},"scope":"SLO/budget posture; observability plumbing is PERF-01, runtime latency truth PERF-08.","applicability":"never N/A for scored services; library-only repos → clause-b N/A.","statusing":"measured_when:  never auto-measured            # declared ≠ measured/budgeted in practice\nestimated_when: >=2 of {slo-files, alerts, ci-gate} probes computed   # clamp [1,2]\nunknown_when:   no service surface\nna_when:        applicability fired (no runnable service)\nclamp:          [1,2]\nconfidence:     medium when artifacts + wiring both seen\nscope_limited:  none typical","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: SLOs declared ∧ at least one enforcement wire (alert or CI gate)\n- `1`: no SLO artifacts ∨ declared-but-unwired only\n- `3`/`0` unreachable by construction","fact_schema":"{\"perf07\": {\n  \"slo_files\": [\"slo/api.yaml\"],\n  \"burn_rate_alerts\": false,\n  \"ci_perf_gate\": {\"present\": true, \"tool\": \"k6\", \"blocking\": false},\n  \"synthetic_checks\": false}}","budget_class":"fast","evidence":"basis: \"slo-scan: files={list}; burn-alerts={bool}; ci-gate={tool}(blocking={b}) [declared≠measured]\"","remediation":{"quick_win":"define SLOs for the top 3 services (latency p95 + availability), measure them with the metrics you added (PERF-01), add a synthetic check for the money path.","structural":"error budgets + burn alerts, a CI perf gate (load-test baseline run on PRs), latency regression reports in the deploy loop, SLO review as a ritual.","gold_standard":"Every service has an SLO, measured and burned-alerted; CI catches perf regressions; latency baselines are historical and trusted.","effort":"🔶 ~2–4 h"}},
  "PERF-08": {"id":"PERF-08","category":"PERF","name":"Runtime Waste & Startup Latency","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"The runtime itself is heavy — minutes-long cold starts, huge memory footprints at idle, no lazy initialization, heavy boot-time work in every process, or a runtime chosen for era reasons that makes every action expensive.","why":"Startup latency/footprint is a direct cost of era-technical choices: it kills autoscaling value (cold adds take too long), wastes money at idle, and makes interactive tooling sluggish. It's a *micro*symptom that compounds into *macro*costs, and it's typical of \"framework-everything\" legacy builds.","manifests":"Cold start > 60s–minutes, idle footprint > 1+ GB per worker, everything initialized at boot (JIT-heavy, DI everything, loading 400 classes), no lazy loading, containers that take too long to be useful, \"the app takes forever to restart\" on deploy.","detection":"Startup profiling — time from process start to first request served (with and without warm cache), memory snapshot at idle (RSS), profiler breakdown of startup time (what initialized? greedy scans? JIT?), container/image size and init work, comparison vs. a lean baseline.","yellow":"Cold start 30–60s, idle footprint notable, lazy init partial.","red":"Minutes-long cold starts (kills autoscaling), or huge idle footprints (bankrupt-on-scale players), or restart is so slow deploys are painful.","yellow_rationale":"warning — model cost, tolerable at low scale.","red_rationale":"the runtime tax is bigger than the code it carries.","criteria":{"0":"minute-scale cold starts blocking scaling.","1":"minutes + heavy idle","2":"moderate (30–60s)","3":"lean startup"},"scope":"Startup/runtime waste; deployment packaging is PERF-02's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"perf08\": {\"status\": \"unknown\",\n             \"reason\": \"startup cost requires instrumented runs\",\n             \"static_hints\": {\"eager_init_sites\": 9}}}","budget_class":null,"evidence":"emission: \"unknown — needs timed container start + profiler breakdown (deep scan)\"","remediation":{"quick_win":"lazy-init the greedy startup work, trim the boot-time DI/registrations, enable JVM/cache warmup layers.","structural":"runtime modernization (container-native runtimes, startup budget with a gate, deferred-cost architecture), image size budgets, \"cold start < 10s\" as an autoscaling prerequisite.","gold_standard":"Cold start < 10–15s, idle footprint proportional to need, autoscaling actually scales because instances become useful fast, zero \"startup work\" that could be lazy.","effort":"🔶 ~2–4 h"}},
  "PERF-09": {"id":"PERF-09","category":"PERF","name":"Cost Efficiency / FinOps","tier":"B","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"The cloud/infra bill is bloated — oversized instances, idle resources, orphaned/stale resources, no cost attribution per team/service, no rightsizing reviews, and cost is late-inspected (\"it's money, whatever\") rather than engineered.","why":"Waste is a *structural* signal: a codebase designed for an era before cost visibility (unused clusters, always-on dev envs, 24/7 oversized fleets) leaks money in ways money-discipline would fix. FinOps isn't cosmetic — it's a proxy for engineering discipline, and cost overruns are why modernization budgets get starved (the waste would fund the fix).","manifests":"Instances sized 4× what's needed, dev envs running 24/7, orphaned volumes/clusters, no per-team cost tags, no rightsizing review, automatic scaling absent so over-provisioned always, \"the bill went up and we shrugged.\"","detection":"Cost analytics (Cloud Cost Management, AWS Cost Explorer resource-level, KubeCost), utilization vs. spend (P95% CPU vs. size), idle-resource sweeps (untagged, stopped-rarely, last-used), FinOps practices audit (tags/attribution, budgets, reviews).","yellow":"Some waste (over-sized instances, always-on dev), attribution partial, rare reviews.","red":"No cost visibility or attribution at all, massive always-on idle waste, or the bill has grown faster than usage for multiple quarters with no one able to explain it.","yellow_rationale":"warning — money discipline is not yet engineered.","red_rationale":"unmanaged cost is a company-budget risk and the tax that starves modernization funding — the leak becomes the excuse for never fixing anything.","criteria":{"0":"invisible bill, massive waste.","1":"minimal visibility, waste growing","2":"partial attribution, some waste","3":"attributed + right-sized"},"scope":"Spend efficiency; the capacity/scaling configs that drive it are PERF-05.","applicability":null,"statusing":"measured_when:  never\nestimated_when: never                            # tag-policy greps prove nothing about spend\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"perf09\": {\"status\": \"unknown\", \"reason\": \"requires cloud-bill + utilization join\"}}","budget_class":null,"evidence":"emission: \"unknown — needs resource-level cost data + P95-utilization join (org access)\"","remediation":{"quick_win":"tag/attribution, kill the obvious idle/orphaned resources, right-size the top 10 oversized instances, set a budget alert.","structural":"FinOps cadence (monthly rightsizing + utilization review), autoscaling-for-cost (scale-to-zero for dev), cost dashboards per team/service, and a cost/request SLO.","gold_standard":"Spend is attributed, tracked vs. usage, auto-right-sized, budgets alert, and waste < 10% of bill with an explanation for the rest.","effort":"🔷 ~1–2 days"}},
  "PERF-10": {"id":"PERF-10","category":"PERF","name":"Disaster Recovery & Resiliency","tier":"D","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"There's no demonstrable disaster-recovery capability — no DR drills, no documented RTO/RPO, single-region/AZ with no plan, no cross-region data strategy, and recovery logic (if any) has never been exercised. \"Resilience\" is a hope.","why":"DR is the final verdict on infrastructure posture — it's the difference between \"we have servers\" and \"we have a business that survives a datacenter event.\" Modern platform practice treats region/AZ distribution + tested failover as a baseline for anything production-critical. A system that can't answer \"what happens if this region dies\" has inherited a pre-cloud mental model.","manifests":"Single region/AZ for everything, no RTO/RPO numbers, DR \"runbook\" that's a google doc from 2016, no failover tests ever run, backups (DATA-06) not tied to a restore plan, \"we'd figure it out\" as the DR plan.","detection":"DR audit — documented RTO/RPO? cross-region/AZ redundancy for the critical path? Failover drills (last successful full-region drill date/time)? Multi-region data strategy (async replication? snapshots?)? Test: literally ask the team to run the DR plan and time it (a drill).","yellow":"Single/limited redundancy, no drills in > 6 months, RTO/RPO undocumented-but-roughly-implied.","red":"No DR plan/doc, no drills ever, single-region single-point-of-failure for the whole system, and no cross-region data path.","yellow_rationale":"warning — you're one event from discovering the plan is fiction.","red_rationale":"a regional event is a company-ending event — no resilience exists to be modernized here.","criteria":{"0":"no DR, region event = shutdown.","1":"single-region with plan in head","2":"multi-AZ, drills rough","3":"multi-region, drilled, RTO met"},"scope":"Failover/resiliency drills; backup/restore lifecycle is DATA-06.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # IaC hints ≠ drilled capability either way\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"perf10\": {\"status\": \"unknown\",\n             \"reason\": \"DR provable only via drills and infra audit\",\n             \"context\": {\"multi_region_iac_blocks\": 0}}}","budget_class":null,"evidence":"emission: \"unknown — needs documented RTO/RPO + last successful failover drill (deep scan)\"","remediation":{"quick_win":"write the DR plan (real: recover critical path), define RTO/RPO per tier, take documented cross-region snapshots for the critical DB, run a tabletop then a real drill.","structural":"ring-fence the critical path into multi-AZ → multi-region with tested failover, async replication strategy, automated failover runbooks, drills scheduled quarterly as a non-negotiable ritual.","gold_standard":"Critical path survives a region event within RTO (drilled and proven), RTO/RPO documented, drills are boring quarterly calendar items, recovery is automated not theatrical.","effort":"🔷 ~1–2 days"}},
  "DOCS-01": {"id":"DOCS-01","category":"DOCS","name":"Missing Architectural Decision Records (ADRs)","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"There's no record of *why* the system is the way it is — no ADRs, no design docs, no decision history. Ask \"why did we choose X?\" and the answer is a memory, a Slack thread, or a shrug.","why":"Undocumented decisions are how obsolete architecture persists: nobody can change a decision they can't see, so every \"why is this like this?\" defaults to \"always has been\" and stays frozen. ADRs turn frozen architecture into revisitable choices, and their absence makes the codebase a museum no one can curate.","manifests":"No `docs/adr/`, no design doc history, decisions argued in Slack/meetings with no record, \"why is this here\" questions with no citation, PRs that make major architecture choices with no written rationale.","detection":"Documentation inventory — is there an ADR/decision doc location and process? Sample 10 consequential architecture decisions (from git history/reviews) and check each has a written rationale + alternatives (\"nd\": what would a new engineer find?); check code comments \"why\" density vs. \"what\".","yellow":"Some design docs exist, ADR convention unofficial or partial, several big decisions undocumented.","red":"No decision records anywhere; consequential choices (datastore, architecture, integration) only live in heads/historical memory.","yellow_rationale":"warning — recoverable, the trail is mostly findable.","red_rationale":"the codebase is a black box of extinct reasoning — you cannot evolve what you cannot explain.","criteria":{"0":"no decision trail exists.","1":"sparse/undocumented core","2":"partial docs","3":"ADR-covered"},"scope":"Decision-record process; doc freshness generally is DOCS-02, knowledge-exit risk DOCS-10.","applicability":"never N/A for scored repos (absence is the signal).","statusing":"measured_when:  tree enumerated                # presence/currency/fact-sample are decidable\nestimated_when: major-change classification uncertain   # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured-only row\nconfidence:     medium\nscope_limited:  none typical","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: ADR process exists ∧ current (∈ Y_DAYS) ∧ sampled majors documented\n- `2`: ADRs exist but stale; recent majors undocumented\n- `1`: scattered decision docs without process/location convention\n- `0`: no decision documentation anywhere despite sustained development history","fact_schema":"{\"docs01\": {\n  \"adr_dir\": \"docs/adr\", \"adr_count\": 14,\n  \"newest_adr_days\": 412,\n  \"major_changes_sampled\": 6, \"with_adr\": 1}}","budget_class":"fast","evidence":"evidence: \"adr-inventory: {n} ADRs at {dir}; newest {d}d; majors-with-adr {k}/{K}\"","remediation":{"quick_win":"write ADRs for the top 10 load-bearing decisions (interview the oldest engineers, mine git/past docs), establish a template + PR requirement for consequential choices.","structural":"ADR convention in the repo (ADR-NNN, status, decision, context, alternatives considered), decisions now documented at review time, an \"explain every load-bearing choice\" refactoring task.","gold_standard":"Every consequential decision has an ADR with alternatives; new decisions document as standard practice; teams can revisit a decision on evidence, not memory.","effort":"🔶 ~2–4 h"}},
  "DOCS-02": {"id":"DOCS-02","category":"DOCS","name":"Stale / Drifted Documentation","tier":"B","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"Documentation exists but is outdated — it contradicts code, describes removed features, references old commands, and the team has learned not to trust it (\"the wiki is lies\").","why":"Stale docs are worse than none: they actively mislead, waste time, and train people to skip docs entirely — which then *creates* the tribal-knowledge problem (DOCS-05). Drift is the natural state of unowned docs, and its prevalence is a sign the team stopped investing in knowledge as code changed.","manifests":"README describing commands that don't work, docs referencing `v1` endpoints, arch diagrams from a dead era, code comments contradicting behavior, docs/wiki with \"update TBD\" for months, misleading runbooks/troubleshooting.","detection":"Doc-vs-code diff — sample docs (README, setup, API docs) and verify commands/URLs/fields against reality; check \"last updated\" dates vs. code change dates for the subjects (correlation); grep docs for removed symbols (imports/endpoints flagged in analyzers). Ask a new hire: did you trust the docs?","yellow":"Some docs outdated, diluted maintenance, trust mostly intact.","red":"Docs widely contradict code — no one trusts them, setup/runbooks are known-wrong, README is \"historical artifact.\"","yellow_rationale":"warning — the rot is present but not yet terminal.","red_rationale":"documented knowledge is dead weight; all knowledge must move to heads (making DOCS-05 inevitable).","criteria":{"0":"docs are lies, trust is dead.","1":"widely stale, partly trustworthy","2":"partial staleness","3":"docs verified current"},"scope":"Freshness/drift of prose docs; ADR process is DOCS-01, docs automation DOCS-09.","applicability":null,"statusing":"measured_when:  never auto-measured            # staleness judgment over heuristics stays labeled inference\nestimated_when: >=5 doc-module pairs mapped    # clamp [1,2]; confidence medium when symbol audit joins too\nunknown_when:   no docs to correlate\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  sampled pairs -> estimated + scope-limited","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: minority of docs drifted; core setup docs current\n- `1`: majority stale ∨ dead-symbol refs in primary docs (README/setup)\n- `3`/`0` unreachable by construction","fact_schema":"{\"docs02\": {\n  \"doc_module_pairs\": 22,\n  \"stale_pairs\": 9,\n  \"dead_symbol_refs\": [{\"doc\": \"README.md\", \"symbol\": \"make bootstrap\"}],\n  \"drift_median_days\": 118}}","budget_class":"fast","evidence":"basis: \"doc-drift: {k}/{n} pairs stale (median {d}d); dead refs in {files}\"","remediation":{"quick_win":"a doc-rot sweep (delete/rewrite the worst 10), add \"last verified\" dates, a github-issues link on every doc page so inaccuracies are reportable with one click.","structural":"docs-as-code with CI verification (commands in docs execute in a test fixture — DOCS-09), ownership per doc, \"docs touched in the same PR as code\" rule.","gold_standard":"Docs match code; commands in docs are CI-verified; a doc is as trustworthy as code, and updated with it.","effort":"⚡ ≤30 min"}},
  "DOCS-03": {"id":"DOCS-03","category":"DOCS","name":"Missing Runbooks & Operational Docs","tier":"B","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"There are no runbooks — no documented incident response, no restore/rollback procedures, no \"what to do when X breaks\" — so every operational event is improvised live, at 3am, by the bravest person.","why":"Runbooks are what turn an incident from a fire into a procedure. Their absence is the operational twin of no tests: you only find out you don't have one while you're on fire. It compounds VEL-12 (MTTR), converts every outage into heroics, and burns out everyone on-call.","manifests":"No `docs/runbooks/` or ops wiki, on-call without procedures (\"just figure it out\"), restored-from-memory steps, \"the person who knows\" must be woken up, no post-incident doc updates.","detection":"Runbook inventory — list the top 10 outage/incident classes (from incident history) and check each has: detection (dashboard/alert), diagnosis (where to look), mitigation (restore steps), escalation (who/when). Test: hand a junior on-call the runbook for the top incident and observe whether they can execute it.","yellow":"Runbooks for some incident types, others improvised; runbook vs. infra drift.","red":"No runbooks at all (or runbooks so wrong they're harmful); incidents are recovered by heroics every time.","yellow_rationale":"warning — the fires you planned for are fine, the others are gamble-rated.","red_rationale":"the recurrence of incidents is structural — you will repeat every lesson, forever.","criteria":{"0":"no runbooks, heroics-only.","1":"sparse / drifting","2":"partial coverage","3":"complete + drilled"},"scope":"Runbook presence/currency; recovery outcomes are VEL-12's row.","applicability":"`na_when: no runnable service surface` (library-only). Else applicable; absence of runbooks on a service repo is score signal.","statusing":"measured_when:  tree enumerated                # presence inventory decidable\nestimated_when: topic classification uncertain # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        applicability fired\nclamp:          [1,2]                             # n/a — measured row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: runbooks cover top operational classes incl. restore ∧ current\n- `2`: partial coverage, core classes present\n- `1`: sparse runbooks, stale, missing restore/incident\n- `0`: zero operational docs on a service with deploy footprint","fact_schema":"{\"docs03\": {\n  \"runbook_dir\": \"docs/runbooks\", \"count\": 3,\n  \"topics_covered\": [\"deploy\", \"oncall\"],\n  \"restore_doc_present\": false,\n  \"newest_days\": 240}}","budget_class":"fast","evidence":"evidence: \"runbooks {dir}: {n} files; topics={list}; restore={bool}; newest {d}d\"","remediation":{"quick_win":"write runbooks for the top 5 incident classes today (postmortem-driven), make them linkable from alert dashboards, add \"runme at the first sign\" steps.","structural":"runbook-as-product (owned, tested, games rehearsed), alert→runbook binding, postmortem = runbook update, drill the top runbook quarterly.","gold_standard":"Every incident class has a current, tested runbook; on-call executes procedures not improv; incident time is dominated by execution, not discovery.","effort":"🔶 ~2–4 h"}},
  "DOCS-04": {"id":"DOCS-04","category":"DOCS","name":"No Onboarding Guide / Developer Setup Docs","tier":"B","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"There's no effective developer-onboarding documentation — no golden path for setting up, running, and contributing; new engineers learn by being told, in person, repeatedly.","why":"A codebase with no written setup path is one where knowledge is not transferable at scale (teams can't grow, turnover is expensive). It's also the *first* documentation every candidate/mentor checks — its absence colors the entire repository's reputation. (Connects directly to VEL-02/VEL-05.)","manifests":"No CONTRIBUTING/onboarding guide, setup only in a personal doc, \"ask on day 1\" lists, README that skips setup (\"just ask\"), no local-env golden path, no \"first PR\" guide.","detection":"Onboarding-doc audit — does CONTRIBUTING/GETTING_STARTED exist, is it current (commands run — tie to DOCS-02 verify), does it cover setup→run→test→contribute→deploy to local? Time a new engineer against it (already measured in VEL-05); survey \"what did setup cost you?\".","yellow":"Setup doc exists but incomplete/stale; much onboarding is still oral.","red":"No onboarding guide at all (or it's known-wrong — DOCS-02), every hire learns the setup from a human.","yellow_rationale":"warning — there's a skeleton, the muscle is word-of-mouth.","red_rationale":"team growth and knowledge transfer are structurally capped at one-person-at-a-time.","criteria":{"0":"no guide, setup is word-of-mouth.","1":"skeletal/oral-reliant","2":"drafted, partially stale","3":"golden path verified"},"scope":"Guide existence/currency; friction posture VEL-02, drift mechanics DOCS-02.","applicability":"never N/A for scored repos.","statusing":"measured_when:  tree enumerated                # presence/stage coverage decidable\nestimated_when: heading-parse uncertain        # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: guide present ∧ all five stages ∧ no undefined commands ∧ current\n- `2`: guide covers setup+run+test; gaps elsewhere\n- `1`: minimal/partial guide, stale or broken references\n- `0`: no onboarding documentation at all","fact_schema":"{\"docs04\": {\n  \"docs_present\": [\"CONTRIBUTING.md\", \"README.md#setup\"],\n  \"stages_covered\": [\"setup\", \"run\", \"test\"],\n  \"stages_missing\": [\"contribute\", \"deploy\"],\n  \"undefined_commands\": [{\"doc\": \"CONTRIBUTING.md\", \"cmd\": \"make bootstrap\"}],\n  \"last_verified_days\": 300}}","budget_class":"fast","evidence":"evidence: \"onboarding-docs {list}: stages {covered}; undefined cmds={k}; age {d}d\"","remediation":{"quick_win":"write the golden path (clone → setup → run → test → first PR) and verify every command executes, add CONTRIBUTING.md.","structural":"golden path CI-verified (fresh container proves it — DOCS-09), onboarding checklist wired into the ticket system, \"setup docs break\" = blame-the-repo not the human.","gold_standard":"A new hire takes < 2 hours to a working local env entirely from docs; the setup guide is CI-tested and always current.","effort":"⚡ ≤30 min"}},
  "DOCS-05": {"id":"DOCS-05","category":"DOCS","name":"Tribal Knowledge & Oral Tradition","tier":"D","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"A significant fraction of \"how this system actually works\" exists only in people's heads — operational quirks, historical constraints, failure lore, \"why\" explanations — with no written representation, and the most senior people are walking liabilities (and/or mobbed with questions).","why":"When knowledge exists only in heads, the codebase's REAL behavior is not inspectable — it's interpersonal. This is the human form of undocumented architecture (DOCS-01) and it's near-universal in legacy systems: every \"ask Dave\" IS a missing document. It also blocks delegation, review, and modernization scoping (you can't cross-reference what's not recorded).","manifests":"\"Let me ask X\" for routing decisions, the \"runbook of knowledge\" person, meeting notes as the only record, wiki search returns nothing, a new feature requires a listening tour, critical \"maybe it does X\" (uncertain) behaviors.","detection":"The \"departure drill\" — pick a critical module, ask \"if the primary expert left Friday, what changes Tuesday?\"; count how many \"how-does-this-work\" questions get answers *from documents* vs. *from people*; run a Q&A session with juniors and log the share of answers with no written source.","yellow":"A few critical modules are oral-only; several \"ask Dave\" dependencies.","red":"The system as a whole is maintained by oral tradition — most decisions/behaviors have no written record and the primary carriers are 1–2 people.","yellow_rationale":"warning — the tax is real but bounded.","red_rationale":"the codebase functions as a social memory — losing the carriers loses the system.","criteria":{"0":"entire system runs as social memory.","1":"core mostly oral","2":"a few oral modules","3":"written-answerable"},"scope":"Oral-tradition dependence; measurable proxies are VEL-06 (authorship) and DOCS-01 (decisions written down).","applicability":null,"statusing":"measured_when:  never\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"docs05\": {\"status\": \"unknown\", \"reason\": \"requires the departure-drill interview protocol\"}}","budget_class":null,"evidence":"emission: \"unknown — needs departure-drill interviews (see the evidence protocol in the catalog guide); related facts: VEL-06 bus factor\"","remediation":{"quick_win":"run the departure drill on the top module — write the unrecorded facts as docs/ADRs/runbooks, pair-document with the oral experts.","structural":"\"write it down or it doesn't exist\" culture (every knowledge answer → doc link), knowledge-review on critical modules, retiring the phrase \"ask X\" in favor of \"read the doc,\" interview-capture sessions for missionaries.","gold_standard":"90%+ of functional questions answerable from written sources; no module depends on a person's memory; the departure drill yields a weekend, not a collapse.","effort":"🔶 ~2–4 h"}},
  "DOCS-06": {"id":"DOCS-06","category":"DOCS","name":"Comment Debt & Self-Documenting Code Imbalance","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"Code comments are misleading, obsolete, or restate the obvious (\"increment i\"), while intent, invariants, and \"why not X\" are undocumented — OR the code is so cryptic that comments exist as apology. Either way, the code's *intent* is not readable from the code itself.","why":"Comment debt is the texture of maintenance neglect: comments that lie are worse than none (they train readers to skip them), and code that can't explain itself passes its meaning down as folklore. Modern practice is self-documenting code (clear names, small functions, explicit intent) + honest \"why\" comments only where needed. (This is the micro-level of the whole knowledge problem.)","manifests":"Comments saying `// TODO: fix this` 5 years old, comments that contradict the next line, copy-pasted comments, naming like `x2`, `doStuff`, magic numbers with no explanation, dead comment blocks, no \"why\" comments near non-obvious invariants.","detection":"Sample-based review — read 200–500 lines of each critical module: are names self-explanatory? Do comments explain \"why\" or just paraphrase \"what\"? Grep for TODO/FIXME/XXX/HACK and check age (git blames their introduction), misleading-comment ratio (does comment match behavior?), and naming quality (identifier length/verb-noun check).","yellow":"TODO-rot present, some cryptic naming, some redundant/paraphrase comments.","red":"Code is cryptic and comments are required to decode it — or comments actively contradict the code, and the standard is \"trust the comment? trust the code? flip a coin.\"","yellow_rationale":"warning — texture is degrading, readability is paying.","red_rationale":"the code cannot be read as truth — it must be decoded, which is why fixes are always risky.","criteria":{"0":"comments are the only decoder and/or they lie.","1":"cryptic + misleading mix","2":"TODOs + paraphrase rot","3":"self-documenting, honest comments"},"scope":"Comment/naming hygiene; dead code those comments often mark is ARCH-04.","applicability":"never N/A for scored repos.","statusing":"measured_when:  never auto-measured            # imbalance judgment is inferential\nestimated_when: >=1 probe class ran            # clamp [1,2]; confidence medium when blame ages complete\nunknown_when:   tree unparseable\nna_when:        never\nclamp:          [1,2]\nconfidence:     medium\nscope_limited:  blame unavailable -> counts-only, confidence low","score_mapping":"Y/R values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: markers present, minority aged, density not pathological in core\n- `1`: aged-marker pile-up on core paths ∨ near-zero comment ratio ∧ opaque naming signals in core\n- `3`/`0` unreachable by construction","fact_schema":"{\"docs06\": {\n  \"markers_total\": 214,\n  \"aged_markers_over_year\": 88,\n  \"comment_ratio_core\": 0.04,\n  \"worst_files\": [{\"file\": \"core/pricing.py\", \"todos\": 23}]}}","budget_class":"fast","evidence":"basis: \"comment-debt: {n} TODO-class ({a} >1y); core comment-ratio {p}%; worst {file}\"","remediation":{"quick_win":"kill the top 20 misleading/obsolete comments (fix or delete), resolve/add justification for the oldest TODOs, rename the worst identifiers.","structural":"self-documenting-code standards in review (naming, small functions), \"why\" comments for invariants, comment lint (TODO age alarm), and a \"readability\" gate on the module most touched on-call.","gold_standard":"Code reads like prose (names carry intent), comments exist only for true \"why\", TODO-rot is gone, and a reader can trust line 1 to mean line 1.","effort":"🔶 ~2–4 h"}},
  "DOCS-07": {"id":"DOCS-07","category":"DOCS","name":"Missing API Documentation","tier":"A","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The API has no consumer-facing documentation — no OpenAPI/spec (from API-01), no reference docs, no examples, no guides — so consumers (internal or external) learn by reading code or probing endpoints.","why":"Undocumented APIs are un-sellable, un-boardable, and un-debuggable. For any multi-team or external surface, docs are the interface; their absence forces every consumer to reverse-engineer, producing integration bugs and support load. (Related to but distinct from API-01's *contract*: docs of a contract is what consumers actually read.)","manifests":"No developer portal/docs page, no usage examples, no auth/endpoint reference, \"check the code, the naming's obvious,\" docs that only exist in a colleague's head, support tickets answering \"how do I use X endpoint.\"","detection":"Docs inventory — a developer-facing doc/test for each endpoint exists (examples, params, responses)? Can a stranger integrate without asking a human? Check tooling (Swagger UI/ReDoc/portal generation tied to the contract), support-ticket analysis for \"how do I use /\" volume.","yellow":"Some endpoints documented, others skeletal; docs partial/mixed-quality.","red":"No consumer-facing API documentation at all, or it's so stale it misleads (DOCS-02 applies), consumers reverse-engineer everything.","yellow_rationale":"warning — documentation exists, coverage is patchy.","red_rationale":"what isn't documented isn't accessible — the API is effectively a private contract wearing public clothes.","criteria":{"0":"no docs; consumers reverse-engineer.","1":"sparse/misleading","2":"partial","3":"current generated docs"},"scope":"Developer-facing API documentation; the contract itself is API-01's row.","applicability":"`na_when: no HTTP/API surface` (API-01 clause-b).","statusing":"measured_when:  route set enumerated           # presence + coverage share are facts\nestimated_when: annotation-parse partial       # clamp [1,2], confidence low\nunknown_when:   routes unparseable\nna_when:        applicability fired\nclamp:          [1,2]                             # n/a — measured row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: spec ∧ hosted/generated reference ∧ high endpoint-doc coverage\n- `2`: spec present, generation/hosting missing or coverage middling\n- `1`: sparse annotations, no spec\n- `0`: zero API documentation surface of any kind","fact_schema":"{\"docs07\": {\n  \"spec_present\": true, \"ui_hosting\": false,\n  \"generator_config\": [\"typedoc\"],\n  \"endpoint_doc_coverage_pct\": 0.38}}","budget_class":"fast","evidence":"evidence: \"api-docs: spec={bool}; ui/gen={list}; endpoint coverage {p}%\"","remediation":{"quick_win":"publish the OpenAPI/spec with a generated reference (Swagger UI/Redoc), add examples for the top 10 endpoints, write an auth quickstart.","structural":"docs generated from contract in CI (spec is source, docs are output — DOCS-09), consumer guides for the top use cases, updated with each contract change, \"docs in same PR\" rule.","gold_standard":"Every endpoint has a current, generated reference with examples; a stranger self-serves; docs update with the contract in the same change.","effort":"🔶 ~2–4 h"}},
  "DOCS-08": {"id":"DOCS-08","category":"DOCS","name":"No Release Communication / Changelog","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"There's no changelog, no release notes, no migration guides, no announcement channel for API/behavior changes — consumers and users discover breaking changes by finding them the hard way.","why":"Release communication is the social layer of an API: even perfect versioning (API-02) is useless if nobody learns about it. In a legacy system, this absence is typical of \"release day = nobody's informed\" — and it's the mechanism by which every breaking change becomes a support incident. (Companion to API-08's consumer blindness.)","manifests":"No CHANGELOG.md, no release notes, repos without semantic-release, breaking changes announced \"via the grapevine,\" migration guides written after the damage, rebrands/deprecations silent.","detection":"Release-communication audit — changelog exists + auto-generated? Release notes published to consumers/users (email/blog/portal)? Breaking changes get migration guides (docs link in the breaking commit)? Interview consumers: \"how did you hear about the last breaking change?\" — if the answer is \"we broke,\" it's absent.","yellow":"Changelog exists but irregular/manual, migration notes sometimes written, announcements ad hoc.","red":"No changelog or release notes at all, breaking changes ship unannounced, consumers/users learn from failures.","yellow_rationale":"warning — the channel exists, the discipline is thin.","red_rationale":"the product's change contract with its ecosystem is void — every change is a surprise tax.","criteria":{"0":"no communication, change-by-surprise.","1":"notes absent, changes announced late","2":"changelog manual/irregular","3":"automated notes + guides"},"scope":"Release communication surface; version discipline mechanics are API-02.","applicability":"never N/A for scored repos.","statusing":"measured_when:  tree enumerated                # changelog/release facts decidable\nestimated_when: API unavailable -> file facts only   # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured row\nconfidence:     medium with full API data\nscope_limited:  private consumers unreachable -> noted","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: maintained changelog ∧ substantive notes on releases ∧ breaking documented\n- `2`: changelog present but lagging or thin notes\n- `1`: sporadic notes; breaking changes undocumented\n- `0`: no changelog ∧ empty release notes across history","fact_schema":"{\"docs08\": {\n  \"changelog_present\": true, \"changelog_current\": false,\n  \"releases_sampled\": 12, \"with_notes_pct\": 0.42,\n  \"breaking_with_migration_guide\": {\"total_breaking\": 3, \"documented\": 1},\n  \"release_tooling\": null}}","budget_class":"api-budgeted","evidence":"evidence: \"release-comms: changelog={bool}(current={bool}); notes {p}% of {n}; breaking-documented {k}/{t}\"","remediation":{"quick_win":"adopt a CHANGELOG process (Keep-a-Changelog, auto-generated from commits/PRs), publish release notes for the top consumers, write migration guides for open breaking changes (backfill).","structural":"semantic-release automation (version + changelog + notes automated), a release-communication channel (port status page + email), \"breaking = migration guide in same MR\" rule.","gold_standard":"Every release has automated notes; every breaking change has a migration guide published with the change; consumers hear first, break never (silently).","effort":"🔶 ~2–4 h"}},
  "DOCS-09": {"id":"DOCS-09","category":"DOCS","name":"Docs-as-Code & Automation","tier":"A","default_status":"estimated","effort":"🔷 ~1–2 days","v1":"YES","rollup":"standard","gates":[],"definition":"Documentation is not treated as code — no docs CI, no generated-from-contract docs, no docs freshness checks, no \"docs in CI\" — so every doc rots (DOCS-02) and the only guarantee is entropy wins.","why":"Docs-as-code is the engineering answer to doc rot: generate what can be generated (API specs → reference), verify what can be verified (commands in docs run in CI), fail on fresh rot (staleness checks). Its absence means the knowledge layer depends on human discipline forever — and that's how it died in the first place.","manifests":"Docs stored without CI/test, `~/docs` or personal folders, OpenAPI spec unused for generation, no linting of docs, no doc-freshness verification, \"regenerate docs\" not part of release, docs repo excluded from quality gates.","detection":"Docs-pipeline audit — is there a docs CI (build, lint, links)? Are API docs generated from contract in CI (spec → reference)? Are runbook commands verified/tests? Is doc freshness checked (staleness gates, last-verified markers)? Can a doc change break the build (intentional)?","yellow":"Some generated docs (spec → reference), no docs CI pipeline, freshness unguarded.","red":"All docs hand-maintained, nothing generated/verified/tested, no docs CI — docs will rot and the team knows it.","yellow_rationale":"warning — the artifacts exist, the machine does not.","red_rationale":"the knowledge layer has no immune system — DOCS-02 is guaranteed, not accidental.","criteria":{"0":"unreinforced hand-maintenance.","1":"hand-maintained, verified sporadically","2":"partial generation, no pipeline","3":"docs CI + generation"},"scope":"Docs pipeline automation; the content quality it protects is DOCS-02/03/04/07.","applicability":"never N/A for scored repos.","statusing":"measured_when:  tree enumerated               # step inventory decidable\nestimated_when: CI parse partial              # clamp [1,2], confidence low\nunknown_when:   tree not enumerable\nna_when:        never\nclamp:          [1,2]                             # n/a — measured row\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: build ∧ lint/link ∧ generation wired ∧ staleness gate present\n- `2`: automation present, gaps in gates/checkers\n- `1`: single advisory-only step\n- `0`: zero docs automation","fact_schema":"{\"docs09\": {\n  \"doc_ci_steps\": [{\"kind\": \"build\", \"tool\": \"mkdocs\", \"blocking\": false}],\n  \"link_checker\": true, \"api_gen_wired\": true,\n  \"staleness_gate\": false}}","budget_class":"fast","evidence":"evidence: \"docs-ci: steps={kinds}; lint={bool}; links={bool}; gen-wired={bool}; stale-gate={bool}\"","remediation":{"quick_win":"wire docs generation into CI (spec → reference), add links/lint checks for markdown, CI-verify the top setup commands (fresh container).","structural":"full docs-as-code — generate what's generatable, verify what's actionable, staleness gates (docs touch-required on code change), docs failures block merge like code failures.","gold_standard":"Docs build like code, generate from truth, verify their own commands, and fail CI on rot — the knowledge layer is as maintained as the code.","effort":"🔷 ~1–2 days"}},
  "DOCS-10": {"id":"DOCS-10","category":"DOCS","name":"Knowledge Exit & Documentation Ownership","tier":"D","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"Documentation has no owner and no process for the \"knowledge exit\" (when people leave, what they knew leaves with them) — no docs champion, no offboarding knowledge capture, no doc ownership map, and institutional memory leaves in the same car as the departing engineer.","why":"Knowledge continuity is how a system survives turnover; its absence is why \"that person left and now we're stuck\" is the most common legacy story. Documentation without ownership rots (root of DOCS-02); knowledge without an offboarding ritual is lost at clock-out pace. This is the *management* of the whole category.","manifests":"No docs owner/maintainer role, no offboarding checklist capturing knowledge, \"X left and took the runbook in his head,\" unowned wiki sprawl, no documentation-review cadence, docs written by whoever had PTO guilt.","detection":"Ownership audit — who maintains each doc/module's knowledge? Offboarding process: does the checklist include knowledge capture (walkthroughs, runbooks, ADRs, ticket handover)? Post-departure incidents attributable to knowledge loss? Doc-new-content rate vs. doc-decay rate (is the library growing or rotting?).","yellow":"Some docs owned, offboarding capture partial, a couple of knowledge-loss incidents.","red":"No ownership, no offboarding capture, and knowledge leaves visibly (recent incidents post-departure).","yellow_rationale":"warning — the drain is real and mostly unmanaged.","red_rationale":"the system's memory is intentionally unbounded-liability — every exit is a reset.","criteria":{"0":"unowned, knowledge exits with each departure.","1":"sparse ownership, capture ad hoc","2":"partial ownership/capture","3":"owned + capture ritual"},"scope":"Knowledge-exit process; measurable proxies are VEL-06 (concentration) and DOCS-01 (written decisions).","applicability":null,"statusing":"measured_when:  never\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"docs10\": {\"status\": \"unknown\", \"reason\": \"requires offboarding-process and ownership audit\"}}","budget_class":null,"evidence":"emission: \"unknown — needs ownership/offboarding process audit; related facts: VEL-06, CODEOWNERS coverage\"","remediation":{"quick_win":"name an owner/champion for the docs, run an offboarding knowledge-capture ritual for the top knowledge holders (scripted walkthroughs into docs/ADRs), capture the last 3 departures' gaps retroactively.","structural":"ownership map (every doc/module has a maintainer), offboarding checklist enforced by HR tools, doc health reviews (growth vs. decay) quarterly, documentation as a funded line item not a PTO activity.","gold_standard":"Every knowledge area has an owner; offboarding reliably captures knowledge; departures are 1-day disruptions; the doc library grows while decaying nothing.","effort":"🔷 ~1–2 days"}},
  "FE-01": {"id":"FE-01","category":"FE","name":"UI Framework / Stack EOL & Deprecation","tier":"A","default_status":"estimated","effort":"⚡ ≤30 min","v1":"YES","rollup":"standard","gates":[],"definition":"The client is built on a framework or toolchain that is EOL, in maintenance mode, or legacy-generational (AngularJS, jQuery-era SPA, Flash/Flex, React 15, Vue 2 pre-EOL) — with no documented migration path and shrinking community/tooling support.","why":"The frontend is the user's daily experience; a dead framework means security patches stop (XSS classes stay open), hiring collapses, the ecosystem's gear (component libs, tooling, AI assistance) stops fitting, and every new feature is built in an abandoned era. (This is ECOS-01/08, aimed at the client.)","manifests":"`package.json` framework version, EOL trackers (endoflife for Angular/Vue/React), framework support pages, bundle of legacy polyfills, \"don't upgrade\" tickets, no component lib compatible with the stack, job postings for the stack drying up.","detection":"Framework lifecycle audit — version matrix vs. EOL calendar (endoflife.date), tooling compatibility check (does the current build toolchain support the framework?), community signals (release cadence, Stack Overflow trend), staffing check (how long to hire for this stack).","yellow":"Framework in maintenance mode / one generation back, with an upgrade path underway.","red":"Framework EOL (or vendor-end-of-life) with no migration in progress, or security patches unavailable.","yellow_rationale":"warning — the window to leave is still open, cost is rising.","red_rationale":"unfixable client vulnerabilities + a frozen evolution path — the client is now a terminal.","criteria":{"0":"EOL with no path.","1":"EOL in isolated surface","2":"maintenance mode with plan","3":"supported/current"},"scope":"UI framework lifecycle; runtime/language EOL is ECOS-01's row.","applicability":"**category gate:** `na_when: no user-facing client detected` (C1/OQ5 — entire FE category skipped). Per-row: never additionally N/A within an active FE category.","statusing":"measured_when:  frameworks.len > 0 and lookup succeeded\nestimated_when: lookup partial / niche framework unmapped   # clamp [1,2], confidence low\nunknown_when:   client detected but no framework identifiable (custom stack)\nna_when:        category gate fired\nclamp:          [1,2]\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3.\n\n- `3`: all frameworks current ∧ toolchain compatible\n- `2`: maintenance-mode framework with migration evidence\n- `1`: EOL framework confined to non-core views ∨ toolchain mismatch without EOL\n- `0`: EOL/retired framework carrying core UI","fact_schema":"{\"fe01\": {\n  \"frameworks\": [{\"name\": \"react\", \"version\": \"16.8\", \"support_status\": \"maintenance\", \"eol_date\": null}],\n  \"toolchain_compat\": {\"bundler\": \"webpack4\", \"supports_framework\": false}}}","budget_class":"api-budgeted","evidence":"evidence: \"fe-lifecycle: react 16.8 {status}; toolchain compat={bool}\"","remediation":{"quick_win":"a written migration brief (target framework, timeline, budget), framework-but-the-patterns upgrade where feasible, freeze risky features.","structural":"incremental migration (module-shell pattern, route-by-route strangler), contract with the backend (API-01) kept stable during migration, the client on a support-meeting framework within two quarters.","gold_standard":"Framework is current-to-recent, security-supported, ecosystems integrable; migration is an ordinary roadmap item if ever needed.","effort":"⚡ ≤30 min"}},
  "FE-02": {"id":"FE-02","category":"FE","name":"Bundle Size & Load Performance","tier":"A","default_status":"measured","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"The client ships fat bundles — megabytes of JS/CSS, no code splitting, render-blocking churn, heavy images — so load/LCP/interaction metrics are slow, mobile suffers, and the \"page load\" is a growing tax on conversion.","why":"Client performance is a user-decision metric (half the abandonments on load-time). Legacy clients universally carry unforked bundles (everything loaded on every route), absence of code-splitting, no measurement, and an app that \"works fine on the office MacBook.\" It's also the cheapest modernization win available.","manifests":"Bundle analysis (webpack-bundle-analyzer/rollup), Lighthouse scores (< 50 perf), no code-splitting (one giant chunk), no caching strategy, no CDN, images unoptimized, page loads every asset on first paint, no Core Web Vitals tracking.","detection":"Performance measurement — Lighthouse/PageSpeed (lab), Core Web Vitals field data (CrUX/RUM), bundle analyzer output (total + per-route), network waterfall inspection (blocking, duplication), mobile-device throttled test vs. target.","yellow":"Bundle 500 KB–1.5 MB initial, LCP 3–4s on mobile, splitting partial.","red":"> 1.5 MB initial, LCP > 4s, no code splitting, no measurement at all — \"the app is slow\" shows up in churn/refunds.","yellow_rationale":"warning — exceeds budgets, users already paying.","red_rationale":"the client is its own growth blocker; users feel it every session.","criteria":{"0":"massively overweight, uncounted, users suffering.","1":"> 1 MB, no split","2":"over budget, splitting partial","3":"budgets + fast"},"scope":"Load performance; framework currency is FE-01's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never                            # budget-config presence proves intent, not bytes\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"fe02\": {\"status\": \"unknown\",\n           \"reason\": \"bundle/load truth needs a built, rendered client\",\n           \"static_hints\": {\"size_limit_configured\": true}}}","budget_class":null,"evidence":"emission: \"unknown — needs Lighthouse/CWV on a built client (deep scan); budget config present={bool}\"","remediation":{"quick_win":"code-split the routes, defer non-critical vendors, compress/optimize images, set a bundle budget in CI (regression gate), measure with Lighthouse in CI.","structural":"a performance budget (bytes + core vitals) enforced, RUM for field data, on-demand vs. bundled loading for heavy features, service-worker caching.","gold_standard":"Initial JS < 300 KB, LCP < 2.5s on mobile field-data, code-split by route, budget-enforced in CI, vitals tracked on a dashboard.","effort":"🔶 ~2–4 h"}},
  "FE-03": {"id":"FE-03","category":"FE","name":"Accessibility Deficits","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"NO","rollup":"standard","gates":[],"definition":"The client fails accessibility basics — no semantic markup, missing ARIA/labels, keyboard-unusable controls, contrast failures, no focus management, no a11y testing — and there's no accessibility standard or enforcement.","why":"Accessibility is both a legal liability (ADA/WCAG/EN 301 549 — suits are real) and a *product reach* issue (roughly a fifth of users). Its absence marks a client built before accessibility became a baseline, and it's a rare case where the \"modernization\" is strictly additive — a cheap, high-return fix. Also a regulatory gate: WCAG 2.1 AA is legally required in many markets.","manifests":"Lighthouse a11y < 70, div-spam instead of semantic elements, unlabeled inputs, modals without focus traps/dismiss, color-only status indicators, no keyboard order, no a11y lint or automated checks, screen-reader users unreachable.","detection":"Automated a11y scan (axe-core, Lighthouse, WAVE, linting), manual keyboard walkthrough (tab through a critical flow), screen-reader smoke (VoiceOver/NVDA on core journeys), contrast checks (axe color-contrast), check for automated a11y checks in CI.","yellow":"Score 70–90, some serious violations on secondary flows, no a11y gate.","red":"Score < 70, critical flows keyboard-unusable, or no automated a11y checking at all with visible violations.","yellow_rationale":"warning — functional but non-compliant risk remains.","red_rationale":"legal exposure + an unusable-product class is excluded — dual liability.","criteria":{"0":"unusable-by-keyboard, no checks, legal exposure.","1":"< 70 on part of app","2":"70–90, some violations","3":"≥ 95, enforced"},"scope":"Rendered accessibility; UI stack currency is FE-01.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"fe03\": {\"status\": \"unknown\",\n           \"reason\": \"accessibility violations observable only on rendered DOM\",\n           \"static_hints\": {\"a11y_lint_configured\": false}}}","budget_class":null,"evidence":"emission: \"unknown — needs axe-core scan + keyboard walkthrough on rendered flows (deep scan)\"","remediation":{"quick_win":"run axe, fix the top serious/critical violations (labels, semantics, focus, contrast), add a11y lint to CI.","structural":"a11y standards + automated gate (axe in CI failing new violations), keyboard/contrast reviews, component-library a11y defaults, screen-reader smoke tests on core journeys.","gold_standard":"a11y score ≥ 95, zero critical/serious violations, keyboard + screen-reader flows pass in review, a11y gate enforced in CI.","effort":"🔶 ~2–4 h"}},
  "FE-04": {"id":"FE-04","category":"FE","name":"Browser / Platform Support Drift","tier":"B","default_status":"measured","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The client targets a stale or wrong platform matrix — still promising IE11/old browsers, or alternatively, no declared support matrix at all, breaking on current browsers, no responsive layouts, no desktop/mobile parity, and platform support is a rumor.","why":"The platform matrix is the client's forward-compatibility contract. Supporting dead browsers forces stagnation (no modern CSS/JS); supporting nothing means users break in the real world. Modern practice: a known, current matrix (browserlist) + responsive across breakpoints + feature detection. Its absence marks a client frozen at the era it was built.","manifests":"Hardcoded IE11/legacy promises in docs, polyfill sprawl for long-dead browsers, no browserlist file, fixed-width layouts (desktop-only), no responsive breakpoints, \"works on Chrome only\" acceptance, no device testing, transdyn failures on exports.","detection":"Support-matrix audit — browserlist/browsers config present + current? Responsive implementation (breakpoints, mobile test)? Device/browser test coverage in QA? Browser usage analytics (what do real users use) vs. what's tested? Try the app on a current mobile browser + a recent-only build.","yellow":"Stale matrix or partial responsive; polyfill cruft; mobile tested sporadically.","red":"Desktop-only/fixed-width (or a matrix that excludes where users are), or no matrix at all with recurring \"breaks in my browser\" reports.","yellow_rationale":"warning — friction, real-user breakage ticking up.","red_rationale":"the client isn't built for the present — it's built for its own archive. Users are being told to upgrade to the app's remembered world.","criteria":{"0":"desktop-only museum or no matrix with real breakage.","1":"broken on current/mobile for some flows","2":"stale or partial responsive","3":"current + responsive"},"scope":"Platform-support posture; framework EOL is FE-01, offline/mobile depth is FE-08.","applicability":"FE category gate.","statusing":"measured_when:  never auto-measured            # support-judgment over targets is inferential\nestimated_when: >=1 probe class computed       # clamp [1,2]; confidence medium with browserslist parsed\nunknown_when:   client detected but no support surface found at all\nna_when:        category gate fired\nclamp:          [1,2]\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: targets slightly behind current norm, obsolete polyfills absent\n- `1`: dead-platform targets ∨ obsolete polyfill stack ∨ no responsive implementation\n- `3`/`0` unreachable by construction","fact_schema":"{\"fe04\": {\n  \"browserslist_present\": true,\n  \"oldest_target\": \"ie 11\", \"target_age_years\": 9,\n  \"obsolete_polyfills\": [\"core-js@2\"],\n  \"responsive_markers\": true}}","budget_class":"fast","evidence":"basis: \"support-drift: oldest target {t} ({a}y); polyfills={list}; responsive={bool}\"","remediation":{"quick_win":"declare the matrix + enforce browserlist, add a responsive bootstrap for the top user journey, test mobile on the core path.","structural":"responsive-first design standards, device/browser QA in the pipeline, analytics-informed matrix reviews twice a year, cut the obsolete matrix (drop IE11 promises, shed polyfills).","gold_standard":"Declared + enforced current matrix, responsive across breakpoints, browser/device tested in QA, matrix reviewed against real usage.","effort":"🔶 ~2–4 h"}},
  "FE-05": {"id":"FE-05","category":"FE","name":"Client-Side Architecture Debt","tier":"B","default_status":"estimated","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The client's internal structure is legacy-modal — global state sprawl (a dozen stores, mutable globals), prop-drilling and god-components, anemic architecture where UI logic invents the domain, no component model/testable seams, and every feature is a new global.","why":"Client architecture debt is ARCH on the frontend: the app grows by global mutation, state is untestable, components are untestable, and refactoring the client (a natural prelude to any modernization) is met with \"too risky to touch.\" It's the reason FE-01/02 migrations stall.","manifests":"Global state object/store sprawl, giant god-components (1000+ line components), prop drilling through 6 layers, logic-in-render (`render` computing things), no separation of data/view/state, hundreds of `useEffect`/effects, state-that-can't-be-test, no component architecture.","detection":"Component/graph analysis — component LOC distribution (god-components), state-management inventory (global stores, context providers, mutations outside stores), testability experiment (can you test a component in isolation? component testing coverage — from TEST-01 by component), hooks/effects density, data-flow tracing for a nontrivial feature.","yellow":"Some god-components, 1–3 global stores, prop drilling in places; light component tests.","red":"5+ unmanaged globals, 2,000-line components as normal, no component tests, unmappable data flow — \"the frontend can't be reasoned about.\"","yellow_rationale":"warning — still navigable, but structure is degrading.","red_rationale":"the client has no architecture worth modernizing incrementally — it's one shot glass of god-components.","criteria":{"0":"unroutable god component sprawl.","1":"a few unmanageables","2":"some globals/god-components","3":"clean architecture + tests"},"scope":"Client-side structure; server-side typing debt is ARCH-11's row.","applicability":"FE category gate.","statusing":"measured_when:  never auto-measured            # architecture-debt judgment is inferential\nestimated_when: >=2 of {components, stores, isolation} probes ran   # clamp [1,2]\nunknown_when:   no parseable client source\nna_when:        category gate fired\nclamp:          [1,2]\nconfidence:     medium on full framework support\nscope_limited:  multi-app monorepo -> sampled + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: distributions healthy-ish; some sprawl outside core views\n- `1`: god-components on core flows ∨ global-store sprawl ∧ outside-mutation density high\n- `3`/`0` unreachable by construction","fact_schema":"{\"fe05\": {\n  \"components\": 214, \"loc_p95\": 640, \"god_components\": 7,\n  \"global_stores\": 4, \"outside_mutations\": 31,\n  \"isolation_proxy_pct\": 0.44}}","budget_class":"slow-dissolvable","evidence":"basis: \"client-arch {n} components: p95 {l} LOC, gods={g}; stores={s}, outside-mutations={m}\"","remediation":{"quick_win":"mark the top 3 god-components, extract their clearest slice with a test, introduce a singular state pattern with actions.","structural":"a deliberately small client architecture (one store, typed, actions-only), component decomposition by responsibility, testable seams with a component test budget, codegen for new screens (VEL-11-style).","gold_standard":"God-components ≤ modern norms, single main state path, components testable in isolation with coverage, \"touch one page breaks another\" is a historical anecdote.","effort":"🔶 ~2–4 h"}},
  "FE-06": {"id":"FE-06","category":"FE","name":"Design System / UI Consistency Drift","tier":"C","default_status":"unknown","effort":"🔶 ~2–4 h","v1":"YES","rollup":"standard","gates":[],"definition":"The client has no (effective) design system — every screen hand-styles controls, colors/typography/spacing vary by feature, duplicated component implementations, no shared tokens — so \"just another screen\" always implies custom styling and visual drift.","why":"A design system is the client's shared language; without it, the UI is a \"many separate clients story,\" accessible-ish by accident, and each feature pays a full styling tax. Its absence signals a client that grew by addition before design-systems discipline — a marker of the same era as FE-01's framework.","manifests":"Duplicated button/input/modal implementations, hardcoded color hexes scattered, no design tokens, no component library (or an abandoned one), docs/wireframes vs. shipped UI mismatch, \"which button should we use? build one.\"","detection":"Duplication audit — grep for repeated styles/colors/components, count component implementations per UI element, check design tokens (CSS variables/theme) adoption %, Figma/DS link usage, a \"time to clone a button\" benchmark, visual consistency audit on a few screens.","yellow":"2–3 implementations of primitives, some tokens, ad hoc styles in places.","red":"No design system, 5+ ways to render a button, zero tokens — every feature re-invents the UI.","yellow_rationale":"warning — inconsistency is compounding feature cost.","red_rationale":"the client has no shared foundation — velocity and consistency are both structural losers.","criteria":{"0":"no shared foundation, reinvented per screen.","1":"duplicates common","2":"partial library","3":"system + tokens"},"scope":"UI consistency posture; client architecture is FE-05.","applicability":"FE category gate.","statusing":"measured_when:  never auto-measured            # consistency drift is a judgment over proxies\nestimated_when: >=2 of {tokens, hardcodes, duplicates} probes ran   # clamp [1,2]\nunknown_when:   no styles parseable\nna_when:        category gate fired\nclamp:          [1,2]\nconfidence:     medium when token surface parsed cleanly\nscope_limited:  sampled dirs -> estimated + scope-limited","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: token system present, adoption middling, few duplicate primitives\n- `1`: no tokens ∨ heavy hardcoded-value density ∨ multiple core primitives duplicated\n- `3`/`0` unreachable by construction","fact_schema":"{\"fe06\": {\n  \"token_files\": [\"theme/tokens.css\"], \"hardcoded_color_sites\": 412,\n  \"token_adoption_pct\": 0.31,\n  \"primitive_duplicates\": {\"button\": 5, \"modal\": 3}}}","budget_class":"fast","evidence":"basis: \"ui-consistency: adoption {p}%; hardcoded colors {n}; button impls={k}\"","remediation":{"quick_win":"build a token layer (design tokens → styled primitives), consolidate the top 2 duplicate controls, adopt one primitive set for new work.","structural":"a small living component library (owned, versioned), tokens adopted across screens, \"no new hand-rolled primitive\" rule, design ↔ engineering parity checks.","gold_standard":"One primitive set, tokens everywhere, new screens composed not styled, visual parity across the app by construction.","effort":"🔶 ~2–4 h"}},
  "FE-07": {"id":"FE-07","category":"FE","name":"Internationalization / Localization Debt","tier":"A","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"YES","rollup":"standard","gates":[],"definition":"The client either hardcodes one language with no i18n framework, or has i18n but a truncated practical reality — tokens only for headers, plurals/grammar wrong, right-to-left unhandled, dates/numbers sorted in English, timezone assumptions — so the product can't actually address the markets its distribution claims.","why":"i18n is an era marker as much as a feature: modern clients are locale-aware from the first screen. A hardcoded, English-assuming client was built when \"one market, one language\" was the product's horizon — a horizon that no longer matches a globalizing distribution. It also compounds every other FE debt (a full a11y pass on one locale has to be repeated for each).","manifests":"String literals in components, no i18n library / no extraction pipeline, no locale switch, RTL layouts broken or text truncated, hardcoded date/currency formats, English-first sort/case logic, \"It works in English\" as the QA bar, translations owned by nobody in the repo.","detection":"Source audit — hardcoded-string density in UI components, i18n framework/lib + extraction pipeline present?, locale switching works + RTL check, plural/keyword (ICU) correctness sample, date/number/timezone handling test, translation-file completeness per supported market.","yellow":"i18n framework exists, some locales work, but plurals/RTL/formatting are shims and token coverage is partial.","red":"No i18n at all (or English-only hardcode) and the market reality is multilingual; or claimed markets ship with broken RTL/plural/formatting.","yellow_rationale":"the rails exist; the train is half-stocked — expanding = broken UX in the half that's fake.","red_rationale":"distribution and product reality have separated — the client is a single-locale artifact in a multi-market world.","criteria":{"0":"hardcoded single-locale, markets claiming it are fiction.","1":"English-only core journeys, one tokenized surface","2":"framework + partial locales, shims remain","3":"full i18n, per-locale fidelity, RTL ok"},"scope":"Localization posture; platform-support drift is FE-04.","applicability":"FE category gate. Within active FE: never N/A (absence of i18n machinery is the signal).","statusing":"measured_when:  never auto-measured            # debt judgment over density is inferential\nestimated_when: >=2 of {density, lib, locales} probes ran   # clamp [1,2]\nunknown_when:   no parseable UI surface\nna_when:        category gate fired\nclamp:          [1,2]\nconfidence:     medium","score_mapping":"Criteria/Y-values: see §3. Estimated ⇒ score ∈ {1,2}:\n\n- `2`: i18n machinery present with partial coverage\n- `1`: near-total hardcoding ∨ no i18n machinery despite multi-locale signals in product copy\n- `3`/`0` unreachable by construction","fact_schema":"{\"fe07\": {\n  \"i18n_lib\": null, \"locale_files\": [],\n  \"hardcoded_string_density_pct\": 0.92,\n  \"extraction_pipeline_present\": false}}","budget_class":"fast","evidence":"basis: \"i18n-sweep: lib={bool}; locales={n}; hardcoded {p}% of UI strings\"","remediation":{"quick_win":"adopt an i18n framework + extraction automation, move strings to tokens, ship locale toggling, fix the top market's dates/plurals.","structural":"locale as a first-class runtime concept (RTL, pluralization via ICU, locale-aware formatting/sorting), full-fidelity QA per shipped locale, prune markets served with fake translations until real ones are ready.","gold_standard":"All UI strings extracted, ICU-correct plurals per locale, RTL fully supported, dates/numbers locale-aware, per-locale QA completeness, new code requires tokens (lint-enforced).","effort":"🔷 ~1–2 days"}},
  "FE-08": {"id":"FE-08","category":"FE","name":"Mobile / Responsive Adaptation & Offline Support","tier":"C","default_status":"unknown","effort":"🔷 ~1–2 days","v1":"NO","rollup":"deep-dive","gates":[],"definition":"The client doesn't adapt to the contexts real users are in — no meaningful offline/progressive capability for a product that needs it, heavy always-online dependence, no mobile-specific performance, no low-bandwidth consideration, and state-loss on navigation — while user data (from FE-04/analytics) shows a mobile-first world.","why":"\"Responsive + offline-aware + mobile-perf\" is the modern client baseline; a client that expects a desktop, wired, Chrome-18 machine is building for an audience that has moved. Offline/PWA support matters where connectivity is real (mobile users, tunnels, travel) — and its absence occasionally turns perfectly-normal usage into data loss.","manifests":"No service worker/PWA, forms lose unsaved data on refresh, hard dependency on network for static shell, no mobile perf budget (heavy assets on phones), no manifest/installability, desktop-first flows that collapse on mobile UX, connectivity-agnostic code.","detection":"Context audit — check PWA/service-worker/offline scaffolding existence, form-state persistence across refresh, static-asset CDN/cache behavior, mobile throttled performance (Lighthouse mobile), connectivity-loss experiment (reload while offline), usage analytics (share of mobile/travel context), state-loss bug count tied to navigation.","yellow":"Some offline/progressive features exist, mobile perf over budget, occasional data-loss on network blips.","red":"No offline capability for a product users depend on in real connectivity, data loss on common navigation/refresh, mobile experience broken/unweighted.","yellow_rationale":"warning — the app functions, context-fit is leaky.","red_rationale":"the client loses what real users do — a crisis of context, not of polish.","criteria":{"0":"connectivity-dependent data loss in user-facing flows.","1":"no offline, mobile over budget","2":"partial progression","3":"offline-capable, mobile-fit"},"scope":"Offline/mobile depth; responsive support markers are FE-04's row.","applicability":null,"statusing":"measured_when:  never in v1\nestimated_when: never\nunknown_when:   always in v1\nclamp:          n/a\nconfidence:     n/a","score_mapping":"None in v1.","fact_schema":"{\"fe08\": {\"status\": \"unknown\",\n           \"reason\": \"offline/mobile behavior provable only at runtime\",\n           \"static_hints\": {\"sw_present\": false, \"pwa_manifest\": false}}}","budget_class":null,"evidence":"emission: \"unknown — needs connectivity-loss experiments + throttled device runs (deep scan); SW={bool} PWA={bool}\"","remediation":{"quick_win":"add a service worker + shell caching (static shell offline), persist draft state, cut mobile payload for the core path, cache-first for static assets.","structural":"PWA/progressive economics by design (offline-first where core), mobile perf budget (Lighthouse gate), reconnect/resume semantics (idempotent submit ties into API-09), context-tiered asset serving.","gold_standard":"Core flows work offline (or degrade meaningfully well), draft data survives navigation, mobile perf within budget, progressive capability measured and tracked.","effort":"🔷 ~1–2 days"}},
};

export const CATEGORY_LABELS: Record<string, string> = {
  "ECOS": "Dependency & Ecosystem Health",
  "ARCH": "Architecture & Code Quality",
  "TEST": "Testing & Quality Engineering",
  "SEC": "Security, Compliance & Vulnerability",
  "DATA": "Data & Schema Evolution",
  "API": "API & Integration Surface",
  "VEL": "Developer Velocity & Operational Drag",
  "PERF": "Performance & Cloud/Infrastructure Fit",
  "DOCS": "Documentation & Knowledge Continuity",
  "FE": "Frontend & Client Health",
};

export const CATEGORY_ORDER = ["ECOS","ARCH","TEST","SEC","DATA","API","VEL","PERF","DOCS","FE"] as const;

export type CategoryCharter = { thesis: string; summary: string };
// Authored in docs/rubric/indicators/<NN-slug>/README.md, emitted verbatim.
export const CATEGORY_CHARTERS: Record<string, CategoryCharter> = {
  "ECOS": {"thesis":"Dependencies are a codebase's circulatory system. When the surrounding ecosystem moves faster than the code, every fix, audit, and hire gets harder—and eventually impossible.","summary":"Measures runtime support, dependency freshness and maintenance, license posture, and supply-chain reproducibility. These signals can degrade without code changes as runtimes and dependencies age."},
  "ARCH": {"thesis":"Architecture debt is the shape of the code disagreeing with what the code now needs to do. When the shape is wrong, every future feature is a fight.","summary":"Scores the internal structure of the codebase — complexity, coupling, boundaries, dead code, churn hot spots, architectural era, state hygiene, agentic operability, and config/flag discipline. The highest-weight *engineering* category (15%; 13.5% when the Frontend module is active) because architecture determines whether a system can be modernized incrementally at all — by humans *or* by AI tooling — or must be treated as a rewrite candidate."},
  "TEST": {"thesis":"The test suite is the codebase's immune system. When it weakens, every change becomes a gamble — and the codebase stops being safely modifiable at all.","summary":"Scores the health of the quality engineering function — coverage, reliability, shape (pyramid), speed, and gates. A degraded suite is both a *cause* of modernization difficulty (you can't refactor what you can't verify) and a *symptom* of it (tests decay exactly like production code when unowned)."},
  "SEC": {"thesis":"Security debt is the only debt that can end the company. A codebase that treats security as an afterthought is obsolete in the most literal sense — it belongs to an era we no longer permit.","summary":"The highest-weight category (20%). Scores the system's vulnerability posture, credential hygiene, security controls, auth, auditability, supply-chain safety, patch cadence, and compliance standing. Four gating kill-switches (G1, G2, G4) live here — more than any other category — because security Red Flags cap the modernization verdict."},
  "DATA": {"thesis":"Data is the one thing a legacy codebase can't throw away. When the schema is a museum and the database is a fortress, the code is just the tip of the iceberg — and the data is where modernization gets expensive.","summary":"Scores the data layer's evolvability — migration discipline, database coupling, integrity, storage technology, locking/scaling behavior, lifecycle management, query performance, and model design. A system can have clean code and a *blighted* data layer; this category catches that."},
  "API": {"thesis":"The API is the contract your system makes with the world. When contracts are undocumented, unversioned, and ungoverned, every consumer — internal or external — is at the mercy of the codebase's mood.","summary":"Scores the health of the interfaces between the system and its consumers (internal services, partners, frontends, IoT, third-party SaaS) — formal contracts, versioning, integration topology, coupling, external-dependency risk, protocol currency, error semantics, and consumer visibility."},
  "VEL": {"thesis":"Velocity is where modernization debt pays out every single day — in build time, deploy failures, and the gap between \"how we work\" and \"how we say we work.\" Slow pipelines aren't a pain point; they're a diagnostic.","summary":"Scores the delivery and operational machinery around the code — CI/CD speed and reliability, deploy frequency and failure rate, local dev reproducibility, onboarding friction, knowledge concentration, review discipline, branch strategy, and how much of the release path is automated vs. heroic. DORA-aligned where measurable."},
  "PERF": {"thesis":"The runtime is a verdict on the architecture. A system that leaks memory, can't observe itself, and refuses to scale isn't \"mildly inefficient\" — it's telling you its design era on every request.","summary":"Scores how the system runs under load and how well it fits modern infrastructure expectations — observability, deployment model, resource behavior, scalability, infrastructure-as-code, SLO/perf disciplines, runtime footprint, cost efficiency, and resilience."},
  "DOCS": {"thesis":"Documentation is the difference between a codebase that *is* and a codebase that *can be learned*. In an obsolete system, every question is answered by one person, one memory, or one archaeology session.","summary":"Scores the written knowledge around the codebase — decisions (ADRs), operations (runbooks), onboarding, API surface, changelogs/release communication, and the balance between code comments and self-documenting code. Weighted lowest (5%) because it's amplifyable rather than causal — but it's the category that makes every other debt *discoverable*."},
  "FE": {"thesis":"The frontend is the product's face — and a client that predates its era shows the same decay class as the backend, plus its own: bundles the size of satellites, accessibility scored in single digits, and a framework the ecosystem left behind.","summary":"This module is scored **only if the system has a user-facing client** (web app, mobile, desktop, or embedded UI). If none exists, skip entirely — it is an annex score recorded separately. When a client exists, its ten-indicator score (FE-01…07 × FE-08 deep-dive) carries a separate 10% in the FE-active system rollup while the other nine categories scale ×0.9 (see `model/config.md`). Covers the UI's framework health, performance, accessibility, platform currency, client architecture, design consistency, run-time adaptation, and internationalization."},
};

export type CategoryWeight = { base: number | null; feActive: number | null };
// Canonical source: docs/rubric/model/config.md §1. `base: null` marks a conditional category.
export const CATEGORY_WEIGHTS: Record<string, CategoryWeight> = {
  "ECOS": { base: 10, feActive: 9 },
  "ARCH": { base: 15, feActive: 13.5 },
  "TEST": { base: 10, feActive: 9 },
  "SEC": { base: 20, feActive: 18 },
  "DATA": { base: 10, feActive: 9 },
  "API": { base: 10, feActive: 9 },
  "VEL": { base: 10, feActive: 9 },
  "PERF": { base: 10, feActive: 9 },
  "DOCS": { base: 5, feActive: 4.5 },
  "FE": { base: null, feActive: 10 },
};

export function getIndicatorName(id: string): string {
  const e = INDICATOR_REGISTRY[id];
  if (!e) { console.warn(`Unknown indicator ${id}`); return `Unknown indicator (${id})`; }
  return e.name;
}
export function getIndicatorEffort(id: string): string { return INDICATOR_REGISTRY[id]?.effort ?? "⚡ ≤30 min"; }
export function getIndicatorRemediation(id: string) { return INDICATOR_REGISTRY[id]?.remediation ?? { quick_win: "", structural: "", gold_standard: "", effort: "⚡ ≤30 min" }; }
export function getCategoryName(id: string): string { return CATEGORY_LABELS[id] ?? id; }
